// Content for Know Your Rights (Adult) (node g51, ages 18-22, Chapter 6): NEW v2 build to GDD 51 (mechanic-
// embodying), the College node that CLOSES the chapter by turning the rights work of Justice League (g35) into
// the adult arenas a young adult now enters (Thread G · Values, Rights & Media). Reworks the old ModesEngine
// build onto the shared v2 engine. 84 researched, India-grounded scenarios across rights-at-work →
// harassment-and-posh → renting-and-consumer → cyber-and-data → claim-it → tools-and-help, each encoded as one of
// the shared v2 play actions (branch / strike-rewrite / sort / reflect / match / role-play / spot): no binary
// "tap the right card". Lead: branch (your move), strike-rewrite (bust the myth), match (right -> route). Six
// modes: rights at work (labour, contracts, pay, interns), harassment & POSH (the Internal Committee), renting &
// consumer (tenancy, deposits, goods), cyber & data (fraud, abuse, your data), claim it (UN&RE: 'you can't fight
// the system' -> you can; redress & free legal aid), tools/help. Empowering and practical: knowing your rights
// and the routes to claim them is one of the strongest protections an adult has. EDUCATIONAL, NOT legal advice;
// all law content flagged for expert review, localisation and currency. India: POSH Act 2013 & Internal
// Committees (10+ employees, complaint within 3 months, covers interns), labour/internship & tenancy/deposit
// norms, Consumer Protection Act 2019, cyber rights & DPDP; redress via Internal Committees, police/FIR and free
// legal aid (NALSA, 15100); helplines 181, 1091, 112, 1930, 1098. Builds on g35 (Justice League); pairs g50;
// precedes the c6 capstone. gameId "know-your-rights".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"kr-001","cat":"rights-at-work","type":"strike-rewrite","hook":"\"As a junior or intern, you have no rights at work.\"","myth":{"un":"As a junior or intern, you have no rights at work.","re":"You have basic labour rights regardless of seniority; interns and contract workers are protected too.","why":"Rights don't start only at senior level."},"relearn":"You have basic labour rights regardless of seniority; interns are protected too.","persona":"Meena","source":"rights at any level"},
  {"id":"kr-002","cat":"rights-at-work","type":"sort","hook":"Sort: okay at work, or not okay?","items":[{"id":"a","text":"A contract stating pay, hours and role"},{"id":"b","text":"Being made to work unpaid 'to prove yourself'"},{"id":"c","text":"Being paid on time for work done"},{"id":"d","text":"Wages withheld with no reason"},{"id":"e","text":"A payslip showing your deductions"},{"id":"f","text":"Your originals kept so you can't quit"}],"bins":[{"id":"ok","label":"Okay","valence":"pos"},{"id":"not","label":"Not okay","valence":"neg"}],"key":{"a":"ok","b":"not","c":"ok","d":"not","e":"ok","f":"not"},"relearn":"A clear contract, on-time pay and a payslip are okay; unpaid 'real' work, withheld wages and held originals aren't.","persona":"any","source":"what's okay at work"},
  {"id":"kr-003","cat":"rights-at-work","type":"branch","hook":"A 'job' wants you to do real, full work for free as an extended 'trial'.","options":[{"text":"Recognise that unpaid real work isn't okay and push back","consequence":"You protect your right to be paid.","outcome":"protected","best":true},{"text":"Accept it to seem committed","consequence":"Real work deserves pay; an endless unpaid 'trial' is exploitation, not commitment."}],"debrief":"Doing genuine, ongoing work for free is exploitation; you have a right to be paid.","relearn":"Real work deserves pay; an unpaid 'trial' doing real work isn't okay.","persona":"any","source":"unpaid work"},
  {"id":"kr-004","cat":"rights-at-work","type":"match","hook":"Match the work right to what it means.","pairs":[{"left":"A contract/offer letter","right":"States pay, hours and role"},{"left":"Being paid for work done","right":"A basic labour right"},{"left":"Safe conditions","right":"Owed to every worker"},{"left":"Equal pay","right":"Same work, same pay"},{"left":"Your original documents","right":"Always belong to you"}],"relearn":"A contract states terms; pay-for-work, safety, equal pay and your own documents are basic rights owed to every worker.","persona":"any","source":"work rights"},
  {"id":"kr-005","cat":"rights-at-work","type":"branch","hook":"Your employer keeps 'forgetting' to pay you on time.","options":[{"text":"Keep records and raise it formally; you're owed your wages","consequence":"You assert your right with evidence.","outcome":"asserted","best":true},{"text":"Stay quiet so you're not 'difficult'","consequence":"You're owed your wages; keeping records and raising it formally is your right, not being difficult."}],"debrief":"You have a right to be paid; documenting and formally raising late pay is how you claim it.","relearn":"Keep records and formally raise unpaid or late wages; you're owed them.","persona":"Meena","source":"unpaid wages"},
  {"id":"kr-006","cat":"rights-at-work","type":"sort","hook":"Sort: a real labour-rights protection, or a myth?","items":[{"id":"a","text":"Minimum wage exists"},{"id":"b","text":"Juniors can be paid nothing legally"},{"id":"c","text":"You should have a contract"},{"id":"d","text":"Interns have zero protections"},{"id":"e","text":"Wages are owed for work done"},{"id":"f","text":"Cash pay means no rights at all"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Minimum wage, contracts and wages-for-work are real; 'juniors paid nothing', 'interns unprotected' and 'cash means no rights' are myths.","persona":"any","source":"labour facts"},
  {"id":"kr-007","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If you complain about work conditions, you'll just be fired and that's legal.\"","myth":{"un":"Complaining about conditions means you can be fired, and that's fine.","re":"You have rights to fair treatment and safe conditions; raising them is legitimate.","why":"Workers can assert conditions without forfeiting protection."},"relearn":"You have rights to fair treatment and safe conditions; raising them is legitimate.","persona":"any","source":"raising conditions"},
  {"id":"kr-008","cat":"rights-at-work","type":"reflect","hook":"Lensy: knowing your basic work rights makes you much harder to exploit. Feel that?","prompt":"What do you think?","options":["Yes","Harder to exploit","Knowledge protects"],"affirm":"A worker who knows their rights is far harder to take advantage of; knowledge is protection.","relearn":"Knowing your basic work rights makes you much harder to exploit.","persona":"any","source":"knowledge protects"},
  {"id":"kr-009","cat":"rights-at-work","type":"branch","hook":"You're offered a role with no contract, just a verbal promise.","options":[{"text":"Ask for the terms in writing before starting","consequence":"You protect yourself with a record.","outcome":"documented","best":true},{"text":"Start on a handshake and hope","consequence":"Getting the terms in writing protects you; a verbal-only promise is easy to deny later."}],"debrief":"Written terms protect you; a verbal-only arrangement leaves you exposed.","relearn":"Ask for the terms in writing before starting a job.","persona":"any","source":"get it in writing"},
  {"id":"kr-010","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Workplace harassment is just something you put up with.\"","myth":{"un":"Workplace harassment is something you just put up with.","re":"Sexual harassment at work is illegal, with formal redress under the POSH Act; you never have to just endure it.","why":"The law gives you a real route."},"relearn":"Workplace harassment is illegal; POSH gives you formal redress, you don't just endure it.","persona":"Aarti","source":"never endure it"},
  {"id":"kr-011","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Harassment is the price of having a job.\"","myth":{"un":"Harassment is the price of having a job.","re":"Harassment is never the price of a job; you have a right to a safe, dignified workplace.","why":"Dignity at work is a right, not a favour."},"relearn":"Harassment is never the price of a job; you have a right to safety and dignity at work.","persona":"Meena","source":"not the price"},
  {"id":"kr-012","cat":"harassment-and-posh","type":"match","hook":"Match the POSH basic to what it means.","pairs":[{"left":"Internal Committee (IC)","right":"Where you complain, confidentially"},{"left":"10+ employees","right":"An IC is mandatory"},{"left":"Within 3 months","right":"The window to file (extendable)"},{"left":"Local Committee","right":"For small workplaces without an IC"},{"left":"Interns and contract staff","right":"Also covered by the Act"}],"relearn":"The IC is your confidential route, mandatory at 10+ staff, with a 3-month window; small places use a Local Committee, and interns are covered.","persona":"any","source":"POSH basics"},
  {"id":"kr-013","cat":"harassment-and-posh","type":"branch","hook":"You're being harassed at work and don't know what to do.","options":[{"text":"Document it and complain to the Internal Committee","consequence":"You use the real, confidential redress route.","outcome":"redress","best":true},{"text":"Assume nothing can be done","consequence":"The Internal Committee is a real, confidential route; documenting and complaining to it is how you act."}],"debrief":"The POSH Internal Committee is a confidential, formal route; documenting and complaining is how you use it.","relearn":"Document harassment and complain to the Internal Committee (POSH).","persona":"any","source":"using POSH"},
  {"id":"kr-014","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"If you complain about harassment, they can punish you for it.\"","myth":{"un":"If you complain about harassment, they can punish you.","re":"Retaliation for a good-faith complaint is itself prohibited under the POSH Act.","why":"The law protects complainants from reprisal."},"relearn":"Retaliation for a good-faith harassment complaint is itself prohibited.","persona":"any","source":"no retaliation"},
  {"id":"kr-015","cat":"harassment-and-posh","type":"sort","hook":"Sort: true about the harassment law, or false?","items":[{"id":"a","text":"It covers interns and contract staff"},{"id":"b","text":"It only protects senior women"},{"id":"c","text":"The process is confidential"},{"id":"d","text":"You must just confront them alone"},{"id":"e","text":"You can ask for interim relief"},{"id":"f","text":"Retaliation for complaining is allowed"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"The law covers interns, is confidential and allows interim relief; it isn't only for seniors, a solo confrontation, or open to retaliation.","persona":"any","source":"POSH facts"},
  {"id":"kr-016","cat":"harassment-and-posh","type":"role-play","hook":"A colleague is being harassed and feels powerless.","setup":"Tell them their options. Say:","yourLine":[{"text":"\"This isn't okay and it's not your fault, there's an Internal Committee you can complain to, confidentially.\"","best":true},{"text":"\"Maybe just ignore it.\""}],"relearn":"Tell a harassed colleague it's not their fault and point them to the confidential IC.","persona":"Mehta","source":"supporting a colleague"},
  {"id":"kr-017","cat":"harassment-and-posh","type":"branch","hook":"Your college has no functioning harassment committee that you can find.","options":[{"text":"Know it's legally required, and push for it / use external routes","consequence":"You don't accept the gap as final.","outcome":"persistent","best":true},{"text":"Assume there's no recourse","consequence":"An IC is legally required; push for it or use external routes (police, 181), not a final gap."}],"debrief":"A missing committee doesn't end your rights; it's legally required, and external routes exist.","relearn":"If a committee's missing, push for it or use external routes.","persona":"any","source":"missing committee"},
  {"id":"kr-018","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: knowing the POSH route turns harassment from something you endure into something you can act on. Powerful?","prompt":"What do you think?","options":["Yes","I can act","Not endure"],"affirm":"Knowing the route changes everything: harassment becomes something with a real, claimable remedy.","relearn":"Knowing the POSH route turns harassment into something you can act on.","persona":"any","source":"route to action"},
  {"id":"kr-019","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A landlord can keep your deposit for any reason.\"","myth":{"un":"A landlord can keep your deposit for any reason.","re":"Deposits are returnable minus genuine, documented damages; not at a whim.","why":"A deposit isn't the landlord's to keep arbitrarily."},"relearn":"Deposits are returnable minus genuine, documented damages, not kept at a whim.","persona":"any","source":"deposits"},
  {"id":"kr-020","cat":"renting-and-consumer","type":"branch","hook":"You're moving into a rented room with only a verbal agreement.","options":[{"text":"Get a written rent agreement and document the deposit","consequence":"You protect both sides with a record.","outcome":"documented","best":true},{"text":"Skip the paperwork to keep it simple","consequence":"A written agreement and documented deposit protect you; verbal-only is hard to enforce later."}],"debrief":"A written rent agreement and documented deposit protect you if there's a dispute.","relearn":"Get a written rent agreement and document the deposit.","persona":"any","source":"tenancy basics"},
  {"id":"kr-021","cat":"renting-and-consumer","type":"sort","hook":"Sort: a tenant protection, or a myth?","items":[{"id":"a","text":"A written agreement protects both sides"},{"id":"b","text":"A landlord can evict you instantly, anytime"},{"id":"c","text":"Deposits should be documented"},{"id":"d","text":"Tenants have no rights at all"},{"id":"e","text":"You can ask for an itemised deposit deduction"},{"id":"f","text":"A landlord can keep the deposit for any reason"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Written agreements and documented deposits protect tenants; 'instant eviction' and 'no rights' are myths.","persona":"Meena","source":"tenancy facts"},
  {"id":"kr-022","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"If you bought it and it's faulty, that's just your bad luck.\"","myth":{"un":"If you bought it and it's faulty, that's your bad luck.","re":"Consumer law gives you rights to refund or replacement for defective goods, and a route to complain.","why":"Sellers owe you working goods."},"relearn":"Consumer law gives you a right to refund or replacement for faulty goods.","persona":"any","source":"consumer rights"},
  {"id":"kr-023","cat":"renting-and-consumer","type":"branch","hook":"A shop refuses to refund or replace a clearly defective product.","options":[{"text":"Cite your consumer rights and use the complaint route","consequence":"You assert a real right with a route.","outcome":"asserted","best":true},{"text":"Give up; the shop said no","consequence":"Consumer law backs you on defective goods; cite your rights and use the complaint route, don't give up."}],"debrief":"Consumer protection law and complaint forums exist for refused refunds on faulty goods.","relearn":"Cite your consumer rights and use the complaint route for defective goods.","persona":"any","source":"consumer redress"},
  {"id":"kr-024","cat":"renting-and-consumer","type":"match","hook":"Match the situation to the protection.","pairs":[{"left":"A faulty product","right":"Refund or replacement rights"},{"left":"A rented room","right":"A written agreement"},{"left":"A returnable deposit","right":"Minus documented damages"},{"left":"A signed bill","right":"Proof for a consumer claim"},{"left":"Move-in photos","right":"Evidence on the deposit"}],"relearn":"Consumer law covers faulty goods, a written agreement covers renting, deposits return minus damages.","persona":"any","source":"protections map"},
  {"id":"kr-025","cat":"renting-and-consumer","type":"sort","hook":"Sort: protects you as a renter/consumer, or leaves you exposed?","items":[{"id":"a","text":"Keeping receipts and records"},{"id":"b","text":"Paying cash with no proof"},{"id":"c","text":"A signed agreement"},{"id":"d","text":"Relying on a verbal promise"},{"id":"e","text":"Move-in photos of the room's condition"},{"id":"f","text":"Trusting the seller's word, no bill"}],"bins":[{"id":"protects","label":"Protects","valence":"pos"},{"id":"exposed","label":"Exposed","valence":"neg"}],"key":{"a":"protects","b":"exposed","c":"protects","d":"exposed","e":"protects","f":"exposed"},"relearn":"Receipts, signed agreements and move-in photos protect you; cash-no-proof and verbal promises leave you exposed.","persona":"any","source":"keep records"},
  {"id":"kr-026","cat":"renting-and-consumer","type":"branch","hook":"A landlord withholds your full deposit citing vague 'wear and tear'.","options":[{"text":"Ask for an itemised reason and dispute it with your records","consequence":"You challenge an unfair deduction.","outcome":"challenged","best":true},{"text":"Accept the loss without question","consequence":"Itemised reasons plus your move-in records can recover an unfairly withheld deposit."}],"debrief":"Documented condition and itemised deductions are how you contest an unfair deposit deduction.","relearn":"Ask for itemised reasons and dispute unfair deductions with records.","persona":"any","source":"deposit disputes"},
  {"id":"kr-027","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Online scams and fraud can't really be reported.\"","myth":{"un":"Online scams and fraud can't really be reported.","re":"You can report cyber fraud and crime at cybercrime.gov.in or helpline 1930, and fast reporting helps.","why":"There's a real national reporting route."},"relearn":"Report cyber fraud at cybercrime.gov.in or 1930; fast reporting helps.","persona":"any","source":"cyber reporting"},
  {"id":"kr-028","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If someone shares an intimate image of me, it's partly my fault.\"","myth":{"un":"If an intimate image of me is shared, it's partly my fault.","re":"Image-based abuse is a crime and the fault of the perpetrator, never the victim; it can be reported.","why":"The blame and the crime sit with the abuser."},"relearn":"Image-based abuse is a crime, on the perpetrator, never your fault, and reportable.","persona":"any","source":"image abuse"},
  {"id":"kr-029","cat":"cyber-and-data","type":"branch","hook":"Someone is blackmailing you over private photos.","options":[{"text":"Don't pay; preserve evidence and report to 1930 / cybercrime.gov.in","consequence":"You take the real protective steps.","outcome":"reported","best":true},{"text":"Pay them to make it stop","consequence":"Paying rarely stops blackmail; preserving evidence and reporting to 1930 is the protective move."}],"debrief":"For sextortion or blackmail: don't pay, preserve evidence, and report to cybercrime 1930.","relearn":"Don't pay blackmailers; preserve evidence and report to 1930 / cybercrime.gov.in.","persona":"any","source":"sextortion"},
  {"id":"kr-030","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two false claims about your data rights.","scene":[{"id":"a","text":"You can ask what data is held about you","trick":false},{"id":"b","text":"Apps can do anything with your data, no consent","trick":true},{"id":"c","text":"Your consent matters for your data","trick":false},{"id":"d","text":"You give up all rights the moment you sign up","trick":true},{"id":"e","text":"You can ask for wrong data to be corrected","trick":false}],"why":"'Apps can do anything' and 'you give up all rights' are false; under DPDP your consent and data rights stay yours.","relearn":"Under DPDP your consent matters and you keep rights over your data.","persona":"any","source":"data rights"},
  {"id":"kr-031","cat":"cyber-and-data","type":"match","hook":"Match the online harm to where you report it (India).","pairs":[{"left":"Financial fraud or scam","right":"1930 or cybercrime.gov.in"},{"left":"An intimate image shared","right":"cybercrime.gov.in and a take-down"},{"left":"A child at risk online","right":"Childline 1098"},{"left":"A woman facing online abuse","right":"Women's helpline 181 or 1091"},{"left":"App misusing your data","right":"Your DPDP Act rights"}],"relearn":"Fraud to 1930, image abuse to cybercrime.gov.in, a child to 1098, a woman to 181, data to DPDP.","persona":"any","source":"cyber routes"},
  {"id":"kr-032","cat":"cyber-and-data","type":"branch","hook":"You've been defrauded online and feel embarrassed to report it.","options":[{"text":"Report it fast anyway; speed can help recover money","consequence":"You act despite the embarrassment.","outcome":"acted","best":true},{"text":"Stay silent out of shame","consequence":"Reporting fast (1930) can help freeze and recover funds; shame shouldn't stop you."}],"debrief":"Fast reporting of online fraud (1930) improves the chance of recovering money; shame just delays it.","relearn":"Report online fraud fast (1930); speed can help recover money.","persona":"Meena","source":"fraud no shame"},
  {"id":"kr-033","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Once something bad is online, nothing can ever be done.\"","myth":{"un":"Once something bad is online, nothing can be done.","re":"You can report it, request take-downs, and pursue redress; it's not hopeless.","why":"Reporting routes and take-down rights exist."},"relearn":"Online harms can be reported and taken down; it isn't hopeless.","persona":"any","source":"not hopeless"},
  {"id":"kr-034","cat":"cyber-and-data","type":"sort","hook":"Sort each move after a cyber harm: smart, or not?","items":[{"id":"a","text":"Preserving screenshots and evidence"},{"id":"b","text":"Deleting everything in a panic"},{"id":"c","text":"Reporting to 1930 quickly"},{"id":"d","text":"Paying a blackmailer"},{"id":"e","text":"Asking the platform to take it down"},{"id":"f","text":"Blaming yourself and going silent"}],"bins":[{"id":"smart","label":"Smart","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"smart","b":"not","c":"smart","d":"not","e":"smart","f":"not"},"relearn":"Preserve evidence, report fast and ask for take-down; panic-deleting, paying or self-blame don't help.","persona":"any","source":"after a cyber harm"},
  {"id":"kr-035","cat":"claim-it","type":"strike-rewrite","hook":"\"You can't fight the system; ordinary people just lose.\"","myth":{"un":"You can't fight the system; ordinary people just lose.","re":"There are real, reachable routes to redress, and knowing them shifts the odds.","why":"Rights are useless unknown, powerful when used."},"relearn":"There are real, reachable routes to redress; knowing them shifts the odds.","persona":"any","source":"you can claim it"},
  {"id":"kr-036","cat":"claim-it","type":"strike-rewrite","hook":"\"You need money and connections to claim your rights.\"","myth":{"un":"You need money and connections to claim your rights.","re":"Free legal aid (NALSA, helpline 15100) exists for anyone who can't afford a lawyer.","why":"Justice isn't only for those who can pay."},"relearn":"Free legal aid (NALSA, 15100) exists for those who can't afford a lawyer.","persona":"Meena","source":"free legal aid"},
  {"id":"kr-037","cat":"claim-it","type":"strike-rewrite","hook":"\"The police can just refuse to register your complaint.\"","myth":{"un":"The police can just refuse to register your complaint.","re":"For a serious (cognizable) offence, registering an FIR is mandatory; a Zero FIR can be filed at any station.","why":"The law requires it for serious offences."},"relearn":"For a serious offence an FIR is mandatory; a Zero FIR can be filed at any station.","persona":"any","source":"FIR / Zero FIR"},
  {"id":"kr-038","cat":"claim-it","type":"match","persona":"any","source":"redress routes","hook":"Match the need to the redress route (India).","pairs":[{"left":"Workplace harassment","right":"The Internal Committee"},{"left":"A serious offence","right":"An FIR (Zero FIR anywhere)"},{"left":"Can't afford a lawyer","right":"Free legal aid via NALSA 15100"},{"left":"A faulty product, no refund","right":"The consumer commission"},{"left":"Online fraud or image abuse","right":"Cyber helpline 1930"}],"relearn":"Each problem has a real route: the Internal Committee, an FIR, NALSA free legal aid, the consumer commission, or cyber 1930."},
  {"id":"kr-039","cat":"claim-it","type":"branch","hook":"You have a real grievance but assume pursuing it is pointless.","options":[{"text":"Find the right route and use it; rights are claimable","consequence":"You turn a grievance into action.","outcome":"acted","best":true},{"text":"Drop it, assuming nothing will change","consequence":"Finding the right route (IC, FIR, free legal aid) turns a grievance into action; 'pointless' is the myth."}],"debrief":"Most rights have a real route to claim them; finding and using it is how change happens.","relearn":"Find the right route and use it; rights are claimable, not pointless.","persona":"any","source":"taking action"},
  {"id":"kr-040","cat":"claim-it","type":"reflect","hook":"Lensy: knowing the routes, free legal aid, the IC, the FIR, means you're never as powerless as it feels. Land?","prompt":"What do you think?","options":["Yes","Not powerless","I know the routes"],"affirm":"Knowing the routes means you always have somewhere to turn; you're far from powerless.","relearn":"Knowing the redress routes means you're never as powerless as it feels.","persona":"any","source":"never powerless"},
  {"id":"kr-041","cat":"claim-it","type":"role-play","hook":"A friend won't pursue a clear rights violation because they can't afford a lawyer.","relearn":"Tell people who can't afford a lawyer about free legal aid (NALSA, 15100).","persona":"any","source":"sharing the route","setup":"Open a door for them. Say:","yourLine":[{"text":"\"There's free legal aid, NALSA, helpline 15100, cost doesn't have to stop you.\"","best":true},{"text":"\"Yeah, without money it's hopeless.\""}]},
  {"id":"kr-042","cat":"claim-it","type":"sort","persona":"any","source":"routes vs dead ends","hook":"Sort: a real route to redress, or a dead end?","items":[{"id":"a","text":"An Internal Committee complaint"},{"id":"b","text":"Just hoping it resolves itself"},{"id":"c","text":"Filing an FIR for a serious offence"},{"id":"d","text":"Assuming you have no options"},{"id":"e","text":"Asking NALSA for free legal aid"},{"id":"f","text":"Staying silent because you feel small"}],"bins":[{"id":"route","label":"Real route","valence":"pos"},{"id":"deadend","label":"Dead end","valence":"neg"}],"key":{"a":"route","b":"deadend","c":"route","d":"deadend","e":"route","f":"deadend"},"relearn":"An IC complaint, an FIR, and asking NALSA for aid are real routes; hoping, assuming no options, or staying silent are dead ends."},
  {"id":"kr-043","cat":"claim-it","type":"role-play","hook":"You need to ask where to get free legal help for a rights issue.","setup":"Ask plainly; it's your right. Say:","yourLine":[{"text":"\"I can't afford a lawyer, how do I access free legal aid through the Legal Services Authority?\"","best":true},{"text":"Assume free help isn't really available"}],"relearn":"You can plainly ask for free legal aid; it's a right, not a favour.","persona":"any","source":"asking for aid"},
  {"id":"kr-044","type":"match","persona":"any","source":"helplines","relearn":"181/1091 women in distress, 112 danger, 1930 cyber harm, 1098 child at risk, 15100 free legal aid.","hook":"Match the need to the helpline (India).","pairs":[{"left":"A woman in distress","right":"181 / 1091"},{"left":"Immediate danger","right":"112"},{"left":"Cyber fraud or abuse","right":"1930"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Can't afford a lawyer","right":"NALSA 15100"}],"cat":"tools-and-help"},
  {"id":"kr-045","type":"sort","persona":"any","source":"reliable resources","relearn":"Legal Services Authorities and the cyber portal are reliable; forwards and guesses aren't.","hook":"Sort: a reliable rights resource, or not?","items":[{"id":"a","text":"A Legal Services Authority"},{"id":"b","text":"A random WhatsApp forward"},{"id":"c","text":"The cybercrime portal"},{"id":"d","text":"A stranger's confident guess"},{"id":"e","text":"A qualified lawyer"},{"id":"f","text":"A scary unverified screenshot"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-046","cat":"tools-and-help","type":"reflect","hook":"Lensy: this is education, not legal advice, so for a real case, get qualified or free legal help. Clear?","prompt":"What do you think?","options":["Yes","Get qualified help","Makes sense"],"affirm":"Treating this as solid grounding, and getting qualified or free legal help for real cases, is exactly right.","relearn":"This is education, not legal advice; for a real case, get qualified or free legal help.","persona":"any","source":"not legal advice"},
  {"id":"kr-047","cat":"tools-and-help","type":"role-play","hook":"A friend faces a rights issue and doesn't know where to start.","relearn":"Point a friend with a rights issue to the right route and a helpline.","persona":"Farhan","source":"helping others","setup":"Give them a first step. Say:","yourLine":[{"text":"\"Here's the route, and a helpline you can call, you don't have to figure it out alone.\"","best":true},{"text":"\"Just let it go.\""}]},
  {"id":"kr-048","type":"match","persona":"any","source":"myth to truth","relearn":"Interns have rights, harassment has redress, free legal aid exists, and the system can be navigated.","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"\"Interns have no rights\"","right":"Basic labour rights apply"},{"left":"\"Just endure harassment\"","right":"There's a formal redress route"},{"left":"\"Need money for justice\"","right":"Free legal aid exists"},{"left":"\"Scams can't be reported\"","right":"1930 and the cyber portal exist"},{"left":"\"You can't fight the system\"","right":"Real routes shift the odds"}],"cat":"tools-and-help"},
  {"id":"kr-049","cat":"tools-and-help","type":"reflect","hook":"Lensy: rights you know are rights you can use, that's the whole point of this. Carry it?","prompt":"What do you think?","options":["Yes","Know to use","The whole point"],"affirm":"Rights you know are rights you can use; that knowledge is one of the strongest protections you have.","relearn":"Rights you know are rights you can use; that's your strongest protection.","persona":"any","source":"the point"},
  {"id":"kr-050","type":"spot","persona":"any","source":"accurate rights","relearn":"Harassment redress and free legal aid are real; 'no rights as a junior' and 'need money' are false.","hook":"Spot the two FALSE lines (tap the wrong ones).","scene":[{"id":"a","text":"\"Harassment has a formal redress route\"","trick":false},{"id":"b","text":"\"You have no rights as a junior\"","trick":true},{"id":"c","text":"\"Free legal aid exists if you can't pay\"","trick":false},{"id":"d","text":"\"You need money to be heard at all\"","trick":true},{"id":"e","text":"\"Online scams can be reported\"","trick":false}],"why":"'No rights as a junior' and 'you need money' are the myths; the rest are real routes.","cat":"tools-and-help"},
  {"id":"kr-051","cat":"tools-and-help","type":"reflect","hook":"Lensy: which right or route do you most want to remember?","prompt":"Pick one.","options":["Work rights","The POSH route","Consumer/cyber redress","Free legal aid"],"affirm":"Carry that one, and you've got a real protection ready when you, or a friend, needs it.","relearn":"Work rights, the POSH route, consumer/cyber redress, and free legal aid, keep one ready.","persona":"any","source":"consolidation"},
  {"id":"kr-052","cat":"rights-at-work","type":"role-play","hook":"Your boss pressures you to work far beyond agreed hours, unpaid.","setup":"Hold the line, politely. Say:","yourLine":[{"text":"\"I'm happy to help, but extra hours need to be agreed and paid as per my terms.\"","best":true},{"text":"Just do it silently to avoid trouble"}],"relearn":"You can politely hold the line that extra work should be agreed and paid.","persona":"any","source":"overwork"},
  {"id":"kr-053","cat":"harassment-and-posh","type":"branch","hook":"You witness a colleague being harassed by a senior.","options":[{"text":"Support them and note what you saw as a potential witness","consequence":"You strengthen any future complaint.","outcome":"witness","best":true},{"text":"Look away; not your problem","consequence":"Supporting them and noting what you saw can strengthen a POSH complaint; bystanding doesn't help."}],"debrief":"Witness support and accounts can strengthen a harassment complaint; being an active bystander matters.","relearn":"Support a harassed colleague and note what you witnessed.","persona":"Rohan","source":"witness support"},
  {"id":"kr-054","cat":"renting-and-consumer","type":"branch","hook":"An online seller delivers a fake product and stops responding.","options":[{"text":"Use consumer complaint routes and report the fraud","consequence":"You pursue a real remedy.","outcome":"pursued","best":true},{"text":"Write it off as a loss","consequence":"Consumer complaint routes and fraud reporting (1930) pursue a real remedy, better than writing it off."}],"debrief":"Fake-product fraud has both consumer and cyber routes; you don't just absorb the loss.","relearn":"Use consumer routes and report fraud for fake products; don't just absorb the loss.","persona":"any","source":"online fraud"},
  {"id":"kr-055","cat":"cyber-and-data","type":"branch","hook":"An app demands far more data and permissions than it needs.","options":[{"text":"Decline the unnecessary permissions; your data is yours","consequence":"You exercise your data rights.","outcome":"private","best":true},{"text":"Allow everything by default","consequence":"You can decline unnecessary permissions; your consent and your data are yours under DPDP."}],"debrief":"You have a right to control your data; declining unnecessary permissions is exercising it.","relearn":"Decline unnecessary app permissions; your consent and data are yours.","persona":"any","source":"data control"},
  {"id":"kr-056","cat":"claim-it","type":"strike-rewrite","hook":"\"The law is too complicated for someone like me to understand.\"","myth":{"un":"The law is too complicated for me to understand.","re":"The core protections can be put in plain language anyone can use.","why":"You don't need to be a lawyer to know your basic rights."},"relearn":"The core protections can be put in plain language anyone can use.","persona":"Meena","source":"plain language"},
  {"id":"kr-057","cat":"rights-at-work","type":"sort","hook":"Sort: a fair internship, or exploitation dressed as one?","items":[{"id":"a","text":"Real learning, fair stipend, set hours"},{"id":"b","text":"Full unpaid work indefinitely"},{"id":"c","text":"A clear agreement"},{"id":"d","text":"'Pay' that never arrives"},{"id":"e","text":"A named mentor and end date"},{"id":"f","text":"Covering a paid staff job for free"}],"bins":[{"id":"fair","label":"Fair internship","valence":"pos"},{"id":"exploit","label":"Exploitation","valence":"neg"}],"key":{"a":"fair","b":"exploit","c":"fair","d":"exploit","e":"fair","f":"exploit"},"relearn":"Learning, a fair stipend, clear terms and a mentor make it fair; endless unpaid work, vanishing pay or free job-cover is exploitation.","persona":"Deepak","source":"internships"},
  {"id":"kr-058","cat":"harassment-and-posh","type":"role-play","hook":"A colleague blames themselves for being harassed.","relearn":"Harassment is never your fault; the law is on your side.","persona":"any","source":"on your side","setup":"Set them straight, gently. Say:","yourLine":[{"text":"\"It's not your fault, and the law is on your side, not theirs.\"","best":true},{"text":"\"Maybe you misread it.\""}]},
  {"id":"kr-059","cat":"renting-and-consumer","type":"spot","hook":"Spot the two risky moves before signing a lease.","relearn":"Read what you sign and never leave blanks empty; question unfair clauses.","persona":"any","source":"read before signing","scene":[{"id":"a","text":"Reading and understanding the terms","trick":false},{"id":"b","text":"Signing blind to save time","trick":true},{"id":"c","text":"Questioning an unfair clause","trick":false},{"id":"d","text":"Keeping your signed copy","trick":false},{"id":"e","text":"Signing a page with blank amounts left empty","trick":true}],"why":"Signing blind and leaving blank amounts let terms change later; reading and questioning protect you."},
  {"id":"kr-060","cat":"cyber-and-data","type":"sort","hook":"Sort each line: you have rights and routes, or a lawless-zone myth?","relearn":"You have real rights and routes online; 'the internet is lawless for you' is a myth.","persona":"any","source":"rights online","items":[{"id":"a","text":"Reporting online fraud to 1930"},{"id":"b","text":"Assuming the internet is lawless for you"},{"id":"c","text":"Exercising your data rights under DPDP"},{"id":"d","text":"Believing nothing online can be acted on"},{"id":"e","text":"Asking a platform to take down abuse"},{"id":"f","text":"Thinking only big people can complain"}],"bins":[{"id":"rights","label":"You have rights","valence":"pos"},{"id":"lawless","label":"Lawless myth","valence":"neg"}],"key":{"a":"rights","b":"lawless","c":"rights","d":"lawless","e":"rights","f":"lawless"}},
  {"id":"kr-061","cat":"claim-it","type":"branch","hook":"You're unsure whether your situation is 'serious enough' to act on.","options":[{"text":"Check the route; you can ask without committing to anything","consequence":"You get clarity with no downside.","outcome":"informed","best":true},{"text":"Assume it's not worth bothering","consequence":"You can ask about routes (free legal aid, an IC) without committing; clarity has no downside."}],"debrief":"Asking about your options costs nothing and commits you to nothing; it just gives clarity.","relearn":"You can ask about your rights and routes without committing to anything.","persona":"any","source":"just ask"},
  {"id":"kr-062","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If you're paid in cash off the books, you have no rights.\"","myth":{"un":"If you're paid in cash off the books, you have no rights.","re":"You still have rights as a worker; off-the-books pay is a warning sign, not a loss of your protections.","why":"Informal pay doesn't erase labour rights."},"relearn":"Off-the-books cash pay doesn't erase your rights; it's a warning sign.","persona":"Meena","source":"informal work"},
  {"id":"kr-063","cat":"harassment-and-posh","type":"sort","hook":"Sort: a step that helps a harassment complaint, or hinders it?","items":[{"id":"a","text":"Documenting incidents with dates"},{"id":"b","text":"Deleting all the evidence"},{"id":"c","text":"Complaining within the time window"},{"id":"d","text":"Telling no one and waiting years"},{"id":"e","text":"Saving messages and emails"},{"id":"f","text":"Confronting the harasser alone, no record"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hinders","label":"Hinders","valence":"neg"}],"key":{"a":"helps","b":"hinders","c":"helps","d":"hinders","e":"helps","f":"hinders"},"relearn":"Documenting, complaining in the window and saving messages help; deleting evidence, long delay or a no-record solo confrontation hinder.","persona":"any","source":"strong complaint"},
  {"id":"kr-064","cat":"renting-and-consumer","type":"spot","hook":"Spot the two rental-scam signs.","relearn":"Verify before paying; upfront deposits for unseen rentals are a common scam.","persona":"any","source":"rental scams","scene":[{"id":"a","text":"A big deposit demanded before you've seen the place","trick":true},{"id":"b","text":"Viewing first, then a documented agreement","trick":false},{"id":"c","text":"Pressure to pay instantly to 'secure' it","trick":true},{"id":"d","text":"A receipt for any money you hand over","trick":false},{"id":"e","text":"Meeting the actual owner before paying","trick":false}],"why":"Big upfront deposits for unseen places and instant-pay pressure are rental-scam signs."},
  {"id":"kr-065","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two moves that are NOT cyber-rights-aware.","scene":[{"id":"a","text":"Reporting fraud to 1930 quickly","trick":false},{"id":"b","text":"Paying a blackmailer to stay quiet","trick":true},{"id":"c","text":"Preserving evidence before reporting","trick":false},{"id":"d","text":"Deleting all the proof in a panic","trick":true},{"id":"e","text":"Asking the platform to take content down","trick":false}],"why":"Paying a blackmailer and deleting your proof both help the abuser; report fast and preserve evidence instead.","relearn":"Report fast and preserve evidence; don't pay blackmailers or delete proof.","persona":"any","source":"cyber-aware"},
  {"id":"kr-066","cat":"claim-it","type":"reflect","hook":"Lensy: a young adult who knows their rights and the routes is genuinely harder to exploit. Feel equipped?","prompt":"What do you think?","options":["Yes","Equipped","Harder to exploit"],"affirm":"Knowing your rights and the routes to claim them is real, practical protection; you're equipped.","relearn":"Knowing your rights and the routes makes you genuinely harder to exploit.","persona":"any","source":"equipped"},
  {"id":"kr-067","cat":"rights-at-work","type":"branch","hook":"You're asked to sign a contract with terms that seem unfair.","options":[{"text":"Read it, question unfair terms, and seek advice before signing","consequence":"You protect yourself from a bad deal.","outcome":"careful","best":true},{"text":"Sign quickly to get the job","consequence":"Reading, questioning unfair terms and seeking advice protects you; signing blind can trap you."}],"debrief":"Questioning unfair contract terms and getting advice before signing is basic self-protection.","relearn":"Read, question unfair terms, and seek advice before signing a contract.","persona":"any","source":"contracts"},
  {"id":"kr-068","cat":"harassment-and-posh","type":"spot","hook":"Spot the two claims that wrongly shrink what harassment is.","scene":[{"id":"a","text":"Unwelcome comments or messages can count","trick":false},{"id":"b","text":"Only physical acts count","trick":true},{"id":"c","text":"A hostile environment can count","trick":false},{"id":"d","text":"A 'joke' can never be harassment","trick":true},{"id":"e","text":"Demanding sexual favours counts","trick":false}],"why":"'Only physical acts' and 'a joke can never count' wrongly shrink it; comments, a hostile environment and demands all count.","relearn":"Comments, a hostile environment and demands all count; not only physical acts, and a 'joke' isn't automatically safe.","persona":"any","source":"what counts"},
  {"id":"kr-069","cat":"renting-and-consumer","type":"match","hook":"Match the record to the protection it gives.","pairs":[{"left":"A signed rent agreement","right":"Proof of your terms"},{"left":"Move-in photos","right":"Evidence for your deposit"},{"left":"Receipts","right":"Proof for consumer claims"},{"left":"A deposit slip","right":"Proof of what you paid"},{"left":"Chat where rent was agreed","right":"A record of the promise"}],"relearn":"Agreements, photos, receipts and slips each give concrete proof if there's a dispute.","persona":"any","source":"keeping proof"},
  {"id":"kr-070","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Sharing my passwords with a partner proves trust and is harmless.\"","myth":{"un":"Sharing all my passwords proves trust and is harmless.","re":"Your accounts and data are yours; sharing everything can enable control or misuse, trust doesn't require it.","why":"Privacy and trust can coexist."},"relearn":"Your accounts and data are yours; trust doesn't require handing over all access.","persona":"any","source":"data and trust"},
  {"id":"kr-071","cat":"claim-it","type":"role-play","hook":"You want to help your community know their rights better.","relearn":"Share plain-language rights and routes; it spreads real protection.","persona":"Farhan","source":"spreading knowledge","setup":"Pass it on plainly. Say:","yourLine":[{"text":"\"Let me share the rights and routes I've learned, in plain terms, so you can use them.\"","best":true},{"text":"Keep it to yourself"}]},
  {"id":"kr-072","type":"sort","persona":"any","source":"the card","relearn":"The redress route and free legal aid are on the card; 'put up with it' and 'no options' aren't.","hook":"Sort: in the rights & helpline card, or not?","items":[{"id":"a","text":"The Internal Committee route"},{"id":"b","text":"\"Just put up with it\""},{"id":"c","text":"Free legal aid (15100)"},{"id":"d","text":"\"You have no options\""},{"id":"e","text":"Cyber harm: 1930"},{"id":"f","text":"\"Don't bother, you'll lose\""}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"card","b":"not","c":"card","d":"not","e":"card","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-073","cat":"rights-at-work","type":"reflect","hook":"Lensy: you deserve fair pay, safe conditions and dignity at work, always. Believe that for yourself?","prompt":"What do you think?","options":["Yes","I deserve it","Always"],"affirm":"Fair pay, safe conditions and dignity at work are yours by right; never settle below them.","relearn":"You deserve fair pay, safe conditions and dignity at work, always.","persona":"any","source":"you deserve"},
  {"id":"kr-074","cat":"harassment-and-posh","type":"branch","hook":"You filed a POSH complaint and worry about facing them daily.","options":[{"text":"Ask the committee about interim relief and confidentiality","consequence":"You use the process's built-in protections.","outcome":"protected","best":true},{"text":"Withdraw it to avoid the discomfort","consequence":"The committee can offer interim relief and confidentiality; you needn't endure it."}],"debrief":"The POSH process includes confidentiality and interim measures; ask the committee.","relearn":"After filing, ask about interim relief and confidentiality.","persona":"any","source":"interim relief"},
  {"id":"kr-075","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: a written record is your best friend in any rent or consumer dispute. Worth the habit?","prompt":"What do you think?","options":["Yes","Keep records","Worth it"],"affirm":"Records and receipts quietly win disputes; it's a small habit with big protection.","relearn":"A written record is your best protection in rent and consumer disputes.","persona":"any","source":"records win"},
  {"id":"kr-076","cat":"cyber-and-data","type":"match","hook":"Match the cyber harm to the first right move.","pairs":[{"left":"Sextortion / blackmail","right":"Don't pay; preserve evidence; report"},{"left":"Account hacked","right":"Secure it and report"},{"left":"Data misused","right":"Exercise your DPDP rights"},{"left":"Intimate image shared","right":"Demand takedown; report cybercrime"},{"left":"Impersonation profile","right":"Report the fake to the platform"}],"relearn":"Don't-pay-and-report for blackmail, secure-and-report for hacks, DPDP rights for data misuse, takedown for leaked images, platform-report for impersonation.","persona":"any","source":"first moves"},
  {"id":"kr-077","cat":"claim-it","type":"sort","persona":"any","source":"claiming well","hook":"Sort: makes claiming a right easier, or harder?","items":[{"id":"a","text":"Knowing the route and helpline"},{"id":"b","text":"Believing you have no options"},{"id":"c","text":"Keeping evidence and dates"},{"id":"d","text":"Waiting until the deadline passes"},{"id":"e","text":"Writing down exactly what happened"},{"id":"f","text":"Deleting the messages out of shame"}],"bins":[{"id":"easier","label":"Easier","valence":"pos"},{"id":"harder","label":"Harder","valence":"neg"}],"key":{"a":"easier","b":"harder","c":"easier","d":"harder","e":"easier","f":"harder"},"relearn":"Knowing the route, keeping evidence, and writing it down make claiming easier; defeatism, missed deadlines, and deleting proof make it harder."},
  {"id":"kr-078","cat":"tools-and-help","type":"branch","hook":"You're not sure which authority handles your specific issue.","options":[{"text":"Start with a helpline or legal-aid clinic; they'll direct you","consequence":"You get pointed to the right place.","outcome":"directed","best":true},{"text":"Give up because it's confusing","consequence":"A helpline or legal-aid clinic will direct you to the right authority; confusion isn't a dead end."}],"debrief":"When unsure of the route, a helpline or legal-aid clinic can point you to the right authority.","relearn":"Unsure of the route? A helpline or legal-aid clinic will direct you.","persona":"any","source":"where to start"},
  {"id":"kr-079","cat":"rights-at-work","type":"match","hook":"Match the workplace problem to a first step.","pairs":[{"left":"Unpaid wages","right":"Document and formally claim"},{"left":"Harassment","right":"The Internal Committee"},{"left":"Unsafe conditions","right":"Raise it; it's your right"},{"left":"No contract","right":"Ask for terms in writing"},{"left":"Held-back originals","right":"Request them back in writing"}],"relearn":"Document unpaid wages, use the Internal Committee for harassment, raise unsafe work, ask for written terms, request held originals back.","persona":"any","source":"first steps at work"},
  {"id":"kr-080","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: the POSH process exists so you never have to choose between your job and your dignity. Reassuring?","prompt":"What do you think?","options":["Yes","Both protected","Reassuring"],"affirm":"You shouldn't have to trade dignity for a job; POSH exists precisely so you don't.","relearn":"POSH exists so you never have to choose between your job and your dignity.","persona":"any","source":"job and dignity"},
  {"id":"kr-081","cat":"cyber-and-data","type":"role-play","hook":"A friend is being harassed online and feels it's not 'serious enough' to report.","relearn":"Online harassment is reportable; show a friend the route (cybercrime.gov.in, 1930).","persona":"any","source":"online harassment","setup":"Validate and guide. Say:","yourLine":[{"text":"\"Online harassment is real and reportable, cybercrime.gov.in or 1930, want help doing it?\"","best":true},{"text":"\"It's probably nothing.\""}]},
  {"id":"kr-082","cat":"claim-it","type":"reflect","hook":"Lensy: 'you can't fight the system' is the lie that keeps people unprotected. Reject it?","prompt":"What do you think?","options":["Yes","Reject the lie","I can claim it"],"affirm":"Rejecting 'you can't fight the system' is the first step to actually using the rights you have.","relearn":"'You can't fight the system' is the lie that keeps people unprotected; reject it.","persona":"any","source":"reject the lie"},
  {"id":"kr-083","type":"spot","persona":"any","source":"knowledge is power","relearn":"Knowing your rights changes what you accept and lets you protect others; 'no difference' is false.","hook":"Spot the two FALSE statements about knowing your rights.","scene":[{"id":"a","text":"\"It changes what you accept and how you act\"","trick":false},{"id":"b","text":"\"It makes no real difference\"","trick":true},{"id":"c","text":"\"It helps you protect others too\"","trick":false},{"id":"d","text":"\"Only lawyers can ever use it\"","trick":true},{"id":"e","text":"\"It makes you harder to exploit\"","trick":false}],"why":"'No difference' and 'only lawyers can use it' are false; knowing your rights changes a lot.","cat":"tools-and-help"},
  {"id":"kr-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: work, harassment, renting, online, you now know your rights and the routes. Carry which forward?","prompt":"Pick one.","options":["Rights at work","The POSH route","Consumer & cyber redress","Free legal aid"],"affirm":"Carry that forward, and you close Chapter 6 as an adult who's genuinely hard to exploit, and ready to help others.","relearn":"Work rights, POSH, consumer & cyber redress, and free legal aid, carry your rights forward.","persona":"any","source":"carry forward"},
  {"id":"kr-900","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"FIR is mandatory","hook":"\"The station can just turn you away for a serious crime.\"","myth":{"un":"The station can just turn you away for a serious crime.","re":"For a serious (cognizable) offence, registering an FIR is mandatory, the police don't get to decide.","why":"The law makes it a duty, not a favour."},"relearn":"For a serious offence, registering an FIR is mandatory; the police can't lawfully refuse."},
  {"id":"kr-901","cat":"claim-it","type":"strike-rewrite","persona":"Meena","source":"Zero FIR anywhere","hook":"\"It happened in another city, so no station here will take it.\"","myth":{"un":"It happened in another city, so no station here will take it.","re":"A Zero FIR can be filed at any station regardless of where it happened; they transfer it on.","why":"Jurisdiction is their job to sort, not your barrier."},"relearn":"A Zero FIR can be filed at any police station; jurisdiction is sorted out later, not by you."},
  {"id":"kr-902","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"aid is a right","hook":"\"Free legal aid is just for the very poorest, not someone like me.\"","myth":{"un":"Free legal aid is just for the very poorest, not someone like me.","re":"Free legal aid covers anyone who can't afford a lawyer, via NALSA helpline 15100.","why":"It's a right under the Constitution, not charity."},"relearn":"Free legal aid via NALSA 15100 is for anyone who can't afford a lawyer, not only the poorest."},
  {"id":"kr-903","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"no bribe needed","hook":"\"You'll have to pay someone off to even get a complaint moving.\"","myth":{"un":"You'll have to pay someone off to even get a complaint moving.","re":"Filing a complaint or an FIR costs nothing; no payment is required to start.","why":"Access to redress is meant to be free at the door."},"relearn":"Filing a complaint or an FIR is free; you never have to pay to start the process."},
  {"id":"kr-904","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"deadlines not forever","hook":"\"There's no rush, I can always complain whenever I get around to it.\"","myth":{"un":"There's no rush, I can always complain whenever I get around to it.","re":"Many routes have time limits, so acting sooner keeps your options open.","why":"Evidence fades and some windows close."},"relearn":"Many routes have time limits; acting sooner keeps your options open and your evidence fresh."},
  {"id":"kr-905","cat":"claim-it","type":"strike-rewrite","persona":"Meena","source":"language is no barrier","hook":"\"I can't claim anything because everything's in English and legalese.\"","myth":{"un":"I can't claim anything because everything's in English and legalese.","re":"You can complain in your own language, and legal aid services can help you put it in writing.","why":"The route is meant to be reachable, not gated by language."},"relearn":"You can complain in your own language; free legal aid can help you put it in writing."},
  {"id":"kr-906","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"copy of the FIR","hook":"\"Once you file, they keep everything and you get nothing back.\"","myth":{"un":"Once you file, they keep everything and you get nothing back.","re":"You're entitled to a free copy of the FIR you file, keep it safe.","why":"It's your record of what you reported."},"relearn":"You're entitled to a free copy of any FIR you file; keep it as your record."},
  {"id":"kr-907","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"complaint is not a court case","hook":"\"Asking about my rights means I've started some huge court battle.\"","myth":{"un":"Asking about my rights means I've started some huge court battle.","re":"Asking about routes or getting advice commits you to nothing; you stay in control of next steps.","why":"Information is not a lawsuit."},"relearn":"Asking about your rights or getting advice commits you to nothing; you decide each next step."},
  {"id":"kr-908","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"write it down","hook":"\"Nobody will believe me, so why even keep proof.\"","myth":{"un":"Nobody will believe me, so why even keep proof.","re":"Saving messages, dates, and a written account makes any complaint far stronger.","why":"A clear record speaks for you when memory won't."},"relearn":"Saving messages, dates, and a written account of what happened makes any complaint far stronger."},
  {"id":"kr-909","cat":"claim-it","type":"strike-rewrite","persona":"Farhan","source":"routes are shareable","hook":"\"Knowing your rights only helps clever, well-connected people.\"","myth":{"un":"Knowing your rights only helps clever, well-connected people.","re":"The routes are plain and the same for everyone; sharing them spreads real protection.","why":"Knowledge of the route is the leveller."},"relearn":"The redress routes are plain and the same for everyone; sharing them spreads real protection."},
  {"id":"kr-910","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"helpline first step","hook":"\"You need a lawyer before you can even ask a single question.\"","myth":{"un":"You need a lawyer before you can even ask a single question.","re":"A helpline like NALSA 15100 can point you to the right route before you ever hire anyone.","why":"The first step is a phone call, not a fee."},"relearn":"A helpline like NALSA 15100 can point you to the right route before you ever need to hire a lawyer."},
  {"id":"kr-911","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"retaliation is not allowed","hook":"\"If I complain at work they can just fire me for it.\"","myth":{"un":"If I complain at work they can just fire me for it.","re":"Punishing you for a good-faith complaint is itself prohibited, not a normal consequence.","why":"Retaliation is treated as a separate wrong."},"relearn":"Punishing you for a good-faith complaint is itself prohibited; retaliation is a separate wrong."},
  {"id":"kr-912","cat":"claim-it","type":"strike-rewrite","persona":"any","source":"no outcome promised but route real","hook":"\"There's no point unless someone guarantees I'll win.\"","myth":{"un":"There's no point unless someone guarantees I'll win.","re":"No honest route promises a win, but using one gives you a real, fair chance you don't get by staying silent.","why":"A fair process beats no process."},"relearn":"No honest route guarantees a win, but using one gives you a real, fair chance silence never does."},
  {"id":"kr-913","cat":"claim-it","type":"match","persona":"any","source":"who does what","hook":"Match each redress route to what it's for (India).","pairs":[{"left":"NALSA / 15100","right":"Free lawyer if you can't pay"},{"left":"Zero FIR","right":"Report a crime at any station"},{"left":"Internal Committee","right":"A workplace harassment complaint"},{"left":"Consumer commission","right":"A refund for a defective product"},{"left":"Cyber helpline 1930","right":"Report online fraud or abuse"}],"relearn":"NALSA gives a free lawyer, a Zero FIR reports a crime anywhere, the IC handles harassment, the consumer commission handles goods, and 1930 handles cyber harm."},
  {"id":"kr-914","cat":"claim-it","type":"match","persona":"any","source":"myth to truth","hook":"Match each defeatist line to the truth that answers it.","pairs":[{"left":"Police can refuse my FIR","right":"It's mandatory for a serious offence"},{"left":"I can't afford justice","right":"Free legal aid exists via NALSA"},{"left":"Wrong city, can't report","right":"A Zero FIR works at any station"},{"left":"Asking starts a court case","right":"Information commits you to nothing"},{"left":"Complaining gets me fired","right":"Retaliation is itself prohibited"}],"relearn":"Each 'can't' has an answer: FIRs are mandatory, aid is free, Zero FIRs travel, asking is safe, retaliation is barred."},
  {"id":"kr-915","cat":"claim-it","type":"match","persona":"Farhan","source":"toolkit card","hook":"Match each line on a plain rights card to the number or step.","pairs":[{"left":"Free legal aid","right":"NALSA 15100"},{"left":"Women in distress","right":"181 or 1091"},{"left":"Any emergency","right":"112"},{"left":"Cyber harm","right":"1930"},{"left":"Serious crime, any station","right":"File a Zero FIR"}],"relearn":"A plain card: NALSA 15100 for aid, 181 or 1091 for women in distress, 112 for emergencies, 1930 for cyber harm, a Zero FIR for any serious crime."},
  {"id":"kr-916","cat":"claim-it","type":"match","persona":"any","source":"good evidence","hook":"Match each kind of proof to why it helps a complaint.","pairs":[{"left":"Saved chat screenshots","right":"Shows what was actually said"},{"left":"Dates and times noted","right":"Builds a clear timeline"},{"left":"A copy of your contract","right":"Proves the terms agreed"},{"left":"Names of any witnesses","right":"Someone can back you up"},{"left":"Your own written account","right":"Records it before memory fades"}],"relearn":"Screenshots show what was said, dates build a timeline, a contract proves terms, witnesses back you up, and a written account beats fading memory."},
  {"id":"kr-917","cat":"claim-it","type":"branch","persona":"any","source":"refused FIR","hook":"You go to report a serious crime and the officer waves you off.","options":[{"text":"Calmly say the FIR is mandatory and ask for the senior officer or a Zero FIR","consequence":"You hold your ground and it gets registered.","outcome":"registered","best":true},{"text":"Walk away assuming nothing can be done","consequence":"For a serious offence the FIR is mandatory; a senior officer or Zero FIR is your right."}],"debrief":"A serious offence means the FIR is mandatory.","relearn":"If a serious-crime FIR is refused, insist it's mandatory, ask for a senior officer, or file a Zero FIR."},
  {"id":"kr-918","cat":"claim-it","type":"branch","persona":"Meena","source":"can't afford lawyer","hook":"You have a real case but no money for a lawyer.","options":[{"text":"Call NALSA on 15100 and ask about free legal aid","consequence":"You get pointed to a free lawyer and your case moves.","outcome":"aided","best":true},{"text":"Give up because lawyers cost too much","consequence":"Free legal aid via NALSA 15100 exists exactly so cost can't stop you."}],"debrief":"Free legal aid means a real case isn't blocked by an empty wallet; the first call is to NALSA 15100.","relearn":"If you can't afford a lawyer, call NALSA on 15100 for free legal aid before giving up."},
  {"id":"kr-919","cat":"claim-it","type":"branch","persona":"any","source":"act early","hook":"Something happened you might want to complain about, but you're tempted to wait.","options":[{"text":"Note the date and save any proof now, even if you decide later","consequence":"Your options stay open and the evidence stays fresh.","outcome":"preserved","best":true},{"text":"Delete everything to forget about it","consequence":"That removes the proof you'd need; saving it keeps the choice yours."}],"debrief":"Saving evidence early commits you to nothing but keeps routes open.","relearn":"Note the date and save proof early, even if undecided; it keeps options and evidence intact."},
  {"id":"kr-920","cat":"claim-it","type":"branch","persona":"any","source":"unsure if serious","hook":"You're not sure your situation is 'big enough' to bother anyone with.","options":[{"text":"Call a helpline or legal aid and just ask what your options are","consequence":"You get clear guidance with no obligation.","outcome":"informed","best":true},{"text":"Assume it's too small and stay quiet","consequence":"Asking about routes costs nothing and commits you to nothing; clarity has no downside."}],"debrief":"Asking for guidance is free and binding on nothing.","relearn":"If unsure whether to act, just ask a helpline or legal aid; guidance is free and obligates you to nothing."},
  {"id":"kr-921","cat":"claim-it","type":"branch","persona":"any","source":"helped a friend","hook":"A friend was wronged but says people like them never win.","options":[{"text":"Share the real route, helpline, legal aid, the right office, and offer to go with them","consequence":"They see a door they didn't know was open.","outcome":"supported","best":true},{"text":"Agree that it's hopeless","consequence":"There are real routes; naming one and offering help turns 'hopeless' around."}],"debrief":"You can't promise an outcome, but you can hand someone the real route.","relearn":"When a friend feels hopeless, share the real route and offer to go with them; the door is open."},
  {"id":"kr-922","cat":"claim-it","type":"branch","persona":"any","source":"online scam route","hook":"You've been scammed online and don't know if it's even worth reporting.","options":[{"text":"Report it fast on cybercrime.gov.in or call 1930, and save all the details","consequence":"Quick reporting gives the best chance to act.","outcome":"reported","best":true},{"text":"Feel too embarrassed and let it slide","consequence":"Cyber fraud is reportable on 1930 or cybercrime.gov.in; fast reporting helps most."}],"debrief":"Online fraud has a real, fast route: 1930 or cybercrime.gov.in.","relearn":"If scammed online, report fast on cybercrime.gov.in or 1930; speed helps most."},
  {"id":"kr-923","cat":"claim-it","type":"branch","persona":"any","source":"deposit dispute","hook":"A landlord refuses to return your deposit and you assume tenants just lose.","options":[{"text":"Show your written agreement and deposit proof, use the consumer route if needed","consequence":"You have documentation and a real avenue.","outcome":"documented","best":true},{"text":"Accept losing it; 'tenants have no rights'","consequence":"Your agreement and deposit proof give a real case; 'no rights' is a myth."}],"debrief":"A written agreement and deposit proof give a real case.","relearn":"For a withheld deposit, your agreement and proof give a real case, not a sure loss."},
  {"id":"kr-924","cat":"claim-it","type":"reflect","persona":"any","source":"the route is half the protection","hook":"Lensy: just knowing where to turn, an FIR, the IC, free legal aid, is already half the protection. Sit right?","prompt":"What do you think?","options":["Yes","Half the protection","I know where to turn"],"affirm":"Knowing the route is real protection on its own; you carry it with you everywhere now.","relearn":"Knowing where to turn for redress is already half the protection."},
  {"id":"kr-925","cat":"claim-it","type":"reflect","persona":"Meena","source":"not too small","hook":"Lensy: your problem doesn't have to be huge to deserve a real route. Feel allowed to ask?","prompt":"What do you think?","options":["Yes","I'm allowed to ask","My problem counts"],"affirm":"Your problem doesn't have to be dramatic to matter; asking about your options is always allowed.","relearn":"Your problem doesn't have to be huge to deserve a route; asking is always allowed."},
  {"id":"kr-926","cat":"claim-it","type":"reflect","persona":"any","source":"no money no barrier","hook":"Lensy: an empty wallet was never meant to lock you out of justice. Believe that?","prompt":"What do you think?","options":["Yes","Money's no barrier","Aid is for me too"],"affirm":"Free legal aid exists precisely so money is never the thing that stops you claiming a right.","relearn":"An empty wallet was never meant to lock anyone out of justice; free legal aid exists for that."},
  {"id":"kr-927","cat":"claim-it","type":"reflect","persona":"any","source":"asking is strength","hook":"Lensy: asking 'what are my options?' isn't weakness, it's how strong people move. Land?","prompt":"What do you think?","options":["Yes","Asking is strength","I'll ask"],"affirm":"Asking what your options are is a smart, strong first move, not a sign you're helpless.","relearn":"Asking 'what are my options?' isn't weakness; it's how informed, strong people act."},
  {"id":"kr-928","cat":"claim-it","type":"reflect","persona":"any","source":"evidence is power","hook":"Lensy: every screenshot and date you save is a little more power in your hands. Feel that?","prompt":"What do you think?","options":["Yes","I'll keep proof","Evidence is power"],"affirm":"Quietly keeping evidence puts real power in your hands for whenever you choose to use it.","relearn":"Every screenshot and date you save is a little more power for whenever you choose to act."},
  {"id":"kr-929","cat":"claim-it","type":"reflect","persona":"Farhan","source":"passing it on","hook":"Lensy: a route you share with ten people protects eleven, not one. Worth passing on?","prompt":"What do you think?","options":["Yes","I'll pass it on","Protect more people"],"affirm":"Sharing a route multiplies its protection; what you learned can quietly shield a whole circle.","relearn":"A route you share protects everyone you pass it to, not just you."},
  {"id":"kr-930","cat":"claim-it","type":"reflect","persona":"any","source":"the system is navigable","hook":"Lensy: the system looks like a wall until you learn the few real doors in it. See doors now?","prompt":"What do you think?","options":["Yes","I see the doors","It's navigable"],"affirm":"Once you know the few real doors, the wall becomes a path you can actually walk.","relearn":"The system looks like a wall until you learn its few real doors; then it's navigable."},
  {"id":"kr-931","cat":"claim-it","type":"reflect","persona":"any","source":"reject learned helplessness","hook":"Lensy: 'people like us always lose' is something you were taught, not something true. Ready to drop it?","prompt":"What do you think?","options":["Yes","Drop the belief","People like us can win"],"affirm":"That belief was handed to you, not earned by you; you're free to set it down and use your rights.","relearn":"'People like us always lose' is taught, not true; you can set it down and use your rights."},
  {"id":"kr-932","cat":"claim-it","type":"reflect","persona":"any","source":"first call is free","hook":"Lensy: the very first step, a phone call to ask, costs you nothing at all. Ease the pressure?","prompt":"What do you think?","options":["Yes","First step is free","I can just call"],"affirm":"The first step is only a question, and it's free; nothing big has to happen until you decide.","relearn":"The first step is a free phone call to ask; nothing else has to happen until you choose."},
  {"id":"kr-933","cat":"claim-it","type":"reflect","persona":"any","source":"you decide the pace","hook":"Lensy: you can learn your route today and use it whenever you're ready, no rush forced on you. Okay?","prompt":"What do you think?","options":["Yes","I set the pace","Ready when I'm ready"],"affirm":"Knowing the route now means you choose when to act; the choice and the timing stay yours.","relearn":"You can learn your route now and use it when you're ready; the pace is yours to set."},
  {"id":"kr-934","cat":"claim-it","type":"role-play","persona":"any","source":"insist on FIR","hook":"An officer is reluctant to register your report of a serious crime.","setup":"Stay calm and clear. Say:","yourLine":[{"text":"\"This is a serious offence, so registering the FIR is mandatory. Please register it, or I'll speak to the senior officer.\"","best":true},{"text":"\"Okay, sorry to bother you, maybe it's nothing.\""}],"relearn":"For a serious offence you can calmly insist the FIR is mandatory and ask for the senior officer."},
  {"id":"kr-935","cat":"claim-it","type":"role-play","persona":"Meena","source":"ask for free aid","hook":"You need a lawyer for a real issue but can't pay for one.","setup":"Ask plainly; it's your right. Say:","yourLine":[{"text":"\"I can't afford a lawyer. How do I get free legal aid through NALSA, helpline 15100?\"","best":true},{"text":"\"I guess without money there's nothing I can do.\""}],"relearn":"You can plainly ask for free legal aid through NALSA 15100; it's a right, not a favour."},
  {"id":"kr-936","cat":"claim-it","type":"role-play","persona":"any","source":"file a zero FIR","hook":"The crime happened in another district and this station is hesitant.","setup":"Name the right thing. Say:","yourLine":[{"text":"\"Please register this as a Zero FIR; it can be filed at any station and transferred to the right one.\"","best":true},{"text":"\"Oh, wrong station, I'll just forget it then.\""}],"relearn":"You can ask any station to register a Zero FIR; it's filed anywhere and transferred on."},
  {"id":"kr-937","cat":"claim-it","type":"role-play","persona":"any","source":"ask for FIR copy","hook":"You've just filed an FIR and are about to leave.","setup":"Claim what's yours. Say:","yourLine":[{"text":"\"May I have my free copy of the FIR for my records, please?\"","best":true},{"text":"\"I'm sure I don't need any paperwork.\""}],"relearn":"You're entitled to a free copy of your FIR; you can simply ask for it before you leave."},
  {"id":"kr-938","cat":"claim-it","type":"role-play","persona":"any","source":"decline to pay","hook":"Someone hints that a small payment will get your complaint moving faster.","setup":"Hold the line firmly. Say:","yourLine":[{"text":"\"Filing this is free and my right, so I won't be paying anything. Please proceed properly.\"","best":true},{"text":"\"How much do you need to get it done?\""}],"relearn":"Filing a complaint is free and your right; you can firmly decline to pay anyone to move it."},
  {"id":"kr-939","cat":"claim-it","type":"role-play","persona":"any","source":"just asking questions","hook":"A friend is scared that asking about their rights commits them to a big fight.","setup":"Take the fear out of it. Say:","yourLine":[{"text":"\"Just asking what your options are commits you to nothing. We can call and learn, then you decide.\"","best":true},{"text":"\"Yeah, once you ask there's no going back, so be careful.\""}],"relearn":"You can tell someone that asking about their options commits them to nothing; they stay in control."},
  {"id":"kr-940","cat":"claim-it","type":"role-play","persona":"Farhan","source":"plain rights toolkit","hook":"You're explaining redress routes to a group of working youth.","setup":"Keep it plain and shareable. Say:","yourLine":[{"text":"\"Here's the plain version: free legal aid is NALSA 15100, cyber harm is 1930, and a serious crime can be a Zero FIR anywhere.\"","best":true},{"text":"\"It's all very complicated legal stuff, you wouldn't follow it.\""}],"relearn":"You can hand people a plain, shareable version: NALSA 15100 for aid, 1930 for cyber, a Zero FIR for serious crime."},
  {"id":"kr-941","cat":"claim-it","type":"role-play","persona":"any","source":"reassure a worried colleague","hook":"A junior colleague fears they'll be fired if they raise a complaint.","setup":"Name their protection. Say:","yourLine":[{"text":"\"Punishing you for a good-faith complaint is itself not allowed. Raising it is your right.\"","best":true},{"text":"\"Maybe just keep your head down so you don't lose the job.\""}],"relearn":"You can remind a colleague that retaliation for a good-faith complaint is itself prohibited."},
  {"id":"kr-942","cat":"claim-it","type":"role-play","persona":"any","source":"offer to come along","hook":"Someone you know is too nervous to go report something alone.","setup":"Offer to share the weight. Say:","yourLine":[{"text":"\"I'll come with you. We'll save the proof, find the right office, and ask for help together.\"","best":true},{"text":"\"You're on your own with that, sorry.\""}],"relearn":"You can offer to go with someone to report; saving proof and finding the office is easier together."},
  {"id":"kr-943","cat":"claim-it","type":"role-play","persona":"any","source":"call the helpline first","hook":"You're stuck on a rights problem and don't know the first move.","setup":"Make the easy first move out loud. Say:","yourLine":[{"text":"\"Let me just call NALSA 15100 and ask what my options are; the first step is only a question.\"","best":true},{"text":"\"There's no point calling anyone, it'll go nowhere.\""}],"relearn":"You can make calling a helpline like NALSA 15100 your free first step; it's only a question."},
  {"id":"kr-944","cat":"claim-it","type":"sort","persona":"any","source":"true or myth","hook":"Sort each line: a true route, or a defeatist myth?","items":[{"id":"a","text":"An FIR is mandatory for a serious crime"},{"id":"b","text":"Police can refuse any complaint they like"},{"id":"c","text":"Free legal aid exists if you can't pay"},{"id":"d","text":"You always need money to claim a right"},{"id":"e","text":"A Zero FIR works at any station"},{"id":"f","text":"Ordinary people just always lose"}],"bins":[{"id":"true","label":"True route","valence":"pos"},{"id":"myth","label":"Defeatist myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"True: FIRs are mandatory, free aid exists, Zero FIRs travel. Myth: police can refuse, you need money, ordinary people always lose."},
  {"id":"kr-945","cat":"claim-it","type":"sort","persona":"Farhan","source":"which helpline","hook":"Sort: which line belongs on a free-legal-aid card, and which doesn't?","items":[{"id":"a","text":"NALSA free legal aid: 15100"},{"id":"b","text":"Cyber fraud and abuse: 1930"},{"id":"c","text":"A made-up number a forward sent you"},{"id":"d","text":"Women in distress: 181 or 1091"},{"id":"e","text":"Any emergency: 112"},{"id":"f","text":"Whatever number a stranger scribbles down"}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"off","label":"Keep off","valence":"neg"}],"key":{"a":"card","b":"card","c":"off","d":"card","e":"card","f":"off"},"relearn":"On the card: NALSA 15100, cyber 1930, women 181 or 1091, emergency 112. Keep off: numbers from forwards or strangers."},
  {"id":"kr-946","cat":"claim-it","type":"sort","persona":"any","source":"helps or hurts a case","hook":"Sort: does this help your case, or quietly weaken it?","items":[{"id":"a","text":"Saving the messages and dates"},{"id":"b","text":"Deleting everything in frustration"},{"id":"c","text":"Writing down what happened that day"},{"id":"d","text":"Telling nobody and waiting years"},{"id":"e","text":"Keeping a copy of your agreement"},{"id":"f","text":"Letting the time limit quietly pass"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"hurts","label":"Hurts","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"Helps: saving messages, writing it down, keeping your agreement. Hurts: deleting proof, waiting years, letting the limit pass."},
  {"id":"kr-947","cat":"claim-it","type":"sort","persona":"any","source":"first move","hook":"Sort: a solid first move on a rights problem, or a dead end?","items":[{"id":"a","text":"Call a helpline and ask your options"},{"id":"b","text":"Decide it's hopeless before trying"},{"id":"c","text":"Note the date and save any proof"},{"id":"d","text":"Pay someone to 'sort it out' quietly"},{"id":"e","text":"Find the right office or committee"},{"id":"f","text":"Wait silently for it to fix itself"}],"bins":[{"id":"move","label":"Solid move","valence":"pos"},{"id":"dead","label":"Dead end","valence":"neg"}],"key":{"a":"move","b":"dead","c":"move","d":"dead","e":"move","f":"dead"},"relearn":"Solid: call and ask, save proof, find the right office. Dead end: deciding it's hopeless, paying bribes, waiting silently."},
  {"id":"kr-948","cat":"claim-it","type":"spot","persona":"any","source":"spot the defeatist lie","hook":"Spot the two lines that wrongly say you're powerless.","scene":[{"id":"a","text":"For a serious crime, an FIR is mandatory.","trick":false},{"id":"b","text":"No money for a lawyer means the system isn't for you.","trick":true},{"id":"c","text":"A Zero FIR can be filed at any station.","trick":false},{"id":"d","text":"NALSA 15100 offers free legal aid.","trick":false},{"id":"e","text":"Police can refuse a serious complaint at will.","trick":true}],"why":"Both caught lines are false: aid exists if you can't pay, and a serious-crime FIR is mandatory.","relearn":"Aid exists if you can't pay, and a serious-crime FIR is mandatory; both 'powerless' lines lie."},
  {"id":"kr-949","cat":"claim-it","type":"spot","persona":"any","source":"spot the wrong claim-it advice","hook":"Spot the two pieces of advice that would quietly harm you.","scene":[{"id":"a","text":"Save your messages and note the dates.","trick":false},{"id":"b","text":"Pay a little to move your complaint faster.","trick":true},{"id":"c","text":"Ask for your free copy of the FIR.","trick":false},{"id":"d","text":"Just delete everything so it goes away.","trick":true},{"id":"e","text":"Call NALSA 15100 for free legal aid.","trick":false}],"why":"Both caught lines hurt you: paying is never required, and deleting destroys the evidence you'd need.","relearn":"Never pay to move a free complaint, and never delete proof; both quietly weaken your case."},
  {"id":"kr-950","cat":"claim-it","type":"spot","persona":"Meena","source":"spot what blocks Meena","hook":"Spot the two false beliefs that would stop Meena claiming her rights.","scene":[{"id":"a","text":"You can complain in your own language.","trick":false},{"id":"b","text":"Without connections, there's no point trying.","trick":true},{"id":"c","text":"Free legal aid can help you write it.","trick":false},{"id":"d","text":"A migrant worker has no rights at all.","trick":true},{"id":"e","text":"A helpline can point you to the route.","trick":false}],"why":"Both caught lines are false: you don't need connections, and rights apply to every worker.","relearn":"You don't need connections, and rights apply to every worker including migrants; both beliefs are false."},
  {"id":"kr-951","cat":"claim-it","type":"spot","persona":"any","source":"spot the bad reporting move","hook":"Spot the two lines that would weaken an online-fraud report.","scene":[{"id":"a","text":"Report it on cybercrime.gov.in or 1930 fast.","trick":false},{"id":"b","text":"Stay quiet; it's too embarrassing to report.","trick":true},{"id":"c","text":"Keep screenshots of messages and transactions.","trick":false},{"id":"d","text":"Wait months to see if it sorts itself out.","trick":true},{"id":"e","text":"Save the scammer's number and account.","trick":false}],"why":"Both caught lines weaken your case: silence and waiting let the trail go cold; reporting fast helps.","relearn":"Staying silent or waiting lets the trail go cold; reporting fast on 1930 is best."},
  {"id":"kr-952","cat":"claim-it","type":"spot","persona":"any","source":"spot the myth about cost","hook":"Spot the two lines that wrongly tie your rights to money.","scene":[{"id":"a","text":"Filing a complaint or FIR is free.","trick":false},{"id":"b","text":"You must hire a costly lawyer before you can ask.","trick":true},{"id":"c","text":"NALSA gives free legal aid if you can't pay.","trick":false},{"id":"d","text":"Justice is really only for people with money.","trick":true},{"id":"e","text":"Asking your options on a helpline costs nothing.","trick":false}],"why":"Both caught lines are false: filing is free and free legal aid means justice isn't only for the rich.","relearn":"Filing is free and free legal aid exists; both 'rights cost money' lines lie."},
  {"id":"kr-953","cat":"claim-it","type":"spot","persona":"any","source":"spot the wrong tenant belief","hook":"Spot the two false beliefs that make a tenant give up too easily.","scene":[{"id":"a","text":"A written rent agreement protects both sides.","trick":false},{"id":"b","text":"Tenants have no rights; just accept the loss.","trick":true},{"id":"c","text":"A documented deposit helps in a dispute.","trick":false},{"id":"d","text":"A landlord can keep your deposit for any reason.","trick":true},{"id":"e","text":"A consumer route exists for real disputes.","trick":false}],"why":"Both caught lines lie: tenants have rights, and a deposit returns minus documented damage.","relearn":"Tenants have rights, and a deposit returns minus documented damage; both beliefs lie."},
  {"id":"kr-954","cat":"claim-it","type":"spot","persona":"any","source":"spot the timing trap","hook":"Spot the two lines that would cost you your window to act.","scene":[{"id":"a","text":"Note the date as soon as it happens.","trick":false},{"id":"b","text":"No rush; you can complain anytime forever.","trick":true},{"id":"c","text":"Acting sooner keeps more routes open.","trick":false},{"id":"d","text":"Wait until it's much worse before asking.","trick":true},{"id":"e","text":"Ask your options early, with no obligation.","trick":false}],"why":"Both caught lines are false: many routes have time limits, so waiting can close your window.","relearn":"Many routes have time limits, so waiting forever or for it to worsen can close your window to act."},
  {"id":"kr-990","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A UPI 'refund' request needs my PIN to send me money.\"","myth":{"un":"A UPI refund needs me to enter my PIN to receive money.","re":"You never enter a PIN to receive money on UPI; a PIN only sends money out.","why":"Anyone asking for your PIN to 'pay you' is trying to take money."},"relearn":"On UPI you never enter a PIN to get money; a PIN only sends money out.","persona":"any","source":"upi pin scam"},
  {"id":"kr-991","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I share my OTP with the bank's caller, it proves I'm the real account holder.\"","myth":{"un":"Sharing my OTP with a bank caller proves I'm the real account holder.","re":"A real bank never asks for your OTP; an OTP is the key to your money, share it with no one.","why":"OTP requests over a call are a fraud tactic, not identity checks."},"relearn":"Banks never ask for your OTP on a call; never share it with anyone.","persona":"Meena","source":"otp scam"},
  {"id":"kr-992","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Online scams and abuse can't really be reported.\"","myth":{"un":"Online scams and abuse can't really be reported.","re":"You can report cyber fraud, harassment and image abuse at cybercrime.gov.in or helpline 1930.","why":"There is a real national reporting route, and fast reporting helps."},"relearn":"Report cyber harm at cybercrime.gov.in or 1930; fast reporting helps.","persona":"any","source":"reportable"},
  {"id":"kr-993","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If a fake profile uses my photos, that's just the internet, nothing can be done.\"","myth":{"un":"A fake profile using my photos is just the internet; nothing can be done.","re":"Impersonation is a cyber offence; you can report it and ask the platform to take it down.","why":"Both a report and a take-down request are real, available routes."},"relearn":"Impersonation is reportable at cybercrime.gov.in; ask the platform to take it down.","persona":"any","source":"impersonation"},
  {"id":"kr-994","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"I sent that photo to one person, so they're allowed to forward it.\"","myth":{"un":"If I sent an intimate photo to someone, they're allowed to forward it.","re":"Consent to share with one person is not consent to circulate; forwarding it without permission is a punishable offence.","why":"Sharing with one person never licenses anyone to redistribute it."},"relearn":"Sending a photo to one person is not consent to forward it; circulating it is an offence.","persona":"Aarti","source":"consent to one isn't consent to share"},
  {"id":"kr-995","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Public Wi-Fi is fine for checking my bank balance and paying bills.\"","myth":{"un":"Open public Wi-Fi is fine for banking and payments.","re":"Open Wi-Fi can be snooped; use mobile data or a trusted network for money and logins.","why":"Sensitive logins on an open network are easier for others to intercept."},"relearn":"Avoid banking on open public Wi-Fi; use mobile data for money and logins.","persona":"any","source":"public wifi"},
  {"id":"kr-996","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I've nothing to hide, I should let my partner track my location all day.\"","myth":{"un":"If I have nothing to hide, I should let my partner track my location all day.","re":"Constant location-tracking on demand is a surveillance and control tactic, not proof of innocence or love.","why":"Wanting some privacy is normal; being monitored everywhere is a warning sign, not loyalty."},"relearn":"Demanding constant location-tracking is a control tactic; privacy isn't something you owe anyone.","persona":"any","source":"location tracking control"},
  {"id":"kr-997","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A job offer asking for a 'registration fee' over WhatsApp is normal.\"","myth":{"un":"A job that asks for a registration or training fee upfront is normal.","re":"Genuine employers pay you; an upfront fee to 'secure a job' is a classic scam.","why":"Real jobs don't charge you to start; money flowing the wrong way is the red flag."},"relearn":"Real jobs pay you; an upfront fee to get hired is a scam, report it.","persona":"Meena","source":"job fee scam"},
  {"id":"kr-998","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"If I just delete the chat, the blackmailer loses their power.\"","myth":{"un":"Deleting the chat takes away a blackmailer's power.","re":"Deleting destroys your evidence; instead save proof and report to 1930 or cybercrime.gov.in.","why":"Saved screenshots are what help a report; deleting only helps the abuser."},"relearn":"Don't delete evidence of blackmail; save proof and report to 1930.","persona":"any","source":"preserve evidence"},
  {"id":"kr-999","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A 'KYC update' link by SMS asking me to re-verify is from my bank.\"","myth":{"un":"A KYC-update link by SMS asking me to re-verify is really my bank.","re":"Banks don't ask you to finish KYC through a random SMS link; that's a phishing trap.","why":"The link harvests your details; verify only through the bank's own app or branch."},"relearn":"Ignore KYC-update SMS links; verify only via the bank's app or branch.","persona":"any","source":"kyc phishing"},
  {"id":"kr-1000","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"My data is the app's property once I sign up, so I have no say.\"","myth":{"un":"Once I sign up, my data is the app's property and I have no say.","re":"Under the DPDP Act 2023 your personal data stays yours; your consent matters and you have rights over it.","why":"Signing up isn't signing away your data rights."},"relearn":"Under the DPDP Act 2023 your data stays yours; your consent matters.","persona":"any","source":"data ownership"},
  {"id":"kr-1001","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"You can't get scammed money back, so reporting is pointless.\"","myth":{"un":"Scammed money is gone, so reporting is pointless.","re":"Reporting fast to 1930 can help freeze the transfer; speed gives the best chance of recovery.","why":"There's no guarantee, but quick reporting is what makes recovery possible at all."},"relearn":"Report fraud fast to 1930; speed gives the best chance to recover money.","persona":"any","source":"recovery hope"},
  {"id":"kr-1002","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"A friend forwarding a 'free recharge' link means it's safe to tap.\"","myth":{"un":"A free-recharge link is safe because a friend forwarded it.","re":"A forward isn't a safety check; reward-bait links often steal logins, so don't tap unknown ones.","why":"Friends forward scams without knowing; the source you trust is the official app, not a forward."},"relearn":"A friend's forward isn't proof it's safe; don't tap reward-bait links.","persona":"any","source":"forward link"},
  {"id":"kr-1003","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Letting an app read all my contacts and messages is the only way to use it.\"","myth":{"un":"I must let an app read all my contacts and messages to use it.","re":"You can decline permissions an app doesn't truly need; your consent over your data is yours to give.","why":"A torch app doesn't need your contacts; over-asking is a flag, not a requirement."},"relearn":"Decline app permissions that aren't truly needed; your consent is yours.","persona":"any","source":"over-permission"},
  {"id":"kr-1004","cat":"cyber-and-data","type":"strike-rewrite","hook":"\"Reporting cyber harm needs a lawyer and a lot of money.\"","myth":{"un":"Reporting cyber harm needs a lawyer and a lot of money.","re":"Anyone can file directly at cybercrime.gov.in or call 1930 for free; no lawyer or fee is needed to report.","why":"The reporting portal is open to every citizen at no cost."},"relearn":"Reporting at cybercrime.gov.in or 1930 is free; no lawyer needed to start.","persona":"Farhan","source":"free to report"},
  {"id":"kr-1005","cat":"cyber-and-data","type":"branch","hook":"A caller says your account is blocked and reads out an OTP for you to confirm.","options":[{"text":"Hang up; a real bank never asks you to confirm an OTP","consequence":"You shut the scam down and stay safe.","outcome":"safe","best":true},{"text":"Read the OTP back so they can 'unblock' you","consequence":"That OTP drains the account; hanging up is the safe move."}],"debrief":"No genuine bank confirms an OTP over a call; ending the call protects you.","relearn":"Never share or confirm an OTP on a call; hang up on anyone who asks.","persona":"any","source":"otp call"},
  {"id":"kr-1006","cat":"cyber-and-data","type":"branch","hook":"Someone is threatening to leak your private photos unless you pay.","options":[{"text":"Don't pay; save the messages and report to 1930 or cybercrime.gov.in","consequence":"You take the real protective steps and the crime is on them.","outcome":"reported","best":true},{"text":"Pay quietly so it goes away","consequence":"Paying rarely stops blackmail; saving evidence and reporting to 1930 is the protective move."}],"debrief":"For sextortion: don't pay, preserve evidence, and report to 1930 or cybercrime.gov.in.","relearn":"Don't pay blackmailers; preserve evidence and report to 1930.","persona":"any","source":"sextortion"},
  {"id":"kr-1007","cat":"cyber-and-data","type":"branch","hook":"You sent money to a fraud UPI ID ten minutes ago and feel sick about it.","options":[{"text":"Report to 1930 now; fast reporting can help freeze the transfer","consequence":"You give recovery its best chance while the trail is fresh.","outcome":"acted","best":true},{"text":"Wait a day to see if they refund it","consequence":"Waiting lowers the odds; reporting fast to 1930 can help."}],"debrief":"The sooner fraud is reported to 1930, the better the chance of freezing it.","relearn":"Report fraud transfers to 1930 immediately; speed matters most.","persona":"any","source":"fast report"},
  {"id":"kr-1008","cat":"cyber-and-data","type":"branch","hook":"An app you just installed demands your camera, mic and contacts to open.","options":[{"text":"Deny what it doesn't need and see if it still works","consequence":"You keep control and grant only what's necessary.","outcome":"private","best":true},{"text":"Allow everything so it stops nagging","consequence":"You can deny what isn't needed; your data is yours to keep."}],"debrief":"You have a right to control your data; denying needless permissions uses it.","relearn":"Deny app permissions that aren't needed; your data stays your choice.","persona":"any","source":"permissions"},
  {"id":"kr-1009","cat":"cyber-and-data","type":"branch","hook":"A 'delivery' SMS says your parcel is stuck and links you to pay a small fee.","options":[{"text":"Don't tap; check the order in the official app","consequence":"You avoid a phishing page built to steal your card.","outcome":"safe","best":true},{"text":"Tap and pay the small fee to release it","consequence":"That page harvests your card; the official app keeps you safe."}],"debrief":"Surprise 'fee' links by SMS are classic phishing; verify in the official app.","relearn":"Don't pay SMS 'parcel fee' links; check the official app instead.","persona":"any","source":"parcel phishing"},
  {"id":"kr-1010","cat":"cyber-and-data","type":"branch","hook":"Your social account is hacked and posting spam to your friends.","options":[{"text":"Change the password, turn on two-step login, and report it to the platform","consequence":"You lock the attacker out and warn the platform.","outcome":"secured","best":true},{"text":"Just delete the spam posts and hope it stops","consequence":"They keep access until you reset; securing and reporting is the real fix."}],"debrief":"A hacked account needs a password reset, two-step login, and a report, not just clean-up.","relearn":"Hacked account: reset the password, add two-step login, report it.","persona":"any","source":"account hacked"},
  {"id":"kr-1011","cat":"cyber-and-data","type":"branch","hook":"A stranger online keeps sending you abusive messages every day.","options":[{"text":"Block and report them, and save proof in case it escalates","consequence":"You cut contact and keep evidence ready.","outcome":"handled","best":true},{"text":"Argue back to make them stop","consequence":"Engaging often feeds it; blocking, reporting and saving proof protects you better."}],"debrief":"Online abuse is reportable; block, report, and keep evidence rather than engage.","relearn":"For online abuse: block, report, and save evidence; don't argue back.","persona":"any","source":"online abuse"},
  {"id":"kr-1012","cat":"cyber-and-data","type":"branch","hook":"A loan app threatens to message your contacts about your dues.","options":[{"text":"Refuse, save the threats, and report it to 1930","consequence":"You treat the threats as the crime they are.","outcome":"reported","best":true},{"text":"Pay whatever they demand to avoid shame","consequence":"Contact-shaming is illegal; reporting to 1930 is the route, not caving."}],"debrief":"Loan-app contact-shaming is harassment, not collection; save proof and report.","relearn":"Loan-app contact threats are harassment; save proof and report to 1930.","persona":"Meena","source":"loan app harassment"},
  {"id":"kr-1013","cat":"cyber-and-data","type":"branch","hook":"A 'lottery win' email asks for your bank details and a small 'processing tax'.","options":[{"text":"Ignore and delete it; a prize you never entered is a scam","consequence":"You keep your details and your money safe.","outcome":"safe","best":true},{"text":"Send the small tax to claim the big prize","consequence":"There is no prize; any 'fee to release winnings' is the scam itself."}],"debrief":"A win for a lottery you never entered, plus an upfront fee, is always a scam.","relearn":"No real prize asks for a fee or your bank details first; delete it.","persona":"any","source":"lottery scam"},
  {"id":"kr-1014","cat":"cyber-and-data","type":"branch","hook":"A site you shopped on had a data breach and your email and number leaked.","options":[{"text":"Change that password everywhere you reused it and watch for phishing","consequence":"You shrink the damage and stay alert to follow-on scams.","outcome":"hardened","best":true},{"text":"Do nothing; the leak already happened","consequence":"Reused passwords stay exposed; resetting them and staying alert limits the harm."}],"debrief":"After a breach, reset reused passwords and expect targeted phishing for a while.","relearn":"After a breach, change reused passwords and watch for phishing.","persona":"any","source":"data breach"},
  {"id":"kr-1015","cat":"cyber-and-data","type":"branch","hook":"A video-call 'investment mentor' promises to double your money in a week.","options":[{"text":"Walk away; guaranteed doubling is the signature of a scam","consequence":"You keep your savings out of a trap.","outcome":"safe","best":true},{"text":"Start small to test if it's real","consequence":"Even a small deposit funds the scam; guaranteed quick returns are never real."}],"debrief":"No genuine investment guarantees fast doubling; that promise is the warning sign.","relearn":"Guaranteed quick-double returns are a scam; don't deposit anything.","persona":"any","source":"investment scam"},
  {"id":"kr-1016","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'bank' call.","scene":[{"id":"a","text":"\"Don't visit the branch, I'll fix it on the phone now.\"","trick":true},{"id":"b","text":"\"Share the OTP I just sent to verify it's you.\"","trick":true},{"id":"c","text":"The bank's real number is on the back of your card","trick":false},{"id":"d","text":"You can hang up and call the bank yourself","trick":false},{"id":"e","text":"A bank never needs your OTP or PIN to help you","trick":false}],"why":"Rushing you off the branch and asking for an OTP are the scam moves; real banks never need your OTP.","relearn":"Real banks never ask for your OTP or rush you off the branch.","persona":"any","source":"bank call flags"},
  {"id":"kr-1017","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'job offer' message.","scene":[{"id":"a","text":"\"Pay a 2000 registration fee to lock your seat.\"","trick":true},{"id":"b","text":"\"Send your Aadhaar photo and bank login to onboard.\"","trick":true},{"id":"c","text":"A real offer letter states your pay, hours and role","trick":false},{"id":"d","text":"You can verify the company first","trick":false},{"id":"e","text":"Genuine employers pay you, not the reverse","trick":false}],"why":"The upfront fee and the bank-login demand are the scam moves; real jobs pay you.","relearn":"Real jobs don't charge a fee or need your bank login to hire you.","persona":"Meena","source":"job offer flags"},
  {"id":"kr-1018","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'KYC update' SMS.","scene":[{"id":"a","text":"\"Click this link in 2 hours or your account is blocked.\"","trick":true},{"id":"b","text":"\"Enter your card number and PIN to re-verify.\"","trick":true},{"id":"c","text":"Your bank handles KYC in its app or branch","trick":false},{"id":"d","text":"You can ignore the link and call the bank","trick":false},{"id":"e","text":"A bank never needs your PIN for KYC","trick":false}],"why":"The panic deadline and the PIN demand are the phishing moves; real KYC needs no PIN.","relearn":"KYC-update SMS links that demand your PIN are phishing; ignore them.","persona":"any","source":"kyc flags"},
  {"id":"kr-1019","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this app's sign-up screen.","scene":[{"id":"a","text":"A torch app demands access to your contacts and SMS","trick":true},{"id":"b","text":"\"Allow all permissions or you can't continue.\"","trick":true},{"id":"c","text":"You can deny permissions an app doesn't truly need","trick":false},{"id":"d","text":"The app lists why it wants each permission","trick":false},{"id":"e","text":"Your consent over your data is yours to give","trick":false}],"why":"Demanding needless data and forcing 'allow all' are the flags; you can deny what isn't needed.","relearn":"An app forcing needless permissions is a flag; deny what it doesn't need.","persona":"any","source":"permission flags"},
  {"id":"kr-1020","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this blackmail chat.","scene":[{"id":"a","text":"\"Pay by tonight or I send the photos to your family.\"","trick":true},{"id":"b","text":"\"Delete our chats so there's no proof.\"","trick":true},{"id":"c","text":"Saving screenshots helps a report","trick":false},{"id":"d","text":"You can report this to 1930","trick":false},{"id":"e","text":"The crime is on the blackmailer, never you","trick":false}],"why":"The pay-or-leak threat and 'delete the proof' are the abuser's moves; save evidence and report.","relearn":"Blackmail threats and 'delete the proof' are flags; save evidence and report.","persona":"any","source":"blackmail flags"},
  {"id":"kr-1021","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'refund' message.","scene":[{"id":"a","text":"\"Enter your UPI PIN to receive your refund.\"","trick":true},{"id":"b","text":"\"Install this remote-screen app so I can help.\"","trick":true},{"id":"c","text":"You never enter a PIN to receive money","trick":false},{"id":"d","text":"A real refund lands with no approval","trick":false},{"id":"e","text":"You can check the order in the app","trick":false}],"why":"A PIN-to-receive request and a remote-control app are the scam moves; receiving needs no PIN.","relearn":"You never enter a PIN to receive money, and never install a stranger's app.","persona":"any","source":"refund flags"},
  {"id":"kr-1022","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this 'electricity bill' SMS.","scene":[{"id":"a","text":"\"Power cut tonight unless you pay on this link.\"","trick":true},{"id":"b","text":"\"Call this personal number to update your meter.\"","trick":true},{"id":"c","text":"You can check dues in the board's app","trick":false},{"id":"d","text":"Real boards don't threaten an instant cut","trick":false},{"id":"e","text":"A personal number isn't an official line","trick":false}],"why":"The instant-cut threat and the personal-number 'helpline' are the scam moves; verify officially.","relearn":"Threats of an instant power cut by SMS link are a scam; verify officially.","persona":"any","source":"bill scam flags"},
  {"id":"kr-1023","cat":"cyber-and-data","type":"spot","hook":"Lensy: spot the two red flags in this stranger's friend request.","scene":[{"id":"a","text":"\"Send a private photo to prove you trust me.\"","trick":true},{"id":"b","text":"\"Move to a secret app, don't tell anyone.\"","trick":true},{"id":"c","text":"You can keep private photos private","trick":false},{"id":"d","text":"You can block and report a pushy stranger","trick":false},{"id":"e","text":"Real trust never demands a photo as a test","trick":false}],"why":"Pressuring for a private photo and pushing to a secret app are grooming moves; block and report.","relearn":"Pressure for private photos or secrecy is a flag; you can block and report.","persona":"any","source":"grooming flags"},
  {"id":"kr-1052","cat":"cyber-and-data","type":"match","hook":"Match each online harm to its first right move (India).","pairs":[{"left":"Money sent to a fraud UPI ID","right":"Report fast to 1930"},{"left":"Private images being shared","right":"Save proof, report at cybercrime.gov.in"},{"left":"Social account hacked","right":"Reset password, add two-step login"},{"left":"App misusing your data","right":"Exercise your DPDP Act rights"},{"left":"A child unsafe online","right":"Call Childline 1098"}],"relearn":"Fraud to 1930, image abuse to cybercrime.gov.in, hacks reset, data to DPDP, a child to 1098.","persona":"any","source":"harm to move"},
  {"id":"kr-1024","cat":"cyber-and-data","type":"match","hook":"Match each scam to the tell that gives it away.","pairs":[{"left":"\"Share the OTP to verify you\"","right":"A bank never needs your OTP"},{"left":"\"Pay a fee to start the job\"","right":"Real jobs pay you, not the reverse"},{"left":"\"Enter your PIN to get a refund\"","right":"Receiving money never needs a PIN"},{"left":"\"You won a prize, pay the tax\"","right":"No real prize charges a fee first"},{"left":"\"Doubling guaranteed in a week\"","right":"Guaranteed fast returns aren't real"}],"relearn":"Each tell is the giveaway: no OTP, no fee to be hired, no PIN to receive, no fee for a prize.","persona":"any","source":"scam tells"},
  {"id":"kr-1025","cat":"cyber-and-data","type":"match","hook":"Match each safe habit to what it protects you from.","pairs":[{"left":"Two-step login","right":"A stolen password alone getting in"},{"left":"A unique password per site","right":"One breach unlocking everything"},{"left":"Banking on mobile data","right":"Snooping on open Wi-Fi"},{"left":"Denying needless permissions","right":"Apps over-collecting your data"},{"left":"Checking links in the app","right":"Phishing pages that steal logins"}],"relearn":"Each habit blocks a real risk: stolen passwords, breaches, snooping, over-collection, phishing.","persona":"any","source":"habits protect"},
  {"id":"kr-1026","cat":"cyber-and-data","type":"match","hook":"Match each helpline or route to what it's for (India).","pairs":[{"left":"Cyber fraud or online harm","right":"1930 or cybercrime.gov.in"},{"left":"A woman in distress","right":"181 or 1091"},{"left":"Any life-threatening emergency","right":"Emergency 112"},{"left":"A child at risk","right":"Childline 1098"},{"left":"Free legal aid to follow up","right":"NALSA 15100"}],"relearn":"Cyber harm to 1930, a woman to 181 or 1091, emergency 112, a child 1098, legal aid 15100.","persona":"Farhan","source":"route card"},
  {"id":"kr-1027","cat":"cyber-and-data","type":"match","hook":"Match each privacy setting to what it does for you.","pairs":[{"left":"Private account","right":"Only approved people see your posts"},{"left":"Location off in photos","right":"Pictures don't reveal where you are"},{"left":"Reviewing tagged posts","right":"You choose what links to your name"},{"left":"Blocking and reporting","right":"You cut off someone harassing you"},{"left":"Clearing old saved logins","right":"A lost phone can't open your accounts"}],"relearn":"Privacy tools give you control: who sees you, where you are, what links to you, and who can reach you.","persona":"any","source":"privacy settings"},
  {"id":"kr-1028","cat":"cyber-and-data","type":"match","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"\"Nothing online can be reported\"","right":"cybercrime.gov.in and 1930 exist"},{"left":"\"A shared image is your fault\"","right":"The crime is on whoever shared it"},{"left":"\"My data belongs to the app\"","right":"Under DPDP your data stays yours"},{"left":"\"Scammed money can't return\"","right":"Fast reporting can help freeze it"},{"left":"\"Trust means sharing passwords\"","right":"Privacy and trust can coexist"}],"relearn":"Each myth has a true reply: it's reportable, not your fault, your data, recoverable, private.","persona":"any","source":"myth to truth"},
  {"id":"kr-1029","cat":"cyber-and-data","type":"match","hook":"Match each phishing lure to the calm check that defuses it.","pairs":[{"left":"\"Act in 2 hours or lose access\"","right":"Real services don't rush you"},{"left":"\"Click here to fix your KYC\"","right":"Do KYC only in the bank's app"},{"left":"\"Confirm card details to go on\"","right":"Never type card details in a link"},{"left":"\"Suspicious login, verify now\"","right":"Open the app, not the link"},{"left":"\"Download this support tool\"","right":"Never install a stranger's app"}],"relearn":"Slow down, ignore the link, open the official app; urgency is the lure, not a warning.","persona":"any","source":"phishing checks"},
  {"id":"kr-1030","cat":"cyber-and-data","type":"sort","hook":"Sort each move after a scam call: protects you, or a scam tactic?","items":[{"id":"a","text":"Hanging up and calling the number on your card"},{"id":"b","text":"Reading out the OTP they 'need to verify'"},{"id":"c","text":"Saving a screenshot of the caller's number"},{"id":"d","text":"Installing the screen-share app they sent"},{"id":"e","text":"Reporting the number to 1930"},{"id":"f","text":"Letting them rush you into deciding now"}],"bins":[{"id":"safe","label":"Protects you","valence":"pos"},{"id":"trap","label":"Scam tactic","valence":"neg"}],"key":{"a":"safe","b":"trap","c":"safe","d":"trap","e":"safe","f":"trap"},"relearn":"Hang up, save proof and report; never share an OTP, install their app, or let them rush you.","persona":"any","source":"scam call sort"},
  {"id":"kr-1031","cat":"cyber-and-data","type":"sort","hook":"Sort each password habit: keeps you safe, or leaves you exposed?","items":[{"id":"a","text":"A different password for each account"},{"id":"b","text":"Reusing one password everywhere"},{"id":"c","text":"Turning on two-step login"},{"id":"d","text":"Saving passwords in a plain notes file"},{"id":"e","text":"Using a long passphrase"},{"id":"f","text":"Telling a 'support' caller your password"}],"bins":[{"id":"safe","label":"Keeps you safe","valence":"pos"},{"id":"weak","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"safe","b":"weak","c":"safe","d":"weak","e":"safe","f":"weak"},"relearn":"Unique passwords, two-step login and a long passphrase help; reuse, plain files and sharing don't.","persona":"any","source":"password sort"},
  {"id":"kr-1032","cat":"cyber-and-data","type":"sort","hook":"Sort each link or message: safe to open, or a phishing risk?","items":[{"id":"a","text":"An order update you open inside the app"},{"id":"b","text":"A 'KYC link' from an unknown SMS"},{"id":"c","text":"A statement you reach via the bank's app"},{"id":"d","text":"A 'free recharge' link a friend forwarded"},{"id":"e","text":"A 'parcel fee' link to pay a stranger"},{"id":"f","text":"A login page you reached by typing the site yourself"}],"bins":[{"id":"safe","label":"Safe to open","valence":"pos"},{"id":"phish","label":"Phishing risk","valence":"neg"}],"key":{"a":"safe","b":"phish","c":"safe","d":"phish","e":"phish","f":"safe"},"relearn":"Reach accounts through the official app or by typing the site; treat surprise SMS and forwards as risk.","persona":"any","source":"link sort"},
  {"id":"kr-1033","cat":"cyber-and-data","type":"sort","hook":"Sort each statement about your data rights: true, or a myth?","items":[{"id":"a","text":"Under DPDP your consent matters"},{"id":"b","text":"You can ask what data is held about you"},{"id":"c","text":"Apps own your data once you sign up"},{"id":"d","text":"You can deny needless permissions"},{"id":"e","text":"You have no say over your own data"},{"id":"f","text":"You can ask for wrong data to be corrected"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"true","c":"myth","d":"true","e":"myth","f":"true"},"relearn":"Your consent matters, you can see, correct and limit your data; 'apps own it, you have no say' is a myth.","persona":"any","source":"data rights sort"},
  {"id":"kr-1034","cat":"cyber-and-data","type":"sort","hook":"Sort each step after private images leak: helps, or makes it worse?","items":[{"id":"a","text":"Saving evidence before anything else"},{"id":"b","text":"Blaming yourself and staying silent"},{"id":"c","text":"Reporting at cybercrime.gov.in"},{"id":"d","text":"Asking the platform to take it down"},{"id":"e","text":"Paying whoever is threatening you"},{"id":"f","text":"Telling someone you trust for support"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"helps","b":"worse","c":"helps","d":"helps","e":"worse","f":"helps"},"relearn":"Save proof, report, ask for take-down and lean on support; self-blame and paying only help the abuser.","persona":"Aarti","source":"image leak sort"},
  {"id":"kr-1035","cat":"cyber-and-data","type":"sort","hook":"Sort each claim about reporting cyber harm: true, or false?","items":[{"id":"a","text":"You can report for free at cybercrime.gov.in"},{"id":"b","text":"You need a lawyer just to file a report"},{"id":"c","text":"Helpline 1930 takes cyber-fraud reports"},{"id":"d","text":"Reporting is pointless once money is gone"},{"id":"e","text":"Fast reporting can help freeze a transfer"},{"id":"f","text":"Only rich people can report cyber crime"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Anyone can report free at cybercrime.gov.in or 1930, and fast reporting helps; the rest are myths.","persona":"any","source":"reporting sort"},
  {"id":"kr-1036","cat":"cyber-and-data","type":"sort","hook":"Sort each habit: protects your privacy, or over-shares?","items":[{"id":"a","text":"Keeping your account private"},{"id":"b","text":"Posting your live location all day"},{"id":"c","text":"Reviewing what others tag you in"},{"id":"d","text":"Sharing your OTP 'just this once'"},{"id":"e","text":"Turning off location data in photos"},{"id":"f","text":"Putting your full address in your bio"}],"bins":[{"id":"private","label":"Protects privacy","valence":"pos"},{"id":"overshare","label":"Over-shares","valence":"neg"}],"key":{"a":"private","b":"overshare","c":"private","d":"overshare","e":"private","f":"overshare"},"relearn":"Private accounts, tag review and stripped location protect you; live location, OTPs and addresses don't.","persona":"any","source":"privacy habit sort"},
  {"id":"kr-1037","cat":"cyber-and-data","type":"role-play","hook":"A friend got scammed online and is too ashamed to report it.","relearn":"Online fraud is reportable; reassure a friend and help them call 1930 fast.","persona":"any","source":"shame to report","setup":"Lensy: take the shame off them. Say:","yourLine":[{"text":"\"This happens to careful people too; let's report it to 1930 now while it's fresh.\"","best":true},{"text":"\"You should've known better, just forget it.\""}]},
  {"id":"kr-1038","cat":"cyber-and-data","type":"role-play","hook":"A friend is being blackmailed over private photos and wants to just pay.","relearn":"Don't pay blackmailers; preserve evidence and report to 1930 or cybercrime.gov.in.","persona":"any","source":"blackmail support","setup":"Lensy: steady them and point to the route. Say:","yourLine":[{"text":"\"Don't pay. Save the messages and we'll report it to 1930; the crime is on them.\"","best":true},{"text":"\"Maybe just pay so it goes away quietly.\""}]},
  {"id":"kr-1039","cat":"cyber-and-data","type":"role-play","hook":"A 'bank' caller is pressuring you to read out an OTP right now.","relearn":"A bank never asks for your OTP; refuse and hang up.","persona":"any","source":"otp refusal","setup":"Lensy: hold your line on the call. Say:","yourLine":[{"text":"\"No bank needs my OTP. I'm hanging up and calling the number on my card.\"","best":true},{"text":"\"Okay, let me just read it out so you can help.\""}]},
  {"id":"kr-1040","cat":"cyber-and-data","type":"role-play","hook":"A younger cousin wants to send a private photo to someone they met online.","relearn":"Private images can be misused; you have every right to say no to a 'trust test'.","persona":"any","source":"private photo no","setup":"Lensy: back them up to refuse. Say:","yourLine":[{"text":"\"You don't owe anyone a private photo; real trust never makes it a test.\"","best":true},{"text":"\"If they asked nicely, maybe it's fine to send one.\""}]},
  {"id":"kr-1041","cat":"cyber-and-data","type":"role-play","hook":"A relative keeps forwarding 'win money' links and urging you to click.","relearn":"Forwarded reward-bait links are scams; you can decline without guilt.","persona":"any","source":"forward refusal","setup":"Lensy: decline the forward calmly. Say:","yourLine":[{"text":"\"I don't open prize links; they steal logins. Let's not forward this one on.\"","best":true},{"text":"\"Fine, I'll click it so you stop sending it.\""}]},
  {"id":"kr-1042","cat":"cyber-and-data","type":"role-play","hook":"A loan app threatens to message your contacts about your dues.","relearn":"Contact-shaming is harassment, not collection; save proof and report to 1930.","persona":"Meena","source":"loan app stand","setup":"Lensy: name it and stand firm. Say:","yourLine":[{"text":"\"Messaging my contacts is harassment. I'm saving this and reporting it to 1930.\"","best":true},{"text":"\"Please don't, I'll find the money somehow.\""}]},
  {"id":"kr-1043","cat":"cyber-and-data","type":"role-play","hook":"A new app insists you must allow every permission to continue.","relearn":"You can deny permissions an app doesn't need; your consent is yours.","persona":"any","source":"permission stand","setup":"Lensy: keep control of your data. Say:","yourLine":[{"text":"\"I'll allow only what it truly needs; my contacts and mic stay off.\"","best":true},{"text":"\"I'll just allow everything so it works.\""}]},
  {"id":"kr-1044","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which online safety habit feels most doable for you to start this week?","prompt":"There's no wrong pick; choose the one you'd actually keep up.","options":["Turn on two-step login somewhere","Make one account private","Stop reusing one password","Save the 1930 number in my phone"],"affirm":"Lensy: any of these makes you harder to scam. Starting small is still starting; your data, your call.","relearn":"One small safety habit at a time makes you harder to scam.","persona":"any","source":"habit reflect"},
  {"id":"kr-1045","cat":"cyber-and-data","type":"reflect","hook":"Lensy: a scam message just made you panic. What helps you slow down?","prompt":"Every answer is valid; notice what steadies you.","options":["Put the phone down for a minute","Tell someone what it said","Open the official app to check","Remember real services don't rush me"],"affirm":"Lensy: urgency is the trick, not the truth. A pause is your best defence; you don't owe a fast reply.","relearn":"Urgency is the scam's trick; a pause is your best defence.","persona":"any","source":"panic reflect"},
  {"id":"kr-1046","cat":"cyber-and-data","type":"reflect","hook":"Lensy: how much of your daily life feels comfortable to keep private online?","prompt":"There's no right amount; it's yours to decide.","options":["My location and address","Who I talk to","My photos","My account being public or not"],"affirm":"Lensy: privacy isn't hiding; it's choosing who gets in. Whatever you keep back is fully your right.","relearn":"Privacy is choosing who gets in; what you keep back is your right.","persona":"any","source":"privacy reflect"},
  {"id":"kr-1047","cat":"cyber-and-data","type":"reflect","hook":"Lensy: if you were scammed, what would help you report instead of staying silent?","prompt":"No answer is wrong; name what would lower the shame.","options":["Knowing it's common","Having the 1930 number ready","A friend doing it with me","Knowing it might recover money"],"affirm":"Lensy: being scammed is not a character flaw; it's a crime done to you. Reporting is strength, not shame.","relearn":"Being scammed is a crime done to you; reporting is strength, not shame.","persona":"any","source":"report reflect"},
  {"id":"kr-1048","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which would make you most willing to help a friend in a cyber mess?","prompt":"Any of these counts; pick what fits you.","options":["Knowing the right helpline","Not judging how it happened","Sitting with them while they report","Reminding them it's not their fault"],"affirm":"Lensy: a calm friend who knows the route changes everything. Showing up matters more than having all the answers.","relearn":"A calm friend who knows the route helps; showing up matters most.","persona":"any","source":"helping reflect"},
  {"id":"kr-1049","cat":"cyber-and-data","type":"reflect","hook":"Lensy: when an app asks for a permission, what would you like to ask yourself first?","prompt":"There's no single right question; choose your default.","options":["Does it really need this?","What could it do with this?","Can I say no and still use it?","Who else gets this data?"],"affirm":"Lensy: pausing on a permission is you owning your data. Every 'no' you mean is a right you're using.","relearn":"Pausing on a permission is owning your data; 'no' is a right.","persona":"any","source":"permission reflect"},
  {"id":"kr-1050","cat":"cyber-and-data","type":"reflect","hook":"Lensy: what would make a 'too good to be true' offer easier for you to walk away from?","prompt":"All of these are fine; pick what would anchor you.","options":["Remembering no prize asks for a fee","Talking it over with someone","Knowing guaranteed returns aren't real","Just not replying at all"],"affirm":"Lensy: if it guarantees fast money, it's bait. Walking away costs you nothing and keeps your savings yours.","relearn":"Guaranteed fast money is bait; walking away keeps your savings safe.","persona":"any","source":"offer reflect"},
  {"id":"kr-1051","cat":"cyber-and-data","type":"reflect","hook":"Lensy: which part of your online life would you most like to feel more in control of?","prompt":"No wrong answer; this is just for you.","options":["My passwords","What I share publicly","The apps on my phone","Knowing where to report harm"],"affirm":"Lensy: control online grows one habit at a time. Wherever you start, the rights and routes are already yours.","relearn":"Control online grows one habit at a time; the rights are already yours.","persona":"any","source":"control reflect"},
  {"id":"kr-1053","cat":"cyber-and-data","type":"match","hook":"Match each data right under DPDP to what it lets you do.","pairs":[{"left":"Right to access","right":"Ask what data is held about you"},{"left":"Right to correction","right":"Get wrong details fixed"},{"left":"Right to erasure","right":"Ask for data no longer needed to go"},{"left":"Right to withdraw consent","right":"Take back a yes you gave before"},{"left":"Right to grievance","right":"Complain if your data is misused"}],"relearn":"Under DPDP you can access, correct, erase, withdraw consent and complain about your data.","persona":"Farhan","source":"dpdp rights"},
  {"id":"kr-1054","cat":"cyber-and-data","type":"sort","hook":"Sort each money move online: safe, or risky?","items":[{"id":"a","text":"Paying through the official app"},{"id":"b","text":"Scanning a stranger's 'collect' QR"},{"id":"c","text":"Checking the payee name before sending"},{"id":"d","text":"Sharing your card CVV on a call"},{"id":"e","text":"Using two-step login on your wallet"},{"id":"f","text":"Approving a request you didn't start"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Pay in the official app, check the payee and use two-step login; never scan stranger QRs or share a CVV.","persona":"any","source":"money move sort"},
  {"id":"kr-1080","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Only women in big companies are covered by the harassment law.\"","myth":{"un":"Only women in big companies are covered.","re":"The Act covers women everywhere they work, including small shops, homes as workplaces and unorganised work.","why":"It protects women at any workplace, not just large offices."},"relearn":"The harassment law covers women at any workplace, not only big companies.","persona":"Meena","source":"covers everywhere"},
  {"id":"kr-1081","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"An intern can't complain about harassment.\"","myth":{"un":"An intern can't complain about harassment.","re":"Interns, trainees and contract workers can complain; the law protects them, not only permanent staff.","why":"The Act names interns and contract women too."},"relearn":"Interns and contract workers can complain about harassment; the law protects them too.","persona":"Aarti","source":"interns covered"},
  {"id":"kr-1082","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"If there were no witnesses, there's no point complaining.\"","myth":{"un":"With no witnesses, there's no point complaining.","re":"A complaint can stand on your own account plus messages, emails and patterns; witnesses are not required.","why":"Your testimony and records are evidence."},"relearn":"You can complain without witnesses; your account plus messages and records are evidence.","persona":"any","source":"no witness needed"},
  {"id":"kr-1083","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"He's senior, so nothing will happen to him.\"","myth":{"un":"He's senior, so nothing will happen to him.","re":"The complaint process applies to everyone, including bosses and owners; rank does not put anyone above it.","why":"Seniority is not immunity from a harassment complaint."},"relearn":"The complaint process applies to everyone, including seniors and owners; rank is not immunity.","persona":"Aarti","source":"rank no shield"},
  {"id":"kr-1084","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Reporting it will just get me labelled a troublemaker and sacked.\"","myth":{"un":"Reporting it gets you labelled and sacked.","re":"Punishing or sacking someone for a good-faith complaint is itself unlawful retaliation, not a normal consequence.","why":"The law forbids reprisal for complaining honestly."},"relearn":"Sacking or punishing you for a good-faith complaint is unlawful retaliation, not normal.","persona":"Meena","source":"retaliation unlawful"},
  {"id":"kr-1085","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"It was just a joke, so it doesn't count as harassment.\"","myth":{"un":"A 'joke' can't count as harassment.","re":"Unwelcome sexual jokes, comments or gestures can be harassment; what matters is that it's unwelcome, not that it's framed as fun.","why":"Harm isn't erased by calling it a joke."},"relearn":"Unwelcome sexual jokes and comments can be harassment; 'just a joke' doesn't erase it.","persona":"any","source":"a joke counts"},
  {"id":"kr-1086","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"You have to confront the harasser yourself first before anyone helps.\"","myth":{"un":"You must confront the harasser alone first.","re":"You can go straight to the Internal Committee; confronting the person yourself is never a required first step.","why":"The committee exists so you don't have to face it alone."},"relearn":"You can go straight to the Internal Committee; confronting them alone first is not required.","persona":"any","source":"no solo first"},
  {"id":"kr-1087","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"A creepy message at midnight isn't a work matter.\"","myth":{"un":"Off-hours messages aren't a work matter.","re":"Unwelcome sexual messages from a colleague or boss can be work harassment even after hours or off the premises.","why":"The work link, not the clock, is what matters."},"relearn":"Unwelcome sexual messages from a colleague count even after hours or off-site.","persona":"any","source":"off-hours counts"},
  {"id":"kr-1088","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Quid pro quo, like 'sleep with me for the promotion', is just office politics.\"","myth":{"un":"'Favours for a promotion' is just office politics.","re":"Tying a job, promotion or marks to sexual favours is a clear, named form of harassment, not politics.","why":"Conditioning work on sex is harassment in law."},"relearn":"Tying a job, promotion or marks to sexual favours is harassment, not office politics.","persona":"Aarti","source":"quid pro quo"},
  {"id":"kr-1089","cat":"harassment-and-posh","type":"strike-rewrite","hook":"\"Harassment only happens to women, so men have no route at all.\"","myth":{"un":"Only women face harassment, so men have no route.","re":"Anyone harassed has routes; a man facing sexual harassment can use workplace policy, complaints and the law too.","why":"No one has to just endure harassment at work."},"relearn":"Anyone harassed has a route; men facing harassment can use workplace policy and the law too.","persona":"any","source":"routes for all"},
  {"id":"kr-1090","cat":"harassment-and-posh","type":"match","hook":"Match each part of a harassment complaint to what it does.","pairs":[{"left":"Internal Committee","right":"Hears and inquires into the complaint"},{"left":"Written complaint","right":"Starts the formal process"},{"left":"Dated notes and messages","right":"Build your evidence"},{"left":"Confidentiality rule","right":"Keeps your identity protected"},{"left":"NALSA 15100","right":"Free legal help if you need it"}],"relearn":"A committee, a written complaint, dated evidence, confidentiality and free legal aid each play a role.","persona":"any","source":"parts of a complaint"},
  {"id":"kr-1091","cat":"harassment-and-posh","type":"match","hook":"Match the situation to who can complain.","pairs":[{"left":"Intern, 3-month stint","right":"Yes, interns are covered"},{"left":"Contract housekeeping staff","right":"Yes, contract workers are covered"},{"left":"Part-time worker","right":"Yes, part-timers are covered"},{"left":"Trainee from another city","right":"Yes, location doesn't remove the right"},{"left":"Permanent employee","right":"Yes, permanent staff are covered"}],"relearn":"Interns, contract, part-time, trainee and permanent women workers are all covered.","persona":"Meena","source":"who can complain"},
  {"id":"kr-1092","cat":"harassment-and-posh","type":"match","hook":"Match each behaviour to what kind of conduct it is.","pairs":[{"left":"Unwelcome touching","right":"Physical harassment"},{"left":"Repeated sexual comments","right":"Verbal harassment"},{"left":"Showing porn at a desk","right":"Creating a hostile space"},{"left":"A fair, polite work review","right":"Normal, fair feedback"},{"left":"\"Favours for a promotion\"","right":"Demanding sexual favours"}],"relearn":"Unwelcome touching, sexual comments, porn and favour-demands are harassment; a fair review is normal feedback.","persona":"any","source":"is it harassment"},
  {"id":"kr-1093","cat":"harassment-and-posh","type":"match","hook":"Match each myth to the truth that breaks it.","pairs":[{"left":"\"You'll lose your job for complaining\"","right":"Retaliation is itself unlawful"},{"left":"\"Only seniors are protected\"","right":"Interns and contract staff count too"},{"left":"\"You must prove it with witnesses\"","right":"Your account and records are evidence"},{"left":"\"Nothing can touch the boss\"","right":"The process applies to everyone"},{"left":"\"It's the price of a job\"","right":"Safety and dignity are a right"}],"relearn":"Each common myth about harassment has a clear truth that breaks it.","persona":"any","source":"myth to truth"},
  {"id":"kr-1094","cat":"harassment-and-posh","type":"match","hook":"Match the helpline or route to when you'd use it.","pairs":[{"left":"Internal Committee","right":"Workplace or college harassment"},{"left":"Women in distress 181","right":"A woman needing urgent support"},{"left":"Women's helpline 1091","right":"Help for women facing harm"},{"left":"NALSA 15100","right":"Free legal aid if you can't pay"},{"left":"Emergency 112","right":"Immediate danger right now"}],"relearn":"Different routes fit different needs: the committee, 181, 1091, NALSA 15100 and 112.","persona":"Farhan","source":"route by need"},
  {"id":"kr-1095","cat":"harassment-and-posh","type":"match","hook":"Match the step to where it belongs in handling harassment.","pairs":[{"left":"Note dates and save messages","right":"First, build your record"},{"left":"Write to the Internal Committee","right":"Then file the complaint"},{"left":"Ask about confidentiality","right":"Protect your identity in the process"},{"left":"Ask about interim relief","right":"Stay safe while it's inquired into"},{"left":"Get free legal aid if needed","right":"Support if you can't afford a lawyer"}],"relearn":"Record, file, ask about confidentiality and interim relief, and use free legal aid if needed.","persona":"any","source":"steps in order"},
  {"id":"kr-1096","cat":"harassment-and-posh","type":"match","hook":"Match each false belief to why it's wrong.","pairs":[{"left":"\"A joke can't be harassment\"","right":"Unwelcome sexual jokes can be"},{"left":"\"Off-hours doesn't count\"","right":"The work link matters, not the clock"},{"left":"\"You can't complain about a boss\"","right":"Owners and bosses aren't above it"},{"left":"\"You needed to refuse on day one\"","right":"There's a window to file, extendable"},{"left":"\"Men have no route\"","right":"Anyone harassed has a route"}],"relearn":"Jokes, off-hours acts, bosses, timing and gender myths all have clear answers.","persona":"any","source":"false belief why"},
  {"id":"kr-1097","cat":"harassment-and-posh","type":"branch","hook":"A senior keeps making sexual comments and you freeze each time.","options":[{"text":"Start a dated note of each incident, privately","consequence":"You build a record you can use later, on your terms.","outcome":"record","best":true},{"text":"Tell yourself you must be imagining it","consequence":"Doubting yourself doesn't stop it; a quiet dated record helps you act when ready."}],"debrief":"A private, dated record turns a blur of incidents into something you can act on later.","relearn":"Quietly note each incident with dates; a record helps you act when you're ready.","persona":"Aarti","source":"start a record"},
  {"id":"kr-1098","cat":"harassment-and-posh","type":"branch","hook":"HR says \"just sort it out between yourselves\" after you report harassment.","options":[{"text":"Ask for the Internal Committee and complain in writing","consequence":"You move it into the formal route that must inquire.","outcome":"formal","best":true},{"text":"Agree and drop it","consequence":"That's not the lawful process; the committee must inquire when you complain in writing."}],"debrief":"Harassment has a formal committee route; you needn't settle it informally.","relearn":"If told to 'sort it out yourselves', ask for the committee and complain in writing.","persona":"any","source":"refuse informal"},
  {"id":"kr-1099","cat":"harassment-and-posh","type":"branch","hook":"There's no harassment committee at your small workplace of 8 people.","options":[{"text":"Use the district Local Committee for small workplaces","consequence":"You reach the external committee meant for tiny workplaces.","outcome":"local","best":true},{"text":"Conclude there's no route at all","consequence":"Small workplaces are served by a district Local Committee; a route exists."}],"debrief":"Workplaces too small for an internal committee use a district Local Committee.","relearn":"A workplace too small for an internal committee has a district Local Committee.","persona":"Meena","source":"local committee"},
  {"id":"kr-1100","cat":"harassment-and-posh","type":"branch","hook":"A harasser warns: \"Complain and I'll make sure you never get hired here again.\"","options":[{"text":"Note the threat and report it with your complaint","consequence":"A threat for complaining is retaliation; logging it helps you.","outcome":"threat-logged","best":true},{"text":"Stay silent so he can't follow through","consequence":"Threatening you for complaining is itself unlawful; note and report it."}],"debrief":"A threat meant to silence your complaint is retaliation, and it belongs in the complaint.","relearn":"A threat for complaining is retaliation; note it and report it.","persona":"any","source":"threat is retaliation"},
  {"id":"kr-1101","cat":"harassment-and-posh","type":"branch","hook":"You missed the complaint window because you were too scared to file.","options":[{"text":"Ask the committee to extend the time","consequence":"The window can be extended for genuine reasons; just ask.","outcome":"extension","best":true},{"text":"Decide it's hopeless now","consequence":"The window can be extended for good reason; ask instead of giving up."}],"debrief":"The window can be extended for genuine reasons; a delay doesn't end your right.","relearn":"If you missed the window out of fear, ask the committee to extend it.","persona":"any","source":"window extendable"},
  {"id":"kr-1102","cat":"harassment-and-posh","type":"branch","hook":"A friend was harassed by a customer, not a colleague, at her job.","options":[{"text":"Tell her the employer still owes her a safe workplace","consequence":"Harassment by a customer is still the employer's duty.","outcome":"employer-duty","best":true},{"text":"Say nothing can be done since it wasn't staff","consequence":"An employer must keep the workplace safe even from a customer."}],"debrief":"Harassment by a customer is still a workplace safety issue the employer must address.","relearn":"Harassment by a customer is still the employer's duty; she can raise it.","persona":"any","source":"customer harasser"},
  {"id":"kr-1103","cat":"harassment-and-posh","type":"branch","hook":"You're asked to sign a 'mutual settlement' to quietly end your complaint.","options":[{"text":"Get free legal advice before signing anything","consequence":"You avoid signing rights away; NALSA 15100 advises free.","outcome":"advised","best":true},{"text":"Sign quickly to make it all stop","consequence":"Signing under pressure can waive rights; NALSA 15100 helps you decide."}],"debrief":"Don't sign under pressure; free legal advice shows what you'd give up.","relearn":"Before signing any settlement, get free legal advice; NALSA 15100 is free.","persona":"any","source":"settlement caution"},
  {"id":"kr-1104","cat":"harassment-and-posh","type":"branch","hook":"A junior confides she's being harassed and begs you to keep it secret.","options":[{"text":"Believe her, respect her pace, share the routes","consequence":"You support her without taking control from her.","outcome":"supported","best":true},{"text":"Report it over her head to look proactive","consequence":"Acting over her head can harm her; support her at her pace."}],"debrief":"Support a survivor at her pace: believe her and share routes, don't seize her choice.","relearn":"Believe her, move at her pace, and share the committee and helpline options.","persona":"Mehta","source":"support her pace"},
  {"id":"kr-1105","cat":"harassment-and-posh","type":"branch","hook":"During the inquiry you have to share the same room as the harasser daily.","options":[{"text":"Ask the committee for interim relief, like a transfer","consequence":"You use a built-in protection so you needn't face him.","outcome":"interim","best":true},{"text":"Quietly endure it until the inquiry ends","consequence":"You can ask for interim relief, like a transfer; don't just endure it."}],"debrief":"While an inquiry runs you can ask for interim relief, like a transfer or leave.","relearn":"Ask the committee for interim relief, like a transfer, during the inquiry.","persona":"any","source":"ask interim relief"},
  {"id":"kr-1106","cat":"harassment-and-posh","type":"branch","hook":"A professor implies your marks depend on meeting him alone after class.","options":[{"text":"Document it and complain to the college committee","consequence":"Marks-for-favours is harassment; the college has a committee.","outcome":"college-route","best":true},{"text":"Go along to protect your grade","consequence":"Marks-for-favours is harassment; document it, don't comply."}],"debrief":"A teacher tying marks to private meetings is harassment; colleges have a committee.","relearn":"Tying marks to private meetings is harassment; use the college committee.","persona":"Aarti","source":"college professor"},
  {"id":"kr-1107","cat":"harassment-and-posh","type":"branch","hook":"You worry your English isn't good enough to write a harassment complaint.","options":[{"text":"Write it in your own language and ask for help","consequence":"A complaint needs your words, not fancy English.","outcome":"own-words","best":true},{"text":"Give up because you can't write it 'properly'","consequence":"You can complain in your own language; free legal aid helps."}],"debrief":"A complaint can be in your own words and language; no legal English needed.","relearn":"You can complain in your own language; free legal aid helps.","persona":"Meena","source":"own language ok"},
  {"id":"kr-1108","cat":"harassment-and-posh","type":"branch","hook":"The committee dismisses your complaint and you feel it was unfair.","options":[{"text":"Ask about appealing and get free legal advice","consequence":"A decision isn't always the end; you can appeal. NALSA 15100 advises free.","outcome":"appeal","best":true},{"text":"Accept it as final and stay quiet","consequence":"You can usually appeal an unfair decision; NALSA 15100 helps you weigh it."}],"debrief":"A decision you feel is wrong can usually be appealed; free legal advice helps.","relearn":"If a decision feels unfair, ask about appealing; NALSA 15100 advises for free.","persona":"any","source":"appeal route"},
  {"id":"kr-1109","cat":"harassment-and-posh","type":"branch","hook":"A colleague says \"she probably led him on\" about a harassment complaint.","options":[{"text":"Push back: the fault is the harasser's, not hers","consequence":"You refuse victim-blaming and keep fault where it belongs.","outcome":"reframed","best":true},{"text":"Shrug and let the comment stand","consequence":"'She led him on' is victim-blaming; the fault is always the harasser's."}],"debrief":"Harassment isn't caused by the target; the fault is always the harasser's.","relearn":"The fault is the harasser's, never the target; push back on victim-blaming.","persona":"Rohan","source":"no victim blame"},
  {"id":"kr-1110","cat":"harassment-and-posh","type":"branch","hook":"You saved screenshots of harassing messages but the harasser deleted his.","options":[{"text":"Keep your saved copies safe and back them up","consequence":"Your screenshots stay valid evidence even after his are gone.","outcome":"preserved","best":true},{"text":"Assume it's worthless now that his are gone","consequence":"Your saved copies still count; back them up so they aren't lost."}],"debrief":"Evidence you preserve stays valid even if the other person deletes theirs.","relearn":"Your saved screenshots are still evidence even if his are deleted; back them up.","persona":"any","source":"preserve evidence"},
  {"id":"kr-1111","cat":"harassment-and-posh","type":"sort","hook":"Sort: a behaviour that can be sexual harassment, or not?","items":[{"id":"a","text":"Unwelcome comments about your body"},{"id":"b","text":"Demanding sexual favours for a promotion"},{"id":"c","text":"A manager giving honest, fair feedback"},{"id":"d","text":"Repeatedly sending unwanted explicit messages"},{"id":"e","text":"Being assigned a normal work task"},{"id":"f","text":"Unwanted touching at the desk"}],"bins":[{"id":"is","label":"Can be harassment","valence":"neg"},{"id":"not","label":"Not harassment","valence":"pos"}],"key":{"a":"is","b":"is","c":"not","d":"is","e":"not","f":"is"},"relearn":"Unwelcome comments, demands, explicit messages and touching can be harassment; fair feedback and normal tasks are not.","persona":"any","source":"is it harassment sort"},
  {"id":"kr-1112","cat":"harassment-and-posh","type":"sort","hook":"Sort: does this remove your right to complain, or not?","items":[{"id":"a","text":"You're only an intern"},{"id":"b","text":"You're on a short contract"},{"id":"c","text":"You're part-time"},{"id":"d","text":"The conduct was genuinely welcome to you"},{"id":"e","text":"You're a trainee from another city"},{"id":"f","text":"There was no unwelcome conduct at all"}],"bins":[{"id":"still","label":"Still covered","valence":"pos"},{"id":"none","label":"Nothing to complain of","valence":"neutral"}],"key":{"a":"still","b":"still","c":"still","d":"none","e":"still","f":"none"},"relearn":"Being an intern, contract, part-time or a trainee leaves you covered; only genuinely welcome conduct means there's nothing to complain of.","persona":"Meena","source":"who is covered sort"},
  {"id":"kr-1113","cat":"harassment-and-posh","type":"sort","hook":"Sort: speak up about this, or wait and watch?","items":[{"id":"a","text":"A boss demanding a date for your appraisal"},{"id":"b","text":"Unwanted explicit messages from a colleague"},{"id":"c","text":"A vague feeling you can't yet name"},{"id":"d","text":"Repeated unwelcome touching"},{"id":"e","text":"A single ambiguous joke you're unsure about"},{"id":"f","text":"A threat to sack you if you report"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"watch","label":"Watch a bit","valence":"uhoh"}],"key":{"a":"speak","b":"speak","c":"watch","d":"speak","e":"watch","f":"speak"},"relearn":"Clear demands, explicit messages, touching and threats are speak-up; a vague feeling or one ambiguous joke you can watch.","persona":"any","source":"speak or watch"},
  {"id":"kr-1114","cat":"harassment-and-posh","type":"sort","hook":"Sort each into the right place in a harassment complaint.","items":[{"id":"a","text":"Save dated messages and emails"},{"id":"b","text":"Write to the Internal Committee"},{"id":"c","text":"Ask about confidentiality"},{"id":"d","text":"Delete everything to avoid trouble"},{"id":"e","text":"Get free legal aid if you can't pay"},{"id":"f","text":"Tell no one and wait for years"}],"bins":[{"id":"do","label":"Helps your case","valence":"pos"},{"id":"avoid","label":"Hurts your case","valence":"neg"}],"key":{"a":"do","b":"do","c":"do","d":"avoid","e":"do","f":"avoid"},"relearn":"Saving evidence, filing, asking about confidentiality and getting free aid help; deleting evidence or long silence hurt.","persona":"any","source":"complaint do or avoid"},
  {"id":"kr-1115","cat":"harassment-and-posh","type":"sort","hook":"Sort: a real protection in the complaint process, or a myth?","items":[{"id":"a","text":"The process is confidential"},{"id":"b","text":"You can ask for interim relief"},{"id":"c","text":"Retaliation for complaining is allowed"},{"id":"d","text":"Free legal aid is available if you can't pay"},{"id":"e","text":"You must face the harasser alone"},{"id":"f","text":"The filing window can be extended"}],"bins":[{"id":"real","label":"Real protection","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"real","c":"myth","d":"real","e":"myth","f":"real"},"relearn":"Confidentiality, interim relief, free legal aid and an extendable window are real; allowed retaliation and forced solo confrontation are myths.","persona":"any","source":"protection or myth"},
  {"id":"kr-1116","cat":"harassment-and-posh","type":"sort","hook":"Sort each case to where it goes.","items":[{"id":"a","text":"Harassment by a coworker at the office"},{"id":"b","text":"Harassment by a teacher on campus"},{"id":"c","text":"A woman in immediate danger now"},{"id":"d","text":"Can't afford a lawyer"},{"id":"e","text":"Harassment at a 6-staff workplace"},{"id":"f","text":"A woman needing urgent support"}],"bins":[{"id":"committee","label":"A committee","valence":"neutral"},{"id":"helpline","label":"A helpline","valence":"tell"}],"key":{"a":"committee","b":"committee","c":"helpline","d":"helpline","e":"committee","f":"helpline"},"relearn":"Workplace and campus harassment go to a committee; danger, cost and urgent support go to helplines.","persona":"Farhan","source":"route sort"},
  {"id":"kr-1138","cat":"harassment-and-posh","type":"sort","hook":"Sort: is this on the harasser, or never the survivor's fault?","items":[{"id":"a","text":"Choosing to make unwelcome advances"},{"id":"b","text":"What the survivor was wearing"},{"id":"c","text":"Ignoring a clear 'no'"},{"id":"d","text":"The survivor smiling politely at work"},{"id":"e","text":"Sending the unwanted messages"},{"id":"f","text":"The survivor taking time to report"}],"bins":[{"id":"on-him","label":"On the harasser","valence":"neg"},{"id":"not-fault","label":"Never her fault","valence":"pos"}],"key":{"a":"on-him","b":"not-fault","c":"on-him","d":"not-fault","e":"on-him","f":"not-fault"},"relearn":"The advances, ignoring a 'no' and the messages are on the harasser; clothes, politeness and timing are never the survivor's fault.","persona":"any","source":"whose fault sort"},
  {"id":"kr-1117","cat":"harassment-and-posh","type":"role-play","hook":"A boss says \"be nice to me and I'll renew your contract.\"","setup":"You want to refuse clearly and on record. Say:","yourLine":[{"text":"\"My contract should depend on my work, not on this. I'm not okay with what you're suggesting.\"","best":true},{"text":"\"Haha, um, I'll think about it.\""}],"relearn":"Refuse a favours-for-contract demand clearly and put your refusal on record.","persona":"Meena","source":"refuse favours-for-contract"},
  {"id":"kr-1118","cat":"harassment-and-posh","type":"role-play","hook":"A colleague keeps 'joking' about your body and others laugh along.","setup":"You want to name it without apologising. Say:","yourLine":[{"text":"\"Those comments about my body aren't a joke to me. Please stop.\"","best":true},{"text":"\"It's fine, I guess, don't worry about it.\""}],"relearn":"You can name an unwelcome 'joke' and ask for it to stop, without apologising.","persona":"any","source":"name the joke"},
  {"id":"kr-1119","cat":"harassment-and-posh","type":"role-play","hook":"You're at the Internal Committee to file your complaint.","setup":"You want to ask for protection while it's heard. Say:","yourLine":[{"text":"\"I'd like this kept confidential, and I want to ask about interim relief while it's inquired into.\"","best":true},{"text":"\"Sorry to bother you, only if it's not too much trouble.\""}],"relearn":"At the committee you can ask for confidentiality and interim relief while your complaint is heard.","persona":"any","source":"ask at committee"},
  {"id":"kr-1120","cat":"harassment-and-posh","type":"role-play","hook":"A friend who was harassed says \"maybe I caused it somehow.\"","setup":"You want to put the fault where it belongs. Say:","yourLine":[{"text":"\"You didn't cause this. The fault is his, and the law is on your side.\"","best":true},{"text":"\"Well, maybe think about what you could've done differently.\""}],"relearn":"Tell a harassed friend they didn't cause it; the fault is the harasser's.","persona":"any","source":"fault is his"},
  {"id":"kr-1121","cat":"harassment-and-posh","type":"role-play","hook":"HR pressures you: \"just drop it, it'll be easier for everyone.\"","setup":"You want to hold your ground politely. Say:","yourLine":[{"text":"\"I'd like my complaint formally placed before the committee, please.\"","best":true},{"text":"\"Okay, if it makes things easier I'll let it go.\""}],"relearn":"You can politely insist your complaint be placed before the committee, not dropped.","persona":"Aarti","source":"hold your ground"},
  {"id":"kr-1122","cat":"harassment-and-posh","type":"role-play","hook":"A new intern asks you whether she's even allowed to complain.","setup":"You want to reassure her clearly. Say:","yourLine":[{"text":"\"Yes, interns are covered. You can complain to the committee, confidentially.\"","best":true},{"text":"\"Hmm, not sure interns count, better not risk it.\""}],"relearn":"Tell a worried intern she is covered and can complain to the committee confidentially.","persona":"Mehta","source":"intern reassure"},
  {"id":"kr-1123","cat":"harassment-and-posh","type":"role-play","hook":"Someone threatens to spread rumours if you report them.","setup":"You want to refuse to be silenced. Say:","yourLine":[{"text":"\"Threatening me for reporting is itself wrong, and I'm noting that too.\"","best":true},{"text":"\"Fine, I won't say anything, please don't tell people.\""}],"relearn":"A threat for reporting is itself wrong; you can refuse to be silenced and note the threat.","persona":"any","source":"refuse silencing"},
  {"id":"kr-1124","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: realising harassment is the harasser's wrong, not your shame, can lift a real weight. Does it?","prompt":"What do you think?","options":["It does","Not my shame","A weight lifts"],"affirm":"The shame was never yours to carry; harassment is the harasser's wrong, and naming that frees you to act.","relearn":"Harassment is the harasser's wrong, not your shame.","persona":"any","source":"not your shame"},
  {"id":"kr-1125","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: a safe, dignified workplace is something you're owed, not a favour you must earn. Sit with that?","prompt":"What do you think?","options":["Yes","I'm owed it","Not a favour"],"affirm":"Dignity at work isn't a perk handed to the lucky; it's owed to you, and the law backs that.","relearn":"A safe, dignified workplace is owed to you, not a favour you earn.","persona":"Meena","source":"owed not favour"},
  {"id":"kr-1126","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: knowing there's a confidential committee can make speaking up feel less frightening. Does it for you?","prompt":"What do you think?","options":["Yes","Less scary","Good to know"],"affirm":"A confidential route means speaking up doesn't have to mean exposure; that can make the first step feel possible.","relearn":"A confidential committee can make speaking up feel less frightening.","persona":"any","source":"less frightening"},
  {"id":"kr-1127","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: supporting a harassed colleague, even quietly, can change how alone they feel. Worth doing?","prompt":"What do you think?","options":["Yes","Worth it","I'd help"],"affirm":"One believing voice can break the isolation harassment creates; your support genuinely matters.","relearn":"Supporting a harassed colleague, even quietly, eases how alone they feel.","persona":"Rohan","source":"support matters"},
  {"id":"kr-1128","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: you can take it at your own pace. There's no rule that you must report the instant it happens. Reassuring?","prompt":"What do you think?","options":["Yes","My pace","Reassuring"],"affirm":"There's a window, and it can extend; you get to choose when you're ready, not be rushed.","relearn":"You can report at your own pace; there's a window and it can be extended.","persona":"any","source":"your own pace"},
  {"id":"kr-1129","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: even a small workplace or short internship doesn't put you outside these protections. Good to know?","prompt":"What do you think?","options":["Yes","I'm covered","Good to know"],"affirm":"Small employer, short stint, contract role: none of it places you outside the right to a safe workplace.","relearn":"A small workplace or short internship doesn't put you outside these protections.","persona":"Aarti","source":"still covered"},
  {"id":"kr-1130","cat":"harassment-and-posh","type":"reflect","hook":"Lensy: free legal aid means claiming this right never has to depend on how much money you have. Sit with that?","prompt":"What do you think?","options":["Yes","Money-free","Reassuring"],"affirm":"Your rights don't have a price tag; free legal aid exists so cost is never what stops you.","relearn":"Free legal aid means claiming this right doesn't depend on having money.","persona":"Farhan","source":"not about money"},
  {"id":"kr-1131","cat":"harassment-and-posh","type":"spot","hook":"Spot the two lines that are harassment myths, not facts.","scene":[{"id":"a","text":"You can complain even without witnesses","trick":false},{"id":"b","text":"Interns and contract staff aren't really covered","trick":true},{"id":"c","text":"The complaint process is confidential","trick":false},{"id":"d","text":"You must always confront the harasser alone first","trick":true},{"id":"e","text":"Retaliation for a good-faith complaint is unlawful","trick":false}],"why":"'Interns aren't covered' and 'you must confront them alone' are myths; the rest are true.","relearn":"Interns are covered and you needn't confront anyone alone first; those two are myths.","persona":"any","source":"spot the myths"},
  {"id":"kr-1132","cat":"harassment-and-posh","type":"spot","hook":"Spot the two things that are NOT how a fair process works.","scene":[{"id":"a","text":"Your identity is kept confidential","trick":false},{"id":"b","text":"You can ask for interim relief","trick":false},{"id":"c","text":"You get punished for complaining","trick":true},{"id":"d","text":"You're forced to settle privately with him","trick":true},{"id":"e","text":"Free legal aid is there if you can't pay","trick":false}],"why":"Punishment for complaining and a forced private settlement are both wrong; the rest are right.","relearn":"Punishment for complaining and a forced settlement are wrong; confidentiality and free aid are right.","persona":"any","source":"spot unfair"},
  {"id":"kr-1133","cat":"harassment-and-posh","type":"spot","hook":"Spot the two lines a harasser uses to silence you.","scene":[{"id":"a","text":"\"No one will believe an intern over me\"","trick":true},{"id":"b","text":"You have a right to a safe workplace","trick":false},{"id":"c","text":"\"Complain and your career is finished here\"","trick":true},{"id":"d","text":"The process is meant to protect your identity","trick":false},{"id":"e","text":"Retaliation for complaining is itself unlawful","trick":false}],"why":"'No one will believe an intern' and 'your career is finished' are silencing tactics; the rest are your real protections.","relearn":"Disbelief and career threats are silencing tactics; your protections are real.","persona":"any","source":"spot silencing"},
  {"id":"kr-1134","cat":"harassment-and-posh","type":"spot","hook":"Spot the two claims that are victim-blaming, not fact.","scene":[{"id":"a","text":"The fault for harassment is the harasser's","trick":false},{"id":"b","text":"\"She must have invited it somehow\"","trick":true},{"id":"c","text":"\"What was she wearing, anyway?\"","trick":true},{"id":"d","text":"You can complain confidentially","trick":false},{"id":"e","text":"Harassment is never the price of a job","trick":false}],"why":"'She invited it' and 'what was she wearing' shift blame to the target; the rest keep fault where it belongs.","relearn":"'She invited it' and 'what was she wearing' are victim-blaming; the fault is always the harasser's.","persona":"any","source":"spot victim-blaming"},
  {"id":"kr-1135","cat":"harassment-and-posh","type":"spot","hook":"Spot the two steps that would weaken a harassment complaint.","scene":[{"id":"a","text":"Saving dated messages and emails","trick":false},{"id":"b","text":"Deleting everything to avoid drama","trick":true},{"id":"c","text":"Writing to the Internal Committee","trick":false},{"id":"d","text":"Telling no one and waiting many years","trick":true},{"id":"e","text":"Asking about confidentiality","trick":false}],"why":"Deleting evidence and a long silence weaken a complaint; saving records, filing and asking about confidentiality strengthen it.","relearn":"Deleting evidence and long silence weaken a complaint; saving records and filing strengthen it.","persona":"any","source":"spot weakeners"},
  {"id":"kr-1136","cat":"harassment-and-posh","type":"spot","hook":"Spot the two things that do NOT remove your right to complain.","scene":[{"id":"a","text":"Being only an intern","trick":true},{"id":"b","text":"Genuinely giving your consent to the conduct","trick":false},{"id":"c","text":"Working at a tiny 5-person shop","trick":true},{"id":"d","text":"The conduct actually being welcome to you","trick":false},{"id":"e","text":"There being no harassment at all","trick":false}],"why":"Being an intern or at a tiny shop doesn't remove the right; genuine consent or welcome conduct means there's no harassment to complain of.","relearn":"Being an intern or at a tiny workplace doesn't remove your right to complain.","persona":"any","source":"spot non-barriers"},
  {"id":"kr-1137","cat":"harassment-and-posh","type":"spot","hook":"Spot the two replies that would shut a survivor down.","scene":[{"id":"a","text":"\"I believe you, and it's not your fault\"","trick":false},{"id":"b","text":"\"Are you sure you're not overreacting?\"","trick":true},{"id":"c","text":"\"You can complain confidentially, at your pace\"","trick":false},{"id":"d","text":"\"Maybe just don't make a fuss\"","trick":true},{"id":"e","text":"\"There's a committee that has to look into this\"","trick":false}],"why":"'Are you overreacting' and 'don't make a fuss' shut a survivor down; the others believe and inform them.","relearn":"'Are you overreacting' and 'don't make a fuss' shut a survivor down; believe and inform instead.","persona":"Mehta","source":"spot shutdowns"},
  {"id":"kr-1170","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A verbal rent deal is enough; paper just slows things down.\"","myth":{"un":"A verbal rent deal is enough; paper just slows things down.","re":"A written rent agreement records terms and protects both tenant and landlord.","why":"If there's a dispute later, a verbal-only deal is very hard to prove."},"relearn":"Get the rent terms in writing; a written agreement protects both sides.","persona":"Meena","source":"written agreement"},
  {"id":"kr-1171","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Tenants have no rights; the landlord can throw you out any day.\"","myth":{"un":"Tenants have no rights; the landlord can throw you out any day.","re":"'Instant eviction' is a myth; eviction has to follow the agreement and due process.","why":"A landlord can't lawfully turn you out overnight without proper notice."},"relearn":"'Instant eviction' and 'tenants have no rights' are myths.","persona":"Meena","source":"eviction myth"},
  {"id":"kr-1172","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"No bill means you can't complain about a faulty phone.\"","myth":{"un":"No bill means you can't complain about a faulty phone.","re":"You have consumer rights on defective goods, and a bill is the simplest proof, so always keep it.","why":"Without proof the complaint is harder, which is exactly why you save the bill."},"relearn":"Keep the bill; it's your simplest proof for a faulty-goods complaint.","persona":"any","source":"keep the bill"},
  {"id":"kr-1173","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Once you've paid, a deal is final and can't be questioned.\"","myth":{"un":"Once you've paid, a deal is final and can't be questioned.","re":"Consumer law lets you seek refund or replacement for a defective good even after paying.","why":"Paying doesn't sign away your rights when the product is faulty."},"relearn":"Paying doesn't end your rights; defective goods can still be refunded or replaced.","persona":"any","source":"after paying"},
  {"id":"kr-1174","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Brokerage and a year's rent up front are normal; just pay it.\"","myth":{"un":"Brokerage and a year's rent up front are normal; just pay it.","re":"You can ask what each charge is for and get a receipt; nothing has to be paid blindly.","why":"An itemised, receipted demand is how you tell a real charge from an inflated one."},"relearn":"Ask what each charge is for and get a receipt before you pay.","persona":"Meena","source":"upfront charges"},
  {"id":"kr-1175","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"A 'no refund, no exchange' board means you've no rights.\"","myth":{"un":"A 'no refund, no exchange' board means you've no rights.","re":"A shop notice can't cancel your consumer rights on a genuinely defective good.","why":"A store sign doesn't override the law on faulty products."},"relearn":"A 'no refund' sign can't take away your rights on a defective good.","persona":"any","source":"no refund sign"},
  {"id":"kr-1176","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"Asking for the deposit back will just get you a bad name.\"","myth":{"un":"Asking for the deposit back will just get you a bad name.","re":"Asking for your returnable deposit is a normal, fair request, not a quarrel.","why":"A deposit is your money held in trust, not a gift to the landlord."},"relearn":"Asking for your returnable deposit back is fair and normal.","persona":"any","source":"deposit is yours"},
  {"id":"kr-1177","cat":"renting-and-consumer","type":"strike-rewrite","hook":"\"An online order gone wrong is just bad luck; you can't do anything.\"","myth":{"un":"An online order gone wrong is just bad luck; you can't do anything.","re":"Online buyers have the same consumer rights, plus a complaint route for the defect or non-delivery.","why":"Buying online doesn't lower your protection on faulty or undelivered goods."},"relearn":"Online buyers have consumer rights too, with a real complaint route.","persona":"any","source":"online consumer"},
  {"id":"kr-1178","cat":"renting-and-consumer","type":"branch","hook":"Your landlord raises rent mid-lease and threatens to lock you out if you refuse.","options":[{"text":"Point to the agreement and ask for any change in writing","consequence":"You hold them to what was agreed.","outcome":"held","best":true},{"text":"Pay the higher rent at once to avoid trouble","consequence":"A lock-out threat isn't lawful eviction; the signed terms bind both sides."}],"debrief":"A signed lease binds both sides; mid-lease changes belong in writing.","relearn":"Hold a landlord to the signed terms; any change should be in writing.","persona":"Meena","source":"mid-lease change"},
  {"id":"kr-1179","cat":"renting-and-consumer","type":"branch","hook":"You move out spotless, but the landlord won't return your deposit.","options":[{"text":"Share move-in photos and ask for the amount by a set date","consequence":"You make a clear, evidenced demand.","outcome":"evidenced","best":true},{"text":"Just keep calling angrily with no records","consequence":"Evidence beats anger; your move-in photos and a dated request make the stronger case for the money."}],"debrief":"Documented condition plus a dated, specific request is how you claim a returnable deposit.","relearn":"Use move-in photos and a dated request to claim a withheld deposit.","persona":"any","source":"deposit return"},
  {"id":"kr-1180","cat":"renting-and-consumer","type":"branch","hook":"A washing machine fails in warranty and the shop says 'company problem, not ours'.","options":[{"text":"Show the bill and warranty; ask for repair or replacement","consequence":"You use your proof to claim the remedy.","outcome":"claimed","best":true},{"text":"Buy a new one and absorb the cost","consequence":"They can't just pass you around; a valid bill and warranty back a repair or replacement."}],"debrief":"A valid bill and warranty support repair, replacement or refund on a defective good.","relearn":"Use the bill and warranty to claim repair or replacement for a faulty good.","persona":"any","source":"warranty claim"},
  {"id":"kr-1181","cat":"renting-and-consumer","type":"branch","hook":"A delivered product is clearly defective and the seller stops replying.","options":[{"text":"Send a written complaint and use the consumer route","consequence":"You escalate properly with a record.","outcome":"escalated","best":true},{"text":"Keep messaging the silent seller and hope","consequence":"A written complaint and the consumer route can get a remedy; messaging a silent seller can't."}],"debrief":"For a silent seller, a written complaint and the consumer route are the escalation.","relearn":"For a silent seller, file a written complaint and use the consumer route.","persona":"any","source":"silent seller"},
  {"id":"kr-1182","cat":"renting-and-consumer","type":"branch","hook":"A 'broker' asks for a token deposit by UPI for a flat you've only seen in photos.","options":[{"text":"Refuse to pay until you've seen the flat and met the owner","consequence":"You avoid the classic unseen-rental trap.","outcome":"avoided","best":true},{"text":"Pay the token so you don't lose the deal","consequence":"Pay-before-viewing is a common scam; see the flat and meet the owner before any money moves."}],"debrief":"Upfront money for an unseen rental is a classic scam pattern.","relearn":"Don't pay for an unseen rental; verify the flat and owner first.","persona":"any","source":"unseen rental"},
  {"id":"kr-1183","cat":"renting-and-consumer","type":"branch","hook":"At a job-linked hostel, the warden keeps your ID and says rent rules can change anytime.","options":[{"text":"Ask for the terms in writing and keep your own ID","consequence":"You set the stay on a clear, fair footing.","outcome":"clear","best":true},{"text":"Hand over the ID and accept whatever they say","consequence":"You can keep your own ID and ask for written terms; rules shouldn't just change at will."}],"debrief":"Even in job-linked housing, you can ask for written terms and keep your ID.","relearn":"Ask for written terms and keep your own ID in any rented housing.","persona":"Meena","source":"hostel terms"},
  {"id":"kr-1184","cat":"renting-and-consumer","type":"branch","hook":"You spot a hidden 'non-refundable maintenance' charge in the rent agreement before signing.","options":[{"text":"Ask the landlord to explain or remove the unclear clause first","consequence":"You fix the terms before they bind you.","outcome":"fixed","best":true},{"text":"Sign now and argue about it later","consequence":"Questioning a clause before signing is far easier than undoing it after, so raise it now."}],"debrief":"Question and settle unclear clauses before you sign, not after.","relearn":"Question unclear clauses before signing, not after.","persona":"any","source":"hidden clause"},
  {"id":"kr-1185","cat":"renting-and-consumer","type":"branch","hook":"A shopkeeper insists a defective mixer can 'only be repaired', not replaced or refunded.","options":[{"text":"Note that consumer law allows refund or replacement, not just repair","consequence":"You assert the fuller set of remedies.","outcome":"asserted","best":true},{"text":"Accept the repair even though it keeps failing","consequence":"For a defective good, refund or replacement is on the table too, not just a repair."}],"debrief":"For a defective good, remedies can include refund or replacement.","relearn":"Defective goods can be refunded or replaced, not just repaired.","persona":"any","source":"only repair"},
  {"id":"kr-1186","cat":"renting-and-consumer","type":"branch","hook":"You realise the deposit you paid in cash has no receipt and the landlord now denies it.","options":[{"text":"Gather any UPI, chat or witness proof and insist on receipts from now","consequence":"You rebuild a trail and prevent a repeat.","outcome":"rebuilt","best":true},{"text":"Argue verbally with no proof at all","consequence":"Any UPI, chat or witness record helps; a verbal-only fight with no proof rarely lands."}],"debrief":"Cash with no receipt is the weak spot; any UPI or chat record helps.","relearn":"Always get a receipt; collect any UPI or chat proof if you didn't.","persona":"Meena","source":"cash deposit"},
  {"id":"kr-1187","cat":"renting-and-consumer","type":"branch","hook":"An app shows your parcel 'delivered' though it never reached you; support keeps closing the ticket.","options":[{"text":"Keep written records and escalate via the consumer route","consequence":"You build a case beyond app support.","outcome":"escalated","best":true},{"text":"Open and close new tickets endlessly","consequence":"The consumer route exists beyond app support; records move a false-'delivered' case."}],"debrief":"A false 'delivered' is a non-delivery dispute; records plus the consumer route help.","relearn":"For a false 'delivered', keep records and use the consumer route.","persona":"any","source":"non-delivery"},
  {"id":"kr-1188","cat":"renting-and-consumer","type":"branch","hook":"Your flatmates left and the landlord wants you to forfeit the whole shared deposit alone.","options":[{"text":"Refer to the agreement and ask what is actually owed","consequence":"You tie any deduction to documented facts.","outcome":"tied","best":true},{"text":"Pay the full forfeit to end the argument","consequence":"Deductions should be genuine and documented; ask for an itemised account before forfeiting all."}],"debrief":"A deposit is forfeited only for genuine, documented dues.","relearn":"Deductions must be genuine and documented; ask for an itemised account.","persona":"any","source":"shared deposit"},
  {"id":"kr-1189","cat":"renting-and-consumer","type":"branch","hook":"A 'limited offer' salesman pressures you to sign a costly water-purifier EMI on the spot.","options":[{"text":"Decline to sign today and read the full terms calmly first","consequence":"You avoid a pressured, unread commitment.","outcome":"avoided","best":true},{"text":"Sign quickly because the 'offer ends today'","consequence":"On-the-spot urgency is the tactic; reading terms before signing protects you."}],"debrief":"'Offer ends today' pressure is a red flag; read before you sign an EMI.","relearn":"Don't sign under on-the-spot pressure; read the full terms first.","persona":"any","source":"pressure sale"},
  {"id":"kr-1190","cat":"renting-and-consumer","type":"branch","hook":"A repair shop returns your laptop worse and refuses to fix it or refund the fee.","options":[{"text":"Keep the job-card and bill; use the consumer route for poor service","consequence":"You treat poor service as a claimable issue.","outcome":"claimed","best":true},{"text":"Pay again at another shop and forget it","consequence":"Deficient service is covered too; job-card and bill back a complaint, so keep them."}],"debrief":"Deficient service, not just faulty goods, is covered; job-card and bill are proof.","relearn":"Deficient service is covered too; keep the job-card and bill.","persona":"any","source":"bad service"},
  {"id":"kr-1191","cat":"renting-and-consumer","type":"branch","hook":"A landlord asks you to sign a rent agreement that's blank in the rent and deposit boxes.","options":[{"text":"Refuse to sign until every amount is filled in front of you","consequence":"You stop the terms from being changed later.","outcome":"stopped","best":true},{"text":"Sign now; they promise to fill it 'correctly' later","consequence":"Blank boxes can be filled against you and a verbal promise can't be proved."}],"debrief":"Never sign a part-blank agreement; have every amount filled first.","relearn":"Never sign an agreement with blank amounts; get them filled first.","persona":"Meena","source":"blank agreement"},
  {"id":"kr-1192","cat":"renting-and-consumer","type":"branch","hook":"You bought a phone that overheats; the seller says 'use it a month, then we'll see'.","options":[{"text":"Report the defect in writing now; keep the bill and warranty","consequence":"You log the fault inside the warranty window.","outcome":"logged","best":true},{"text":"Wait a month as told, recording nothing","consequence":"Log the defect in writing now; quietly waiting can weaken a warranty claim later."}],"debrief":"Report a defect in writing early and keep your bill and warranty.","relearn":"Report a defect in writing early; keep the bill and warranty.","persona":"any","source":"defect window"},
  {"id":"kr-1193","cat":"renting-and-consumer","type":"branch","hook":"A PG owner threatens to keep your bag unless you pay a surprise 'cleaning charge'.","options":[{"text":"Ask for the charge in writing with a receipt, calmly","consequence":"You tell a fair charge from a hostage tactic.","outcome":"separated","best":true},{"text":"Pay whatever they demand to get your bag","consequence":"Holding your things to force payment isn't fair; ask for it in writing with a receipt."}],"debrief":"A fair charge comes in writing with a receipt; a hostage move doesn't.","relearn":"Ask for any charge in writing with a receipt; your things shouldn't be held hostage.","persona":"Meena","source":"pg exit"},
  {"id":"kr-1194","cat":"renting-and-consumer","type":"branch","hook":"A gym takes a year's fee up front, then shuts within two months with no refund.","options":[{"text":"Keep the receipt and pursue the consumer route for the unused service","consequence":"You treat the lost service as a claimable issue.","outcome":"claimed","best":true},{"text":"Shrug it off as money gone","consequence":"A prepaid service that stops can be a consumer claim; your receipt is the proof to pursue it."}],"debrief":"A prepaid service cut short is a consumer matter; the receipt is proof.","relearn":"A prepaid service that stops can be a consumer claim; keep the receipt.","persona":"any","source":"prepaid service"},
  {"id":"kr-1195","cat":"renting-and-consumer","type":"sort","hook":"Sort: a fair deposit deduction, or an unfair one?","items":[{"id":"a","text":"Cost of a wall you actually damaged, with a bill"},{"id":"b","text":"'Just because' with no reason given"},{"id":"c","text":"A documented unpaid utility bill"},{"id":"d","text":"Normal wear like faded paint over years"},{"id":"e","text":"A broken window you caused, with a quote"},{"id":"f","text":"A round figure cut to keep some of it"}],"bins":[{"id":"fair","label":"Fair, documented","valence":"pos"},{"id":"unfair","label":"Unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Deductions must be genuine and documented; 'just because' and normal wear aren't fair.","persona":"any","source":"fair deductions"},
  {"id":"kr-1196","cat":"renting-and-consumer","type":"sort","hook":"Sort: covered by consumer law, or not a consumer issue?","items":[{"id":"a","text":"A defective good you bought"},{"id":"b","text":"A service that was clearly deficient"},{"id":"c","text":"A gift someone freely gave you"},{"id":"d","text":"Misleading false advertising"},{"id":"e","text":"A fee you paid for a service"},{"id":"f","text":"A casual favour from a friend"}],"bins":[{"id":"covered","label":"Consumer law covers it","valence":"pos"},{"id":"not","label":"Not a consumer issue","valence":"neutral"}],"key":{"a":"covered","b":"covered","c":"not","d":"covered","e":"covered","f":"not"},"relearn":"Consumer law covers paid goods, services and misleading ads; free gifts and favours aren't consumer deals.","persona":"any","source":"what counts"},
  {"id":"kr-1197","cat":"renting-and-consumer","type":"sort","hook":"Sort: smart before paying a deposit, or risky?","items":[{"id":"a","text":"Seeing the actual room first"},{"id":"b","text":"Paying a stranger before any viewing"},{"id":"c","text":"Getting a receipt for the money"},{"id":"d","text":"Paying instantly under pressure"},{"id":"e","text":"Meeting the real owner"},{"id":"f","text":"Sending UPI to a 'broker' you can't verify"}],"bins":[{"id":"smart","label":"Smart","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"See the place, meet the owner and get a receipt; pre-viewing pay and pressure are risky.","persona":"any","source":"before deposit"},
  {"id":"kr-1198","cat":"renting-and-consumer","type":"sort","hook":"Sort: belongs in a rent agreement, or doesn't belong at all?","items":[{"id":"a","text":"Rent amount and due date"},{"id":"b","text":"A clause taking your ID forever"},{"id":"c","text":"Deposit amount and return terms"},{"id":"d","text":"'Landlord may keep deposit for any reason'"},{"id":"e","text":"Notice period for leaving"},{"id":"f","text":"'Tenant waives all rights'"}],"bins":[{"id":"belongs","label":"Fair to include","valence":"pos"},{"id":"nope","label":"Should not be there","valence":"neg"}],"key":{"a":"belongs","b":"nope","c":"belongs","d":"nope","e":"belongs","f":"nope"},"relearn":"Rent, deposit terms and notice belong; clauses seizing your ID or waiving all rights don't.","persona":"any","source":"agreement clauses"},
  {"id":"kr-1199","cat":"renting-and-consumer","type":"sort","hook":"Sort: strong proof in a dispute, or weak proof?","items":[{"id":"a","text":"A signed, stamped rent agreement"},{"id":"b","text":"'He said it was fine over chai'"},{"id":"c","text":"A dated UPI payment record"},{"id":"d","text":"A vague memory of the amount"},{"id":"e","text":"Move-in photos with a timestamp"},{"id":"f","text":"A friend's second-hand account"}],"bins":[{"id":"strong","label":"Strong proof","valence":"pos"},{"id":"weak","label":"Weak proof","valence":"uhoh"}],"key":{"a":"strong","b":"weak","c":"strong","d":"weak","e":"strong","f":"weak"},"relearn":"Signed papers, dated payments and timestamped photos are strong proof; hearsay and memory are weak.","persona":"any","source":"proof strength"},
  {"id":"kr-1200","cat":"renting-and-consumer","type":"sort","hook":"Sort: a real consumer remedy, or a myth about your options?","items":[{"id":"a","text":"Refund for a defective good"},{"id":"b","text":"'A no-refund sign ends your rights'"},{"id":"c","text":"Replacement of a faulty product"},{"id":"d","text":"'Once paid, nothing can be done'"},{"id":"e","text":"A complaint route for bad service"},{"id":"f","text":"'Online buys have no protection'"}],"bins":[{"id":"real","label":"Real remedy","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Refund, replacement and complaint routes are real; no-refund signs and 'nothing can be done' are myths.","persona":"any","source":"remedy or myth"},
  {"id":"kr-1201","cat":"renting-and-consumer","type":"match","hook":"Match each rental record to what it proves.","pairs":[{"left":"Signed rent agreement","right":"The agreed terms"},{"left":"Timestamped move-in photos","right":"The room's condition"},{"left":"Deposit UPI record","right":"What you paid as deposit"},{"left":"Itemised exit account","right":"Why any amount was cut"},{"left":"Notice you sent in writing","right":"That you gave proper notice"}],"relearn":"Each rental record proves one thing; together they protect you in a deposit or rent dispute.","persona":"any","source":"record to proof"},
  {"id":"kr-1202","cat":"renting-and-consumer","type":"match","hook":"Match each consumer problem to its remedy.","pairs":[{"left":"A defective product","right":"Refund or replacement"},{"left":"A deficient paid service","right":"A consumer complaint"},{"left":"A non-delivered online order","right":"Records plus the consumer route"},{"left":"A misleading advertisement","right":"A complaint about false claims"},{"left":"A faulty good under warranty","right":"Repair using bill and warranty"}],"relearn":"Each consumer problem has a matching route; the remedy depends on the kind of harm.","persona":"any","source":"problem to remedy"},
  {"id":"kr-1203","cat":"renting-and-consumer","type":"match","hook":"Match the rental myth to the truth that corrects it.","pairs":[{"left":"'Instant eviction anytime'","right":"Eviction needs notice and process"},{"left":"'Tenants have no rights'","right":"A rent agreement protects you"},{"left":"'Deposit kept for any reason'","right":"Returnable minus documented dues"},{"left":"'Verbal deals are enough'","right":"Put the terms in writing"},{"left":"'Cash with no receipt is fine'","right":"Always get a receipt"}],"relearn":"Each common rental myth has a plain, factual correction.","persona":"any","source":"myth to truth"},
  {"id":"kr-1204","cat":"renting-and-consumer","type":"match","hook":"Match the consumer claim to the proof that supports it.","pairs":[{"left":"A faulty appliance","right":"The bill and warranty"},{"left":"A non-delivery","right":"The order and 'delivered' screenshot"},{"left":"A deficient repair","right":"The job-card and receipt"},{"left":"A false-ad purchase","right":"The advert and the actual product"},{"left":"An overcharge","right":"The price tag and the bill"}],"relearn":"Every consumer claim is stronger with the right proof kept and shown.","persona":"any","source":"claim to proof"},
  {"id":"kr-1205","cat":"renting-and-consumer","type":"match","hook":"Match each rent-agreement term to what it does for you.","pairs":[{"left":"Notice period","right":"Time to plan a move"},{"left":"Deposit return clause","right":"How your money comes back"},{"left":"Maintenance responsibility","right":"Who fixes what"},{"left":"Rent and due date","right":"What you owe and when"},{"left":"Lock-in or exit terms","right":"How either side can end it"}],"relearn":"A good rent agreement spells out money, notice, repairs and exit, so nothing is left to guesswork.","persona":"Meena","source":"agreement terms"},
  {"id":"kr-1206","cat":"renting-and-consumer","type":"spot","hook":"Spot the two red flags in this rental listing chat.","relearn":"Pre-payment for an unseen flat and a refusal to meet are classic rental-scam signs.","persona":"any","source":"listing red flags","scene":[{"id":"a","text":"'Send the token now or I give it to someone else'","trick":true},{"id":"b","text":"'Come see the flat this weekend'","trick":false},{"id":"c","text":"'I'm abroad, just pay; I can't meet you'","trick":true},{"id":"d","text":"'I'll give a receipt for the deposit'","trick":false},{"id":"e","text":"'Here's the owner's number, please verify'","trick":false}],"why":"Instant-pay pressure and a seller who won't meet you are classic rental-scam red flags."},
  {"id":"kr-1207","cat":"renting-and-consumer","type":"spot","hook":"Spot the two unfair terms in this rent agreement.","relearn":"Clauses seizing your ID or letting a landlord keep the deposit for any reason are unfair.","persona":"any","source":"unfair terms","scene":[{"id":"a","text":"'Tenant must surrender ID card to landlord'","trick":true},{"id":"b","text":"'Rent is due by the 5th each month'","trick":false},{"id":"c","text":"'Landlord may keep the deposit for any reason'","trick":true},{"id":"d","text":"'One month's notice to leave'","trick":false},{"id":"e","text":"'Deposit returns minus documented damage'","trick":false}],"why":"Surrendering your ID and 'keep the deposit for any reason' are the unfair clauses to catch."},
  {"id":"kr-1208","cat":"renting-and-consumer","type":"spot","hook":"Spot the two warning signs in this online deal.","relearn":"Deals that block proof, like no bill and prepaid-only with no returns, are warning signs.","persona":"any","source":"online warning","scene":[{"id":"a","text":"'No bill or invoice will be given'","trick":true},{"id":"b","text":"'You'll get a GST invoice by email'","trick":false},{"id":"c","text":"'Prepaid only, and absolutely no returns'","trick":true},{"id":"d","text":"'Cash on delivery is available'","trick":false},{"id":"e","text":"'There's a clear return window'","trick":false}],"why":"No bill and 'prepaid only, no returns' strip away your proof and remedies; those are the warning signs."},
  {"id":"kr-1209","cat":"renting-and-consumer","type":"spot","hook":"Spot the two risky moves when paying a deposit.","relearn":"Paying cash with no receipt, or to an unverified person, leaves you with no proof.","persona":"Meena","source":"deposit risks","scene":[{"id":"a","text":"Handing over cash and taking no receipt","trick":true},{"id":"b","text":"Paying by UPI and saving the record","trick":false},{"id":"c","text":"Paying a 'broker' you couldn't verify","trick":true},{"id":"d","text":"Getting a signed deposit slip","trick":false},{"id":"e","text":"Noting the amount and date together","trick":false}],"why":"Cash with no receipt and paying an unverified person leave you no proof; those are the risky moves."},
  {"id":"kr-1210","cat":"renting-and-consumer","type":"spot","hook":"Spot the two pressure tactics in this salesman's pitch.","relearn":"'Offer ends today' urgency and 'sign first, read later' are pressure tactics to resist.","persona":"any","source":"sales pressure","scene":[{"id":"a","text":"'This price is only for the next ten minutes'","trick":true},{"id":"b","text":"'Take your time to read the terms'","trick":false},{"id":"c","text":"'Just sign here; you can read it later'","trick":true},{"id":"d","text":"'Here's a copy to keep for yourself'","trick":false},{"id":"e","text":"'Ask me anything before you decide'","trick":false}],"why":"Fake ten-minute urgency and 'sign first, read later' are the pressure tactics to catch and resist."},
  {"id":"kr-1211","cat":"renting-and-consumer","type":"spot","hook":"Spot the two myths in this 'advice' about deposits.","relearn":"'Deposits are the landlord's once paid' and 'you can't ask for it back' are myths.","persona":"any","source":"deposit myths","scene":[{"id":"a","text":"'Once paid, the deposit is the landlord's money'","trick":true},{"id":"b","text":"'A deposit is returnable minus real damage'","trick":false},{"id":"c","text":"'Asking for it back will only get you trouble'","trick":true},{"id":"d","text":"'Move-in photos help you get it back'","trick":false},{"id":"e","text":"'An itemised reason is fair to ask for'","trick":false}],"why":"'The deposit is the landlord's' and 'don't dare ask' are the myths; a deposit is returnable and you can ask."},
  {"id":"kr-1212","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: a deposit is your money held in trust, not a parting gift. Sit with that?","prompt":"What feels true for you?","options":["It's still mine","I can ask for it back","Worth keeping proof"],"affirm":"A returnable deposit stays yours; documented condition and a fair ask are how you protect it.","relearn":"A deposit is your money held in trust, returnable minus documented damage.","persona":"any","source":"deposit mindset"},
  {"id":"kr-1213","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: keeping a bill or chat takes seconds but can settle a whole dispute later. Worth the habit?","prompt":"How do you see it?","options":["Worth it","I'll save proof","Small effort, big help"],"affirm":"A saved bill, photo or chat is quiet insurance; the habit costs little and protects a lot.","relearn":"Keeping receipts, photos and chats is a small habit with big protection.","persona":"any","source":"proof habit"},
  {"id":"kr-1214","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: asking 'what is this charge for?' isn't rude, it's how fair deals work. Agree?","prompt":"What do you think?","options":["It's fair to ask","I'll ask next time","Good deals welcome questions"],"affirm":"Honest sellers and landlords can explain their charges; asking is normal, not a fight.","relearn":"Asking what a charge is for is normal and fair, not rude.","persona":"any","source":"asking is fair"},
  {"id":"kr-1215","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: 'I'll read it before I sign' is a small line that saves a lot of trouble. Make it a habit?","prompt":"Where do you stand?","options":["Always read first","I can take my time","No rush to sign"],"affirm":"Reading before signing is yours to insist on; a fair deal can always wait for you to read.","relearn":"Reading before you sign is a habit worth keeping; a fair deal can wait.","persona":"any","source":"read first"},
  {"id":"kr-1216","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: knowing one consumer right makes you harder to brush off with 'your bad luck'. Feel that?","prompt":"What lands for you?","options":["I have rights","Harder to brush off","Knowing helps"],"affirm":"Even one known right shifts the conversation; 'your bad luck' loses its power when you know the route.","relearn":"Knowing your consumer rights makes 'your bad luck' easy to refuse.","persona":"any","source":"knowing helps"},
  {"id":"kr-1217","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: renting alone in a new city is hard, and asking for written terms is strength, not trouble. Agree?","prompt":"What feels right?","options":["It's strength","I can ask","Written is safer"],"affirm":"Asking for written terms protects you and the landlord; it's a fair, steady move, not making trouble.","relearn":"Asking for written terms when you rent is strength, not trouble.","persona":"Meena","source":"renting alone"},
  {"id":"kr-1218","cat":"renting-and-consumer","type":"reflect","hook":"Lensy: 'no refund' boards are everywhere, but a sign can't outrank the law on a faulty good. Sit with that?","prompt":"How do you read it?","options":["A sign isn't the law","I still have rights","Good to know"],"affirm":"A store notice can't cancel your rights on a genuinely defective good; the law still stands behind you.","relearn":"A 'no refund' sign can't override your rights on a defective good.","persona":"any","source":"sign vs law"},
  {"id":"kr-1219","cat":"renting-and-consumer","type":"role-play","hook":"Say it: the landlord won't return your deposit.","setup":"You moved out clean. The landlord keeps quiet about the deposit. What do you say?","yourLine":[{"text":"I left the room as it was; please return my deposit by the 10th, or share an itemised reason.","best":true},{"text":"It's fine if you keep some of it, I don't want any trouble."}],"persona":"any","source":"ask deposit","relearn":"Ask clearly for your deposit by a date, or for an itemised reason."},
  {"id":"kr-1220","cat":"renting-and-consumer","type":"role-play","hook":"Say it: the shop refuses to fix a faulty product.","setup":"The blender you bought last week won't start. The shop says 'not our problem'. What do you say?","yourLine":[{"text":"It's defective and under warranty; I'd like a repair or replacement, and here's the bill.","best":true},{"text":"Okay, maybe I used it wrong, I'll just manage."}],"persona":"any","source":"faulty product","relearn":"State the defect, show the bill, and ask for repair or replacement."},
  {"id":"kr-1221","cat":"renting-and-consumer","type":"role-play","hook":"Say it: a 'broker' wants money before you've seen the flat.","setup":"Someone asks for a token deposit by UPI for a flat you've only seen in photos. What do you say?","yourLine":[{"text":"I'll pay once I've seen the flat and met the owner, not before.","best":true},{"text":"Alright, I'll send the token now so I don't lose it."}],"persona":"any","source":"token deposit","relearn":"Don't pay for an unseen rental; see the flat and meet the owner first."},
  {"id":"kr-1222","cat":"renting-and-consumer","type":"role-play","hook":"Say it: a salesman pressures you to sign on the spot.","setup":"A salesman insists you sign a costly EMI now because 'the offer ends today'. What do you say?","yourLine":[{"text":"I don't sign anything I haven't read; I'll take the terms and decide later.","best":true},{"text":"Fine, I'll sign now and figure out the details afterwards."}],"persona":"any","source":"on-the-spot","relearn":"Don't sign under pressure; read the terms and decide in your own time."},
  {"id":"kr-1223","cat":"renting-and-consumer","type":"role-play","hook":"Say it: the landlord wants you to sign a blank agreement.","setup":"The rent and deposit boxes are empty. The landlord says 'I'll fill them later, just sign'. What do you say?","yourLine":[{"text":"Let's write in the rent and deposit now, then I'll sign, not before.","best":true},{"text":"Okay, I trust you'll fill it in correctly."}],"persona":"Meena","source":"blank sign","relearn":"Never sign blank boxes; get every amount written in first."},
  {"id":"kr-1224","cat":"renting-and-consumer","type":"role-play","hook":"Say it: an online order arrived broken and support keeps stalling.","setup":"The parcel came damaged; support keeps closing your ticket. What do you say in your complaint?","yourLine":[{"text":"The item arrived defective; here are photos and the order. I want a refund or replacement.","best":true},{"text":"It's a bit damaged but maybe I'll just keep it, it's too much effort."}],"persona":"any","source":"broken order","relearn":"State the defect, attach proof, and clearly ask for a refund or replacement."},
  {"id":"kr-1225","cat":"renting-and-consumer","type":"role-play","hook":"Say it: the PG owner adds a surprise charge as you leave.","setup":"On the way out, the PG owner demands an extra 'cleaning charge' with no receipt. What do you say?","yourLine":[{"text":"Please put this charge in writing with a receipt; then I'll consider it.","best":true},{"text":"Okay, here's the cash, I just want to leave quietly."}],"persona":"Meena","source":"surprise charge","relearn":"Ask for any surprise charge in writing with a receipt before paying."},
  {"id":"kr-1226","cat":"renting-and-consumer","type":"role-play","hook":"Say it: the landlord cites vague 'wear and tear' to cut your deposit.","setup":"The landlord wants to cut a big chunk for unspecified 'wear and tear'. What do you say?","yourLine":[{"text":"Could you give an itemised reason? Here are my move-in photos for comparison.","best":true},{"text":"It's okay, keep whatever you think is fair."}],"persona":"any","source":"wear and tear","relearn":"Ask for an itemised reason and compare it against your move-in photos."},
  {"id":"kr-1227","cat":"renting-and-consumer","type":"match","hook":"Match each unfair move to the fair alternative.","pairs":[{"left":"Sign a blank agreement","right":"Fill every amount first"},{"left":"Pay cash, take no receipt","right":"Get a receipt or pay by UPI"},{"left":"Deposit kept for any reason","right":"Itemised, documented deductions"},{"left":"Pay for an unseen flat","right":"View it and meet the owner"},{"left":"Sign under instant pressure","right":"Read the terms in your own time"}],"relearn":"Every pressured or risky move has a fair, safer alternative you can ask for.","persona":"any","source":"unfair to fair"},
  {"id":"kr-1260","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A probation period means the company can pay you nothing.\"","myth":{"un":"On probation the company can pay you nothing.","re":"Probation sets a review window, not free labour; work done during it still earns the agreed pay.","why":"A trial period tests fit, it doesn't cancel your wage."},"relearn":"Probation is a review window, not unpaid time; work done still earns your agreed pay.","persona":"Meena","source":"probation pay"},
  {"id":"kr-1261","cat":"rights-at-work","type":"strike-rewrite","hook":"\"If there's no written contract, the company owes you nothing.\"","myth":{"un":"No written contract means the company owes you nothing.","re":"Wages are owed for work actually done, with or without paper; a missing contract is their risk too.","why":"Pay follows the work, not just the paperwork."},"relearn":"Wages are owed for work done even without a written contract; a missing contract is a warning sign.","persona":"Meena","source":"no contract"},
  {"id":"kr-1262","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Asking for a payslip will mark you as a troublemaker.\"","myth":{"un":"Asking for a payslip marks you as a troublemaker.","re":"A payslip is a normal record of pay and deductions; asking for one is routine, not a complaint.","why":"A simple proof-of-pay request is your right, not rebellion."},"relearn":"Asking for a payslip is routine; it records your pay and deductions and protects you.","persona":"any","source":"payslip"},
  {"id":"kr-1263","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Gig and delivery workers are 'partners', so they have no rights at all.\"","myth":{"un":"Gig and delivery 'partners' have no rights at all.","re":"A label like 'partner' doesn't erase your earnings, agreed terms, or safety; those still stand.","why":"Renaming a worker doesn't delete what's owed to them."},"relearn":"Calling a gig worker a 'partner' doesn't erase agreed pay, terms or safety.","persona":"any","source":"gig partner label"},
  {"id":"kr-1264","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A company can hold your original certificates until you 'prove loyalty'.\"","myth":{"un":"A company can keep your original certificates to ensure loyalty.","re":"Your original documents are yours; holding them to trap you in a job is coercion, not policy.","why":"Your degree and ID belong to you, never to an employer."},"relearn":"Your original certificates are yours; an employer holding them to trap you is coercion.","persona":"Meena","source":"document holding"},
  {"id":"kr-1265","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Overtime is just part of the job; you can never expect to be paid for it.\"","myth":{"un":"Overtime is part of the job and is never paid extra.","re":"Hours beyond your agreed terms are extra work; agreed overtime should be counted and paid.","why":"Time worked is time owed, not a free gift."},"relearn":"Hours beyond your agreed terms are extra work and agreed overtime should be paid.","persona":"any","source":"overtime"},
  {"id":"kr-1266","cat":"rights-at-work","type":"strike-rewrite","hook":"\"Women can be paid less than men for the very same job.\"","myth":{"un":"Women can be paid less than men for the same job.","re":"Equal work earns equal pay; paying a woman less for the same role and output is unfair and not allowed.","why":"The wage follows the work, not the worker's gender."},"relearn":"Equal work earns equal pay; paying a woman less for the same job is not allowed.","persona":"Aarti","source":"equal pay"},
  {"id":"kr-1267","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A resignation 'penalty' can take your last month's full salary.\"","myth":{"un":"Resigning lets them keep your full last salary as penalty.","re":"You're still owed pay for days actually worked; a vague 'penalty' can't swallow earned wages whole.","why":"Leaving a job doesn't cancel pay you already earned."},"relearn":"You're owed pay for days actually worked; a vague exit 'penalty' can't take earned wages.","persona":"any","source":"exit penalty"},
  {"id":"kr-1268","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A 'training bond' lets them keep your stipend if you ever ask questions.\"","myth":{"un":"A training bond means they keep your stipend if you question anything.","re":"A bond has set terms; it can't be stretched to grab your stipend just for asking fair questions.","why":"A bond is a written deal, not a gag on your voice."},"relearn":"A training bond has set terms; it can't be stretched to take your stipend for asking questions.","persona":"Deepak","source":"training bond"},
  {"id":"kr-1269","cat":"rights-at-work","type":"strike-rewrite","hook":"\"A weekly day off is a favour the boss can cancel anytime.\"","myth":{"un":"A weekly day off is a favour the boss can cancel anytime.","re":"Rest and a weekly off are part of fair, safe work, not a gift handed out at someone's mood.","why":"Reasonable rest keeps work safe; it isn't charity."},"relearn":"A weekly day off and rest are part of fair, safe work, not a favour to cancel at whim.","persona":"Meena","source":"weekly off"},
  {"id":"kr-1270","cat":"rights-at-work","type":"sort","hook":"Sort: okay at work, or not okay?","items":[{"id":"a","text":"An offer letter stating pay, hours and role"},{"id":"b","text":"Wages held back to 'punish' a mistake"},{"id":"c","text":"A payslip each month"},{"id":"d","text":"Doing months of real work unpaid"},{"id":"e","text":"Agreed overtime that gets paid"},{"id":"f","text":"Originals kept so you can't leave"}],"bins":[{"id":"ok","label":"Okay","valence":"pos"},{"id":"not","label":"Not okay","valence":"neg"}],"key":{"a":"ok","b":"not","c":"ok","d":"not","e":"ok","f":"not"},"relearn":"Clear terms, a payslip and paid overtime are okay; withheld wages, unpaid real work and held originals are not.","persona":"any","source":"okay at work"},
  {"id":"kr-1271","cat":"rights-at-work","type":"sort","hook":"Sort: a real labour-rights fact, or a myth?","items":[{"id":"a","text":"Interns doing real work can be paid"},{"id":"b","text":"Juniors legally get zero rights"},{"id":"c","text":"A contract should state your role"},{"id":"d","text":"Cash-in-hand pay erases all rights"},{"id":"e","text":"Gig workers still have agreed terms"},{"id":"f","text":"Probation means you work for free"}],"bins":[{"id":"real","label":"Real fact","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Interns and gig workers have terms and a contract states your role; 'no rights for juniors, cash, or probation' are myths.","persona":"any","source":"labour facts"},
  {"id":"kr-1272","cat":"rights-at-work","type":"sort","hook":"Sort: belongs in a fair offer letter, or a red flag?","items":[{"id":"a","text":"Your monthly pay in figures"},{"id":"b","text":"'Salary: we'll decide later'"},{"id":"c","text":"Working hours and weekly off"},{"id":"d","text":"'No leaving for two years or pay us'"},{"id":"e","text":"Your job title and duties"},{"id":"f","text":"'Pay only if the client is happy'"}],"bins":[{"id":"fair","label":"Fair term","valence":"pos"},{"id":"flag","label":"Red flag","valence":"neg"}],"key":{"a":"fair","b":"flag","c":"fair","d":"flag","e":"fair","f":"flag"},"relearn":"A fair offer states pay, hours and role; vague pay, lock-in threats and 'pay only if client's happy' are red flags.","persona":"any","source":"offer letter terms"},
  {"id":"kr-1273","cat":"rights-at-work","type":"sort","hook":"Sort: which step protects you, or leaves you exposed?","items":[{"id":"a","text":"Get the offer in writing first"},{"id":"b","text":"Start on a verbal promise only"},{"id":"c","text":"Keep your own record of hours"},{"id":"d","text":"Trust 'we'll sort pay later'"},{"id":"e","text":"Save messages about your pay"},{"id":"f","text":"Hand over your only ID copy"}],"bins":[{"id":"safe","label":"Protects you","valence":"pos"},{"id":"risk","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Written terms, your own hour log and saved pay messages protect you; verbal-only deals and handing over IDs expose you.","persona":"Meena","source":"protect yourself at work"},
  {"id":"kr-1274","cat":"rights-at-work","type":"sort","hook":"Sort: who is still a protected worker?","items":[{"id":"a","text":"A paid intern doing real tasks"},{"id":"b","text":"A contract housekeeping worker"},{"id":"c","text":"A part-time evening shift worker"},{"id":"d","text":"A delivery rider called a 'partner'"},{"id":"e","text":"A trainee on a stipend"},{"id":"f","text":"A daily-wage site worker"}],"bins":[{"id":"yes","label":"Has rights","valence":"pos"},{"id":"also","label":"Also has rights","valence":"neutral"}],"key":{"a":"yes","b":"also","c":"yes","d":"also","e":"yes","f":"also"},"relearn":"Interns, contract, part-time, gig, trainee and daily-wage workers all have basic labour rights.","persona":"any","source":"who is protected"},
  {"id":"kr-1275","cat":"rights-at-work","type":"sort","hook":"Sort: fair internship, or exploitation in disguise?","items":[{"id":"a","text":"A set stipend paid on time"},{"id":"b","text":"Full unpaid work for many months"},{"id":"c","text":"Real learning and a mentor"},{"id":"d","text":"'Stipend' that never arrives"},{"id":"e","text":"Agreed hours in writing"},{"id":"f","text":"Doing a paid staff member's whole job free"}],"bins":[{"id":"fair","label":"Fair internship","valence":"pos"},{"id":"exploit","label":"Exploitation","valence":"neg"}],"key":{"a":"fair","b":"exploit","c":"fair","d":"exploit","e":"fair","f":"exploit"},"relearn":"A paid stipend, real learning and written hours make a fair internship; endless unpaid work or vanishing pay is exploitation.","persona":"Deepak","source":"internship vs exploitation"},
  {"id":"kr-1276","cat":"rights-at-work","type":"sort","hook":"Sort: a deduction that's fair, or one to question?","items":[{"id":"a","text":"Tax shown clearly on your payslip"},{"id":"b","text":"'Fine' for asking about late pay"},{"id":"c","text":"Provident fund you agreed to"},{"id":"d","text":"Cut for a 'uniform' you never got"},{"id":"e","text":"An advance you actually took"},{"id":"f","text":"Pay 'held' until you train a replacement"}],"bins":[{"id":"fair","label":"Fair deduction","valence":"pos"},{"id":"question","label":"Question it","valence":"uhoh"}],"key":{"a":"fair","b":"question","c":"fair","d":"question","e":"fair","f":"question"},"relearn":"Clear tax, agreed PF and a real advance are fair cuts; surprise 'fines', phantom charges and held pay are worth questioning.","persona":"any","source":"deductions"},
  {"id":"kr-1277","cat":"rights-at-work","type":"sort","hook":"Sort: counts as 'real work that deserves pay', or genuine free learning?","items":[{"id":"a","text":"Handling live customer orders alone"},{"id":"b","text":"A one-day shadowing visit"},{"id":"c","text":"Running the shop's daily accounts"},{"id":"d","text":"Watching a senior do a task once"},{"id":"e","text":"Filling staff shifts they're short on"},{"id":"f","text":"A short guided practice exercise"}],"bins":[{"id":"work","label":"Real work, pay owed","valence":"tell"},{"id":"learn","label":"Genuine learning","valence":"pos"}],"key":{"a":"work","b":"learn","c":"work","d":"learn","e":"work","f":"learn"},"relearn":"Doing the real job, accounts or covering shifts is paid work; shadowing or guided practice can be genuine learning.","persona":"any","source":"work vs learning"},
  {"id":"kr-1278","cat":"rights-at-work","type":"sort","hook":"Sort: a safe-conditions right, or just a nice-to-have?","items":[{"id":"a","text":"Clean drinking water on site"},{"id":"b","text":"A free luxury coffee machine"},{"id":"c","text":"Basic safety gear for risky work"},{"id":"d","text":"A bean-bag lounge"},{"id":"e","text":"A reasonable rest break"},{"id":"f","text":"Branded company hoodies"}],"bins":[{"id":"right","label":"Safety right","valence":"pos"},{"id":"perk","label":"Just a perk","valence":"neutral"}],"key":{"a":"right","b":"perk","c":"right","d":"perk","e":"right","f":"perk"},"relearn":"Water, safety gear and reasonable rest are part of safe work; lounges and freebies are just perks.","persona":"Meena","source":"safe conditions vs perks"},
  {"id":"kr-1279","cat":"rights-at-work","type":"sort","hook":"Sort: a worker myth to drop, or a fact to keep?","items":[{"id":"a","text":"Wages are owed for work done"},{"id":"b","text":"'Junior means no rights'"},{"id":"c","text":"Written terms protect both sides"},{"id":"d","text":"'Complaining always gets you fired'"},{"id":"e","text":"Equal work earns equal pay"},{"id":"f","text":"'Off-the-books pay erases rights'"}],"bins":[{"id":"keep","label":"Keep, it's a fact","valence":"pos"},{"id":"drop","label":"Drop, it's a myth","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Wages owed, written terms and equal pay are facts; 'juniors have no rights' and 'complaining gets you fired' are myths.","persona":"any","source":"myths vs facts"},
  {"id":"kr-1280","cat":"rights-at-work","type":"branch","hook":"Your 'unpaid trial' is now your full-time job and pay still hasn't started.","options":[{"text":"Put the agreed pay-start in writing and ask when it begins","consequence":"You turn a vague promise into a dated commitment.","outcome":"documented","best":true},{"text":"Keep waiting so you don't seem ungrateful","consequence":"Real work deserves pay; an endless unpaid 'trial' is exploitation."}],"debrief":"A full job done for months unpaid is exploitation; pin the pay-start in writing.","relearn":"Pin the pay-start in writing when an unpaid 'trial' has become your real job.","persona":"any","source":"trial became job"},
  {"id":"kr-1281","cat":"rights-at-work","type":"branch","hook":"Your employer will only return your original mark-sheets after two more years.","options":[{"text":"Ask for your originals back in writing; they're yours","consequence":"You assert ownership of your documents on record.","outcome":"asserted","best":true},{"text":"Leave them, it's not worth the fight","consequence":"Your originals are yours; holding them to trap you is coercion."}],"debrief":"Your certificates belong to you; a written request to return them is fair.","relearn":"Your original certificates are yours; ask in writing for them back.","persona":"Meena","source":"held originals"},
  {"id":"kr-1282","cat":"rights-at-work","type":"branch","hook":"A recruiter asks for a 'registration fee' before you can start the job.","options":[{"text":"Stop and verify; a real job pays you, you don't pay to work","consequence":"You spot a likely scam before losing money.","outcome":"safe","best":true},{"text":"Pay it quickly so you don't lose the offer","consequence":"A genuine employer pays you; up-front 'job fees' are a classic scam, not a real cost."}],"debrief":"You should never pay to be hired; up-front 'job fees' are a red flag.","relearn":"A real job pays you; never pay an up-front fee to start work.","persona":"any","source":"job fee scam"},
  {"id":"kr-1283","cat":"rights-at-work","type":"branch","hook":"You're told to sign a blank salary sheet 'for records' before your pay is fixed.","options":[{"text":"Decline and ask for the amount to be filled in first","consequence":"You avoid signing away an unknown figure.","outcome":"protected","best":true},{"text":"Sign it to keep things smooth","consequence":"A blank signed sheet can be filled with any number; insist the amount is written before you sign."}],"debrief":"Never sign a blank pay document; the figure must be filled in first.","relearn":"Don't sign a blank salary sheet; insist the amount is written in before you sign.","persona":"any","source":"blank sheet"},
  {"id":"kr-1284","cat":"rights-at-work","type":"branch","hook":"Your last salary is 'pending' weeks after you resigned, and calls go unanswered.","options":[{"text":"Send one written request listing days worked and amount owed","consequence":"You create a dated record of the claim.","outcome":"documented","best":true},{"text":"Assume it's gone and give up","consequence":"You're owed pay for days worked; a written request is how you claim it."}],"debrief":"Earned final wages are owed; a dated written request starts the claim.","relearn":"Send a clear written request for your earned final wages; you're owed them.","persona":"Meena","source":"final settlement"},
  {"id":"kr-1285","cat":"rights-at-work","type":"branch","hook":"Your manager adds night shifts your agreed terms never mentioned, with no extra pay.","options":[{"text":"Point to your agreed hours; ask extra shifts be agreed and paid","consequence":"You hold the line on your written terms.","outcome":"asserted","best":true},{"text":"Just do the shifts to stay liked","consequence":"Work beyond your terms should be agreed and paid; this is fair, not difficult."}],"debrief":"Shifts beyond your agreed hours should be agreed and paid; your terms are the anchor.","relearn":"Extra shifts beyond your agreed hours should be agreed and paid.","persona":"any","source":"surprise shifts"},
  {"id":"kr-1286","cat":"rights-at-work","type":"branch","hook":"You overhear that men in your exact role are paid more than the women doing the same work.","options":[{"text":"Calmly raise the gap; ask for the same pay for the same work","consequence":"You name an unfair gap on record.","outcome":"raised","best":true},{"text":"Decide it's just how things are","consequence":"Equal work earns equal pay; raising the gap is fair."}],"debrief":"Same role and output should earn the same pay; the gap is fair to question.","relearn":"Equal work earns equal pay; you can raise an unfair pay gap.","persona":"Aarti","source":"pay gap"},
  {"id":"kr-1287","cat":"rights-at-work","type":"branch","hook":"A friend says 'just take the cash-in-hand job, no contract, more money'.","options":[{"text":"Take it only with written proof of pay and terms","consequence":"You keep a record even in an informal setup.","outcome":"documented","best":true},{"text":"Go fully off the books with nothing in writing","consequence":"Cash pay keeps your rights, but no record makes them hard to claim."}],"debrief":"Cash work still carries rights; get written proof of pay and terms.","relearn":"Even for cash work, keep written proof of your pay and terms.","persona":"any","source":"cash job"},
  {"id":"kr-1288","cat":"rights-at-work","type":"branch","hook":"Your contract has a clause you don't understand and HR says 'just sign, everyone does'.","options":[{"text":"Ask what the clause means and get advice before signing","consequence":"You know what you're agreeing to first.","outcome":"careful","best":true},{"text":"Sign because everyone else did","consequence":"Questioning a clause protects you; 'everyone signs' isn't a reason."}],"debrief":"Understand each clause before signing; 'everyone does' is not a reason.","relearn":"Ask what a clause means and get advice before signing a contract.","persona":"any","source":"confusing clause"},
  {"id":"kr-1289","cat":"rights-at-work","type":"branch","hook":"You're injured on an unsafe site that had no basic safety gear.","options":[{"text":"Report the unsafe condition and record what happened","consequence":"You document a safety failure owed to every worker.","outcome":"documented","best":true},{"text":"Stay quiet so you're not blamed","consequence":"Safe conditions are owed to all; reporting the hazard is your right, not a fault."}],"debrief":"Safe conditions are owed to every worker; record and report a hazard.","relearn":"Report unsafe conditions and keep a record; safety is owed to every worker.","persona":"Meena","source":"unsafe site"},
  {"id":"kr-1290","cat":"rights-at-work","type":"branch","hook":"An app's 'partner' terms changed your delivery pay overnight with no notice.","options":[{"text":"Save screenshots of old and new terms before deciding","consequence":"You preserve evidence of what changed and when.","outcome":"evidence","best":true},{"text":"Delete the old app version and move on","consequence":"Saved screenshots protect you; clearing them throws away your evidence."}],"debrief":"When platform terms change, save the before-and-after as evidence first.","relearn":"Save screenshots of changed gig-app terms before acting; it's your evidence.","persona":"any","source":"platform terms change"},
  {"id":"kr-1291","cat":"rights-at-work","type":"branch","hook":"A woman is told 'this role isn't for you, it needs night travel', despite doing it well.","options":[{"text":"Ask for the real, job-based criteria for the role","consequence":"You surface whether the bar is the job or her gender.","outcome":"clarified","best":true},{"text":"Accept that some roles just aren't for women","consequence":"A role shouldn't be denied for being a woman; asking for criteria is fair."}],"debrief":"A role shouldn't be closed off for being a woman; ask for job-based criteria.","relearn":"Ask for job-based criteria when a role is denied for being a woman.","persona":"Aarti","source":"role denied to woman"},
  {"id":"kr-1292","cat":"rights-at-work","type":"branch","hook":"Your stipend is two months late and the office keeps saying 'next week'.","options":[{"text":"Put the owed amount and dates in one written follow-up","consequence":"You convert vague promises into a dated, written claim.","outcome":"documented","best":true},{"text":"Keep accepting 'next week' indefinitely","consequence":"A stipend for work done is owed; a written follow-up with dates is how you claim it."}],"debrief":"A promised stipend for work is owed; a written, dated follow-up moves it forward.","relearn":"Put owed stipend amounts and dates in a written follow-up.","persona":"Deepak","source":"late stipend"},
  {"id":"kr-1293","cat":"rights-at-work","type":"branch","hook":"You want to leave a job but fear a vague 'we'll ruin your reference' threat.","options":[{"text":"Resign in writing and keep your own record of good work","consequence":"You leave on a clean paper trail.","outcome":"clean-exit","best":true},{"text":"Stay trapped out of fear","consequence":"A written resignation and your records protect you; a vague threat shouldn't trap you."}],"debrief":"A clean written resignation and your own work records protect your exit.","relearn":"Resign in writing and keep records of your work; a vague threat shouldn't trap you.","persona":"any","source":"reference threat"},
  {"id":"kr-1294","cat":"rights-at-work","type":"match","hook":"Match the work document to what it does for you.","pairs":[{"left":"An offer letter","right":"States your pay, hours and role"},{"left":"A monthly payslip","right":"Records pay and any deductions"},{"left":"Your own hours log","right":"Backs up an overtime claim"},{"left":"A signed contract copy","right":"Holds both sides to agreed terms"},{"left":"Saved pay messages","right":"Evidence if pay is disputed"}],"relearn":"Offer letter, payslip, hours log, contract copy and saved messages each give you a different layer of proof.","persona":"any","source":"work documents"},
  {"id":"kr-1295","cat":"rights-at-work","type":"match","hook":"Match the work problem to a sensible first step.","pairs":[{"left":"Unpaid final salary","right":"Written request listing days owed"},{"left":"No contract given","right":"Ask for terms in writing"},{"left":"Originals held back","right":"Written request to return them"},{"left":"Unsafe site","right":"Report and record the hazard"},{"left":"Surprise unpaid overtime","right":"Point to your agreed hours"}],"relearn":"Each work problem has a calm first step, mostly a written request or pointing back to agreed terms.","persona":"any","source":"first steps"},
  {"id":"kr-1296","cat":"rights-at-work","type":"match","hook":"Match the worker to the rights they still hold.","pairs":[{"left":"A paid intern","right":"Fair stipend and agreed hours"},{"left":"A contract cleaner","right":"Pay for work and safe conditions"},{"left":"A gig 'partner' rider","right":"Agreed terms and earnings owed"},{"left":"A part-time worker","right":"Pay for the hours worked"},{"left":"A daily-wage worker","right":"Wages for the day's work done"}],"relearn":"Interns, contract, gig, part-time and daily-wage workers each keep real rights to pay and fair terms.","persona":"any","source":"who holds rights"},
  {"id":"kr-1297","cat":"rights-at-work","type":"match","hook":"Match the red-flag phrase to what it really signals.","pairs":[{"left":"'Pay a fee to start'","right":"Likely a job scam"},{"left":"'Salary decided later'","right":"Vague, unenforceable pay"},{"left":"'Sign this blank sheet'","right":"They could fill in any figure"},{"left":"'Give us your originals'","right":"An attempt to trap you"},{"left":"'Work free to prove yourself'","right":"Unpaid real work"}],"relearn":"Up-front fees, vague pay, blank sheets, held originals and 'work free to prove yourself' are all warning signs.","persona":"any","source":"red-flag phrases"},
  {"id":"kr-1298","cat":"rights-at-work","type":"match","hook":"Match the fair internship feature to why it matters.","pairs":[{"left":"A set stipend","right":"Pays you for real work done"},{"left":"Written hours","right":"Stops endless unpaid time"},{"left":"A named mentor","right":"Means real learning, not just labour"},{"left":"A clear end date","right":"It won't drag on forever"},{"left":"Defined tasks","right":"You're not just free staff cover"}],"relearn":"A stipend, written hours, a mentor, an end date and defined tasks are what make an internship fair, not free labour.","persona":"Deepak","source":"fair internship features"},
  {"id":"kr-1299","cat":"rights-at-work","type":"match","hook":"Match each pay term to its plain meaning.","pairs":[{"left":"Stipend","right":"Set pay for a trainee or intern"},{"left":"Deduction","right":"An amount cut from your pay"},{"left":"In-hand pay","right":"What lands after deductions"},{"left":"Overtime","right":"Hours beyond your agreed time"},{"left":"Notice period","right":"Agreed time before you can leave"}],"relearn":"Knowing stipend, deduction, in-hand pay, overtime and notice period helps you read any pay deal clearly.","persona":"any","source":"pay terms"},
  {"id":"kr-1300","cat":"rights-at-work","type":"match","hook":"Match the worker right to a true statement about it.","pairs":[{"left":"Right to be paid","right":"Owed for work actually done"},{"left":"Right to written terms","right":"Protects both you and the employer"},{"left":"Right to safe conditions","right":"Owed to every worker on site"},{"left":"Right to equal pay","right":"Same work earns the same pay"},{"left":"Right to your documents","right":"Originals always belong to you"}],"relearn":"Pay for work, written terms, safe conditions, equal pay and your own documents are rights that hold at any level.","persona":"any","source":"rights at a glance"},
  {"id":"kr-1301","cat":"rights-at-work","type":"reflect","hook":"Lensy: a junior who knows what an offer letter must say is hard to trick. Sit with that.","prompt":"What do you think?","options":["Yes","Hard to trick","I'd read it"],"affirm":"Knowing your terms should be in writing makes a vague verbal promise much easier to spot and refuse.","relearn":"Knowing what your terms should say in writing makes you harder to trick.","persona":"any","source":"knowing terms"},
  {"id":"kr-1302","cat":"rights-at-work","type":"reflect","hook":"Lensy: your time and work have real value, even on your first job. Feel that?","prompt":"What do you think?","options":["Yes","They have value","Always"],"affirm":"Your hours and effort are worth pay from day one; being new never means your work is free.","relearn":"Your time and work have real value, even on your very first job.","persona":"Deepak","source":"your work has value"},
  {"id":"kr-1303","cat":"rights-at-work","type":"reflect","hook":"Lensy: asking 'what's the pay, hours and role?' is a sign of self-respect, not rudeness. Agree?","prompt":"What do you think?","options":["Yes","Self-respect","Fair to ask"],"affirm":"Clear questions about pay, hours and role are normal and grown-up; a fair employer expects them.","relearn":"Asking about pay, hours and role is self-respect, not rudeness.","persona":"Aarti","source":"asking is okay"},
  {"id":"kr-1304","cat":"rights-at-work","type":"reflect","hook":"Lensy: you can be grateful for a chance and still expect to be paid for it. Hold both?","prompt":"What do you think?","options":["Yes","Both can be true","Paid and grateful"],"affirm":"Gratitude and fair pay aren't opposites; you can value an opportunity and still be paid for real work.","relearn":"You can be grateful for a chance and still expect fair pay for real work.","persona":"any","source":"grateful and paid"},
  {"id":"kr-1305","cat":"rights-at-work","type":"reflect","hook":"Lensy: keeping your own simple record of hours and pay is quiet power. Notice that?","prompt":"What do you think?","options":["Yes","Quiet power","I'll keep notes"],"affirm":"A plain log of your hours and pay turns 'he said, she said' into evidence whenever you need it.","relearn":"Keeping your own simple record of hours and pay is quiet power.","persona":"Meena","source":"keep records"},
  {"id":"kr-1306","cat":"rights-at-work","type":"reflect","hook":"Lensy: walking away from an offer that pays you nothing for real work is allowed. Believe it?","prompt":"What do you think?","options":["Yes","I can say no","It's allowed"],"affirm":"You're allowed to refuse a 'role' that wants your real work for free; saying no to exploitation is strength.","relearn":"You're allowed to walk away from an offer that wants real work for no pay.","persona":"any","source":"you can refuse"},
  {"id":"kr-1307","cat":"rights-at-work","type":"reflect","hook":"Lensy: being new doesn't mean being silent; you can ask a fair question on day one. True for you?","prompt":"What do you think?","options":["Yes","I can ask","From day one"],"affirm":"A first job still comes with a voice; a calm question about your terms is yours to ask from the start.","relearn":"Being new doesn't mean being silent; you can ask fair questions on day one.","persona":"any","source":"new but not silent"},
  {"id":"kr-1308","cat":"rights-at-work","type":"role-play","hook":"A 'mentor' says do three months of full work free 'and we'll see about pay later'.","setup":"Be warm but clear. Say:","yourLine":[{"text":"\"I'd love to learn here, but ongoing real work needs an agreed stipend from the start.\"","best":true},{"text":"Agree to it silently and hope pay shows up later"}],"relearn":"You can warmly insist that ongoing real work needs an agreed stipend from the start.","persona":"Deepak","source":"unpaid trial pushback"},
  {"id":"kr-1309","cat":"rights-at-work","type":"role-play","hook":"At your offer, there's still no mention of salary in writing.","setup":"Ask plainly. Say:","yourLine":[{"text":"\"Before I start, could we put the pay, hours and role in writing?\"","best":true},{"text":"Start anyway and avoid asking about money"}],"relearn":"You can plainly ask for pay, hours and role in writing before you start.","persona":"any","source":"ask for written terms"},
  {"id":"kr-1310","cat":"rights-at-work","type":"role-play","hook":"HR keeps your original degree certificate 'for safekeeping' and won't return it.","setup":"Stay calm and firm. Say:","yourLine":[{"text":"\"I'd like my original certificate back; I'm happy to give you a copy instead.\"","best":true},{"text":"Let them keep it so you don't seem distrustful"}],"relearn":"You can calmly ask for your original documents back and offer a copy instead.","persona":"Meena","source":"ask for originals"},
  {"id":"kr-1311","cat":"rights-at-work","type":"role-play","hook":"You're handed a blank salary form to sign before the amount is fixed.","setup":"Pause politely. Say:","yourLine":[{"text":"\"I'm glad to sign once the salary figure is filled in here.\"","best":true},{"text":"Sign the blank form to keep things moving"}],"relearn":"You can politely refuse to sign a blank pay form until the figure is filled in.","persona":"any","source":"blank form refusal"},
  {"id":"kr-1312","cat":"rights-at-work","type":"role-play","hook":"Your final salary is weeks late and the office keeps stalling.","setup":"Be polite but specific. Say:","yourLine":[{"text":"\"I worked through to the 20th; could you confirm when that final pay clears?\"","best":true},{"text":"Keep quiet and assume it's lost"}],"relearn":"You can politely ask for a clear date on your owed final pay.","persona":"Meena","source":"chase final pay"},
  {"id":"kr-1313","cat":"rights-at-work","type":"role-play","hook":"You're a woman and learn a male peer in your exact role earns more.","setup":"Raise it steadily. Say:","yourLine":[{"text":"\"We're in the same role with the same output; I'd like us to be on the same pay.\"","best":true},{"text":"Say nothing and accept the gap"}],"relearn":"You can steadily ask for equal pay when you do equal work.","persona":"Aarti","source":"raise pay gap"},
  {"id":"kr-1314","cat":"rights-at-work","type":"role-play","hook":"Your boss keeps piling on unpaid extra hours far beyond your agreed time.","setup":"Hold the line kindly. Say:","yourLine":[{"text":"\"I can do extra when it's agreed and paid; that's how I keep things sustainable.\"","best":true},{"text":"Take on all of it silently to seem keen"}],"relearn":"You can kindly hold the line that extra hours should be agreed and paid.","persona":"any","source":"extra hours line"},
  {"id":"kr-1315","cat":"rights-at-work","type":"spot","hook":"Spot the two red-flag lines in this 'job offer'.","scene":[{"id":"a","text":"'Your salary is 18,000 a month, paid by the 7th.'","trick":false},{"id":"b","text":"'Pay a 2,000 registration fee before you can join.'","trick":true},{"id":"c","text":"'Your hours are 9 to 6, with a weekly off.'","trick":false},{"id":"d","text":"'We'll hold your original degree till you finish a year.'","trick":true},{"id":"e","text":"'Here's your offer letter with the role written in.'","trick":false}],"why":"A join 'fee' and handing over your originals are the red flags; a real job pays you and your documents stay yours.","relearn":"Join fees and held originals are red flags.","persona":"any","source":"offer red flags"},
  {"id":"kr-1316","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that signal exploitation, not a fair internship.","scene":[{"id":"a","text":"'You'll get a set stipend each month.'","trick":false},{"id":"b","text":"'Work full days unpaid for six months to prove it.'","trick":true},{"id":"c","text":"'A mentor will guide your real learning.'","trick":false},{"id":"d","text":"'You'll cover a staff member's whole job for free.'","trick":true},{"id":"e","text":"'Your hours and end date are written down.'","trick":false}],"why":"Months of full unpaid work and covering a paid job free are the exploitation signs; a stipend and mentor are fair.","relearn":"Long unpaid work or free job-cover is exploitation.","persona":"Deepak","source":"internship red flags"},
  {"id":"kr-1317","cat":"rights-at-work","type":"spot","hook":"Spot the two unfair things hidden in this contract pitch.","scene":[{"id":"a","text":"'It lists your pay, hours and role clearly.'","trick":false},{"id":"b","text":"'Sign this blank page now; we'll add terms later.'","trick":true},{"id":"c","text":"'You get a copy of the signed contract.'","trick":false},{"id":"d","text":"'A penalty lets us keep your full last salary.'","trick":true},{"id":"e","text":"'Notice period is one month, stated upfront.'","trick":false}],"why":"A blank page to sign and a penalty that grabs your earned salary are the unfair parts; clear terms are fine.","relearn":"Blank pages and salary-grabbing penalties are unfair.","persona":"any","source":"contract red flags"},
  {"id":"kr-1318","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that wrongly deny a worker their rights.","scene":[{"id":"a","text":"'Interns doing real work can be paid a stipend.'","trick":false},{"id":"b","text":"'You're junior, so you simply have no rights.'","trick":true},{"id":"c","text":"'Wages are owed for the work you did.'","trick":false},{"id":"d","text":"'Cash-in-hand means you've got no rights at all.'","trick":true},{"id":"e","text":"'A contract protects both you and the company.'","trick":false}],"why":"'Juniors have no rights' and 'cash pay erases rights' are false; pay and contracts are real protections.","relearn":"'Juniors have no rights' and 'cash erases rights' are false.","persona":"any","source":"rights-denial flags"},
  {"id":"kr-1319","cat":"rights-at-work","type":"spot","hook":"Spot the two warning signs in this gig 'partner' offer.","scene":[{"id":"a","text":"'Your per-trip rate is shown before you accept.'","trick":false},{"id":"b","text":"'We can change your pay anytime with no notice.'","trick":true},{"id":"c","text":"'You'll get a weekly summary of earnings.'","trick":false},{"id":"d","text":"'Buy your own safety gear or you can't work; that's on you.'","trick":true},{"id":"e","text":"'You choose your own shift hours.'","trick":false}],"why":"Changing pay with no notice and dumping all safety costs on you are the warning signs; clear rates are fair.","relearn":"No-notice pay changes are a gig warning sign.","persona":"any","source":"gig offer flags"},
  {"id":"kr-1320","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that are exploitation dressed as 'opportunity'.","scene":[{"id":"a","text":"'You'll be paid for every hour you work here.'","trick":false},{"id":"b","text":"'Do this real client project free; exposure is your pay.'","trick":true},{"id":"c","text":"'We agree your role and hours in writing.'","trick":false},{"id":"d","text":"'Keep working unpaid; payment starts someday, maybe.'","trick":true},{"id":"e","text":"'Your stipend lands on a fixed date.'","trick":false}],"why":"'Exposure as pay' and endless 'someday' payment are exploitation; real work earns real pay.","relearn":"'Exposure' and 'someday' pay are exploitation.","persona":"any","source":"exposure pay flags"},
  {"id":"kr-1321","cat":"rights-at-work","type":"spot","hook":"Spot the two unfair lines aimed at a woman worker.","scene":[{"id":"a","text":"'You'll be judged on the same targets as everyone.'","trick":false},{"id":"b","text":"'We pay women a bit less for the same role.'","trick":true},{"id":"c","text":"'Your shift and duties are written in your letter.'","trick":false},{"id":"d","text":"'This promotion isn't for women, whatever the results.'","trick":true},{"id":"e","text":"'Safe conditions apply to every worker here.'","trick":false}],"why":"Paying women less and barring a promotion for being a woman are the unfair lines.","relearn":"Lower pay or a barred promotion for being a woman is unfair.","persona":"Aarti","source":"gender-at-work flags"},
  {"id":"kr-1322","cat":"rights-at-work","type":"spot","hook":"Spot the two lines that try to trap you in the job.","scene":[{"id":"a","text":"'Your notice period is one month, as agreed.'","trick":false},{"id":"b","text":"'We keep your originals until you give two years.'","trick":true},{"id":"c","text":"'You'll get a relieving letter when you leave.'","trick":false},{"id":"d","text":"'Quit early and we keep all your pending salary.'","trick":true},{"id":"e","text":"'Your pay clears on a fixed monthly date.'","trick":false}],"why":"Holding your originals and seizing all pending salary to stop you leaving are the traps.","relearn":"Held originals and seized salary to stop you leaving are traps.","persona":"any","source":"lock-in flags"},
  {"id":"kr-1350","type":"match","persona":"Farhan","source":"need to helpline","relearn":"181/1091 women in distress, 112 danger, 1930 cyber harm, 15100 legal aid, 1098 child at risk.","hook":"Match each need to the right helpline (India).","pairs":[{"left":"A woman in distress","right":"181 / 1091"},{"left":"Immediate danger","right":"112"},{"left":"Online fraud or abuse","right":"1930"},{"left":"Can't afford a lawyer","right":"NALSA 15100"},{"left":"A child at risk","right":"Childline 1098"}],"cat":"tools-and-help"},
  {"id":"kr-1351","type":"match","persona":"any","source":"need to route","relearn":"Each rights problem has a real route: an IC, the cyber portal, legal aid, or a consumer forum.","hook":"Match the problem to where its route begins.","pairs":[{"left":"Workplace harassment","right":"The Internal Committee"},{"left":"A scam message online","right":"cybercrime.gov.in"},{"left":"No money for a lawyer","right":"Free legal aid"},{"left":"A faulty product","right":"A consumer forum"},{"left":"Withheld wages","right":"The labour authority"}],"cat":"tools-and-help"},
  {"id":"kr-1352","type":"match","persona":"any","source":"resource to use","relearn":"Reliable rights resources: legal-aid clinics, the cyber portal, an IC, official sites, qualified help.","hook":"Match the situation to a reliable resource (not a forward).","pairs":[{"left":"Want free legal help","right":"A legal-aid clinic"},{"left":"Want to report cyber harm","right":"The official cyber portal"},{"left":"Harassed at college","right":"The campus IC"},{"left":"Unsure of the law","right":"A qualified lawyer"},{"left":"Need rights basics","right":"An official government site"}],"cat":"tools-and-help"},
  {"id":"kr-1353","type":"match","persona":"Farhan","source":"toolkit phrase","relearn":"A shareable card carries the route AND the helpline so a friend isn't left guessing.","hook":"Match each line on the rights card to what it gives a friend.","pairs":[{"left":"\"Harassment? Go to the IC\"","right":"A route to redress"},{"left":"\"Can't pay? NALSA 15100\"","right":"Free legal help"},{"left":"\"Scammed? 1930\"","right":"A cyber report line"},{"left":"\"In danger? 112\"","right":"Emergency help"},{"left":"\"This isn't legal advice\"","right":"An honest limit"}],"cat":"tools-and-help"},
  {"id":"kr-1354","type":"match","persona":"any","source":"myth to truth","relearn":"Junior staff have rights, harassment has redress, justice isn't only for the rich, scams are reportable.","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"\"Interns have no rights\"","right":"Basic labour rights apply"},{"left":"\"Just endure harassment\"","right":"There's a formal complaint route"},{"left":"\"Justice needs money\"","right":"Free legal aid exists"},{"left":"\"Scams can't be reported\"","right":"1930 and the cyber portal exist"},{"left":"\"You can't fight the system\"","right":"Real routes shift the odds"}],"cat":"tools-and-help"},
  {"id":"kr-1355","type":"match","persona":"Meena","source":"who can help","relearn":"Different helpers do different jobs: an IC, a legal-aid clinic, a consumer forum, a labour office, a counsellor.","hook":"Match each helper to what they handle.","pairs":[{"left":"Internal Committee","right":"Harassment complaints"},{"left":"Legal-aid clinic","right":"A free lawyer"},{"left":"Consumer forum","right":"A faulty-goods claim"},{"left":"Labour office","right":"Unpaid wages"},{"left":"Campus counsellor","right":"Support and pointing the way"}],"cat":"tools-and-help"},
  {"id":"kr-1356","type":"match","persona":"any","source":"first step","relearn":"A good first step is small: save proof, note dates, find the route, call a helpline, ask for legal aid.","hook":"Match each situation to a sensible first step.","pairs":[{"left":"Got blackmailed online","right":"Save proof, don't pay"},{"left":"Wages not paid","right":"Keep a record of work done"},{"left":"Deposit being withheld","right":"Show the written agreement"},{"left":"Unsure who to call","right":"Ring a helpline to be directed"},{"left":"Can't afford a lawyer","right":"Ask for free legal aid"}],"cat":"tools-and-help"},
  {"id":"kr-1357","type":"match","persona":"Farhan","source":"plain language","relearn":"A toolkit works only if it's plain: short lines, a number, no jargon, in the reader's language.","hook":"Match each toolkit habit to why it helps a working friend.","pairs":[{"left":"Short, plain lines","right":"Anyone can read it fast"},{"left":"A number on each line","right":"Help is one call away"},{"left":"No legal jargon","right":"It doesn't intimidate"},{"left":"In their own language","right":"It actually reaches them"},{"left":"\"Not legal advice\" noted","right":"It stays honest"}],"cat":"tools-and-help"},
  {"id":"kr-1358","type":"match","persona":"any","source":"reliable vs not","relearn":"Trust official portals, clinics and qualified help; not forwards, rumours or a stranger's guess.","hook":"Match each source to whether it's a reliable rights source.","pairs":[{"left":"The official cyber portal","right":"Reliable"},{"left":"A legal-aid clinic","right":"Trustworthy"},{"left":"A viral WhatsApp forward","right":"Not a source"},{"left":"A stranger's confident guess","right":"Unreliable"},{"left":"A qualified lawyer","right":"Worth asking"}],"cat":"tools-and-help"},
  {"id":"kr-1359","type":"sort","persona":"any","source":"reliable resources","relearn":"Official portals, clinics and an IC are reliable; forwards, rumours and guesses are not.","hook":"Sort: a reliable rights resource, or not?","items":[{"id":"a","text":"A legal-aid clinic"},{"id":"b","text":"A random WhatsApp forward"},{"id":"c","text":"The official cyber portal"},{"id":"d","text":"A stranger's confident guess"},{"id":"e","text":"The campus Internal Committee"},{"id":"f","text":"A rumour someone repeated"}],"bins":[{"id":"reliable","label":"Reliable","valence":"pos"},{"id":"not","label":"Not a source","valence":"neg"}],"key":{"a":"reliable","b":"not","c":"reliable","d":"not","e":"reliable","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-1360","type":"sort","persona":"any","source":"on the card","relearn":"The rights card carries real routes and helplines; not 'put up with it' or 'you have no options'.","hook":"Sort: belongs on the rights & helpline card, or not?","items":[{"id":"a","text":"The Internal Committee route"},{"id":"b","text":"\"Just put up with it\""},{"id":"c","text":"Free legal aid: NALSA 15100"},{"id":"d","text":"\"You have no options\""},{"id":"e","text":"Cyber harm: 1930"},{"id":"f","text":"\"Don't bother, you'll lose\""}],"bins":[{"id":"card","label":"On the card","valence":"pos"},{"id":"not","label":"Off the card","valence":"neg"}],"key":{"a":"card","b":"not","c":"card","d":"not","e":"card","f":"not"},"cat":"tools-and-help"},
  {"id":"kr-1361","type":"sort","persona":"Farhan","source":"helpline matching","relearn":"Match the harm to its line: danger 112, women 181/1091, cyber 1930, child 1098, legal aid 15100.","hook":"Sort each line into the kind of help it gives.","items":[{"id":"a","text":"112"},{"id":"b","text":"1930"},{"id":"c","text":"181 / 1091"},{"id":"d","text":"Childline 1098"},{"id":"e","text":"NALSA 15100"},{"id":"f","text":"The Internal Committee"}],"bins":[{"id":"danger","label":"Immediate danger","valence":"uhoh"},{"id":"report","label":"Report a harm","valence":"tell"},{"id":"support","label":"Get support/advice","valence":"pos"}],"key":{"a":"danger","b":"report","c":"report","d":"support","e":"support","f":"report"},"cat":"tools-and-help"},
  {"id":"kr-1362","type":"sort","persona":"any","source":"honest frame","relearn":"Honest framing: this is education, routes are real, no promises of a specific outcome.","hook":"Sort: an honest thing the toolkit says, or an overclaim to drop?","items":[{"id":"a","text":"\"Here are real routes you can use\""},{"id":"b","text":"\"You'll definitely win your case\""},{"id":"c","text":"\"This is education, not legal advice\""},{"id":"d","text":"\"You're guaranteed your money back\""},{"id":"e","text":"\"Free legal aid can help you\""},{"id":"f","text":"\"They'll surely be fired\""}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"overclaim","label":"Overclaim","valence":"neg"}],"key":{"a":"honest","b":"overclaim","c":"honest","d":"overclaim","e":"honest","f":"overclaim"},"cat":"tools-and-help"},
  {"id":"kr-1363","type":"sort","persona":"any","source":"good toolkit","relearn":"A good rights card is plain, has a number per line, names the route, and stays honest.","hook":"Sort: makes the rights card more useful, or less?","items":[{"id":"a","text":"Short, plain lines"},{"id":"b","text":"Heavy legal jargon"},{"id":"c","text":"A helpline on each line"},{"id":"d","text":"Vague 'go ask someone'"},{"id":"e","text":"Written in the reader's language"},{"id":"f","text":"A promise it can't keep"}],"bins":[{"id":"better","label":"More useful","valence":"pos"},{"id":"worse","label":"Less useful","valence":"neg"}],"key":{"a":"better","b":"worse","c":"better","d":"worse","e":"better","f":"worse"},"cat":"tools-and-help"},
  {"id":"kr-1364","type":"sort","persona":"Meena","source":"who to call","relearn":"Pick the line by need: danger 112, cyber harm 1930, free lawyer 15100, woman in distress 181.","hook":"Sort each situation to the line you'd reach for.","items":[{"id":"a","text":"A man is following you right now"},{"id":"b","text":"Someone is blackmailing you online"},{"id":"c","text":"You can't afford a lawyer"},{"id":"d","text":"You feel unsafe and alone as a woman"},{"id":"e","text":"A scam took your money online"},{"id":"f","text":"You're in real, present danger"}],"bins":[{"id":"emerg","label":"112 / 181","valence":"uhoh"},{"id":"cyber","label":"Cyber 1930","valence":"tell"},{"id":"aid","label":"Legal aid 15100","valence":"pos"}],"key":{"a":"emerg","b":"cyber","c":"aid","d":"emerg","e":"cyber","f":"emerg"},"cat":"tools-and-help"},
  {"id":"kr-1365","type":"sort","persona":"any","source":"share or skip","relearn":"Share verified routes and helplines; never forward unverified rumours or scary half-truths.","hook":"Sort: safe to share with a friend, or check first?","items":[{"id":"a","text":"The verified helpline list"},{"id":"b","text":"A forwarded 'new law' rumour"},{"id":"c","text":"The official cyber portal link"},{"id":"d","text":"A scary unverified screenshot"},{"id":"e","text":"A legal-aid clinic's address"},{"id":"f","text":"\"Someone said the rule changed\""}],"bins":[{"id":"share","label":"Safe to share","valence":"pos"},{"id":"check","label":"Check first","valence":"uhoh"}],"key":{"a":"share","b":"check","c":"share","d":"check","e":"share","f":"check"},"cat":"tools-and-help"},
  {"id":"kr-1366","type":"sort","persona":"any","source":"first move","relearn":"First moves that help: save proof, note dates, find the route, call a helpline, ask for legal aid.","hook":"Sort: a helpful first move, or a dead end?","items":[{"id":"a","text":"Save proof and note dates"},{"id":"b","text":"\"Just give up\""},{"id":"c","text":"Call a helpline to be directed"},{"id":"d","text":"\"Stay silent and hope\""},{"id":"e","text":"Ask a legal-aid clinic"},{"id":"f","text":"Pay the blackmailer to make it stop"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"deadend","label":"Dead end","valence":"neg"}],"key":{"a":"helps","b":"deadend","c":"helps","d":"deadend","e":"helps","f":"deadend"},"cat":"tools-and-help"},
  {"id":"kr-1367","type":"sort","persona":"Farhan","source":"toolkit pieces","relearn":"A working-youth toolkit needs the route, a helpline, plain words and the honest 'not legal advice' line.","hook":"Sort each piece: core to the toolkit, or clutter?","items":[{"id":"a","text":"The route to redress"},{"id":"b","text":"Long disclaimers nobody reads"},{"id":"c","text":"A helpline number"},{"id":"d","text":"Fancy legal Latin"},{"id":"e","text":"The honest 'not legal advice' note"},{"id":"f","text":"A wall of dense text"}],"bins":[{"id":"core","label":"Core","valence":"pos"},{"id":"clutter","label":"Clutter","valence":"neg"}],"key":{"a":"core","b":"clutter","c":"core","d":"clutter","e":"core","f":"clutter"},"cat":"tools-and-help"},
  {"id":"kr-1368","type":"reflect","persona":"any","source":"save it before you need it","relearn":"Save a helpline or legal-aid number now, so it's ready before any crisis hits.","hook":"Lensy: the time to find a helpline number is before you need it. Worth saving one today?","prompt":"What do you think?","options":["Yes","I'll save one","Good idea"],"affirm":"Having a helpline or legal-aid contact saved in advance means you're never scrambling in a crisis.","cat":"tools-and-help"},
  {"id":"kr-1369","type":"reflect","persona":"any","source":"the point","relearn":"Rights you know are rights you can use; that knowledge is real protection.","hook":"Lensy: rights you know are rights you can use. Worth carrying?","prompt":"What do you think?","options":["Yes","Know to use","Carry it"],"affirm":"Rights you know are rights you can use; that knowledge is one of the strongest protections you have.","cat":"tools-and-help"},
  {"id":"kr-1370","type":"reflect","persona":"any","source":"keep one","relearn":"Keep one route or line ready, and you have a real protection when you or a friend needs it.","hook":"Lensy: which helpline do you most want to keep in your head?","prompt":"Pick one.","options":["112 for danger","1930 for cyber harm","15100 for legal aid","181 for women in distress"],"affirm":"Keep that one ready, and you've got a real route the moment you, or someone near you, needs it.","cat":"tools-and-help"},
  {"id":"kr-1371","type":"reflect","persona":"Farhan","source":"who to share with","relearn":"A rights card helps most where help feels far; think of who could use yours.","hook":"Lensy: who in your life would the rights card help most?","prompt":"Picture one person.","options":["A younger sibling","A new colleague","A friend renting alone","A neighbour"],"affirm":"Holding a real person in mind is how a toolkit stops being a leaflet and starts being help.","cat":"tools-and-help"},
  {"id":"kr-1372","type":"reflect","persona":"any","source":"first instinct","relearn":"Your first instinct doesn't have to be perfect; finding the route is the win.","hook":"Lensy: if a rights problem hit tomorrow, what's your honest first instinct?","prompt":"No wrong answer.","options":["Freeze a moment","Call someone","Look it up","Save proof"],"affirm":"Whatever your first instinct, the win is finding the route next; you don't have to have it all figured out.","cat":"tools-and-help"},
  {"id":"kr-1373","type":"reflect","persona":"any","source":"asking is strength","relearn":"Asking for help is a skill, not a weakness; the toolkit exists so you don't go it alone.","hook":"Lensy: how does asking for help land for you, honestly?","prompt":"Sit with it.","options":["Hard for me","Getting easier","Fine by me","Depends"],"affirm":"However it lands, asking is a skill worth growing; the routes exist so nobody has to do this alone.","cat":"tools-and-help"},
  {"id":"kr-1374","type":"reflect","persona":"Meena","source":"rights as survival","relearn":"Knowing your rights when you're on your own is power; you carry it with you.","hook":"Lensy: working far from home, which protection means most to you?","prompt":"Pick what fits.","options":["Being paid fairly","A safe workplace","A roof I can keep","Knowing who to call"],"affirm":"Whatever you chose, knowing the right that protects it is yours to carry, wherever the work takes you.","cat":"tools-and-help"},
  {"id":"kr-1375","type":"reflect","persona":"any","source":"belief shift","relearn":"\"You can't fight the system\" is a belief, not a fact; real routes shift the odds.","hook":"Lensy: \"ordinary people just lose\", does that belief still hold for you?","prompt":"Be honest.","options":["Less than before","I'm not sure","No, there are routes","Old habit"],"affirm":"Loosening that belief is the real shift here; routes don't promise wins, but they genuinely change the odds.","cat":"tools-and-help"},
  {"id":"kr-1376","type":"reflect","persona":"Farhan","source":"plain language","relearn":"A toolkit only helps if people can read it; plain language is the whole game.","hook":"Lensy: what would make a rights card actually reach the people you work with?","prompt":"Think practically.","options":["Their language","Shorter lines","A number to call","Less jargon"],"affirm":"Whatever you picked, you're thinking like a toolkit-builder: reach first, polish later.","cat":"tools-and-help"},
  {"id":"kr-1377","type":"reflect","persona":"any","source":"trust a source","relearn":"You can choose what you trust: official portals and clinics over forwards and guesses.","hook":"Lensy: when a 'new rule' lands in your chats, what do you tend to do?","prompt":"No judgement.","options":["Forward it on","Check it first","Ignore it","Ask someone"],"affirm":"Whatever your habit, choosing to check a claim against an official source before acting is always solid.","cat":"tools-and-help"},
  {"id":"kr-1378","type":"reflect","persona":"any","source":"calm first step","relearn":"You don't have to solve it all at once; one calm first step is enough.","hook":"Lensy: facing a rights mess, what helps you take just the first step?","prompt":"What works for you?","options":["A list","One phone call","A friend with me","A deep breath"],"affirm":"Whatever steadies you, remember the bar is one step, not the whole battle; the route reveals itself as you go.","cat":"tools-and-help"},
  {"id":"kr-1379","type":"reflect","persona":"any","source":"helping others","relearn":"Knowing a route means you can point a friend to it; that's protection multiplied.","hook":"Lensy: which friend might you be the one to point toward help?","prompt":"Hold them in mind.","options":["Someone renting alone","A new joinee","Someone scammed","Not sure yet"],"affirm":"Being the person who knows the route is quiet power; what you've learned can protect more than just you.","cat":"tools-and-help"},
  {"id":"kr-1380","type":"reflect","persona":"any","source":"no false promise","relearn":"Honest help names real routes without promising a win; that honesty is a feature.","hook":"Lensy: does it bother you that the toolkit won't promise you'll win?","prompt":"Be honest.","options":["A little","No, I prefer honest","I get why","Mixed"],"affirm":"That honesty is the point: real routes, named plainly, with no false guarantee; that's help you can actually trust.","cat":"tools-and-help"},
  {"id":"kr-1381","type":"reflect","persona":"Aarti","source":"a say in your life","relearn":"Wanting a say in your own life is reason enough to learn your rights.","hook":"Lensy: what's the right you most want at your back as you start out?","prompt":"Pick one.","options":["A safe workplace","To be heard","To say no","To be paid fairly"],"affirm":"Whatever you chose, wanting a real say in your own life is exactly why these rights are worth knowing.","cat":"tools-and-help"},
  {"id":"kr-1382","type":"reflect","persona":"any","source":"keep it handy","relearn":"A toolkit only works if it's reachable; decide now where yours will live.","hook":"Lensy: where would you actually keep a rights & helpline card so it's there when needed?","prompt":"Make it real.","options":["Phone notes","Saved chat","On paper","Memorised"],"affirm":"Wherever it lives, the point is reachable-in-the-moment; a card you can find beats one you forgot you had.","cat":"tools-and-help"},
  {"id":"kr-1383","type":"reflect","persona":"any","source":"confidence","relearn":"Knowing the route lowers the fear; you're harder to exploit when you know where help is.","hook":"Lensy: knowing these routes now, does anything feel a bit less scary?","prompt":"Notice it.","options":["Yes, a bit","Not yet","A lot","Hard to say"],"affirm":"However it sits, knowing where help lives tends to shrink the fear; that's exactly what a toolkit is for.","cat":"tools-and-help"},
  {"id":"kr-1384","type":"reflect","persona":"any","source":"one to teach","relearn":"You remember what you teach; passing on one route locks it in for you too.","hook":"Lensy: if you taught one person one thing from this, what would it be?","prompt":"Choose one.","options":["A helpline","The IC route","Free legal aid","Save-your-proof"],"affirm":"Teaching it is how you keep it; the thing you'd pass on is probably the thing you'll never forget yourself.","cat":"tools-and-help"},
  {"id":"kr-1385","type":"reflect","persona":"any","source":"carry forward","relearn":"Work, harassment, renting, online: you know the rights and routes now. Carry one forward.","hook":"Lensy: across work, renting, harassment and online, which route do you most want to carry forward?","prompt":"Pick one.","options":["Rights at work","Harassment redress","Consumer & cyber routes","Free legal aid"],"affirm":"Carry that one forward and you step into adult life genuinely harder to exploit, and ready to help others too.","cat":"tools-and-help"},
  {"id":"kr-1386","type":"role-play","persona":"Farhan","source":"point a friend","relearn":"Point a friend to the route and a helpline so they don't face it alone.","hook":"A friend has a rights problem and doesn't know where to start.","setup":"Give them a first step. Say:","yourLine":[{"text":"\"Here's the route, and a helpline you can call: you don't have to figure it out alone.\"","best":true},{"text":"\"Just let it go, it's not worth the trouble.\""}],"cat":"tools-and-help"},
  {"id":"kr-1387","type":"role-play","persona":"any","source":"share the card","relearn":"Offer the rights card plainly; sharing the route is a kindness, not a lecture.","hook":"A new colleague seems unsure of their rights at work.","setup":"Offer the card without preaching. Say:","yourLine":[{"text":"\"I keep a little rights-and-helpline card: want me to share it? No pressure.\"","best":true},{"text":"\"You really should know all this already.\""}],"cat":"tools-and-help"},
  {"id":"kr-1388","type":"role-play","persona":"any","source":"check a forward","relearn":"Slow a scary forward down: check it against an official source before passing it on.","hook":"Someone forwards a scary 'the law just changed' message to your group.","setup":"Slow it down kindly. Say:","yourLine":[{"text":"\"Let's check that on the official site before we share it: forwards get things wrong a lot.\"","best":true},{"text":"\"Quick, forward it to everyone before it's too late!\""}],"cat":"tools-and-help"},
  {"id":"kr-1389","type":"role-play","persona":"Meena","source":"ask for legal aid","relearn":"You can ask plainly for free legal aid; not affording a lawyer is exactly what NALSA is for.","hook":"You can't afford a lawyer and feel embarrassed to say so.","setup":"At the legal-aid clinic, say:","yourLine":[{"text":"\"I can't afford a lawyer. I'd like to ask about free legal aid, please.\"","best":true},{"text":"\"Sorry, never mind, I'll just manage somehow.\""}],"cat":"tools-and-help"},
  {"id":"kr-1390","type":"role-play","persona":"any","source":"honest limit","relearn":"Be honest about limits: share the route, but say it's not legal advice.","hook":"A friend treats your tip like a guaranteed legal ruling.","setup":"Keep it honest. Say:","yourLine":[{"text":"\"This points you to the route, but I'm not a lawyer, so get proper legal help for your case.\"","best":true},{"text":"\"Yeah, trust me, you've definitely won already.\""}],"cat":"tools-and-help"},
  {"id":"kr-1391","type":"role-play","persona":"Aarti","source":"name the route","relearn":"Name the formal route out loud; harassment has a complaint process, not just silence.","hook":"A junior says she's being harassed but thinks nothing can be done.","setup":"Tell her the route exists. Say:","yourLine":[{"text":"\"There's a formal complaint route here, and it's confidential: you don't have to just endure it.\"","best":true},{"text":"\"That's just how jobs are, sadly. Put up with it.\""}],"cat":"tools-and-help"},
  {"id":"kr-1392","type":"role-play","persona":"any","source":"first call","relearn":"When unsure who handles it, a helpline can direct you; you don't need the perfect answer first.","hook":"You're frozen because you don't know which office handles your issue.","setup":"Make the simplest call. Say:","yourLine":[{"text":"\"I'll ring a helpline and ask them to point me to the right place: that's a fine first step.\"","best":true},{"text":"\"I'll wait until I somehow know exactly who to call.\""}],"cat":"tools-and-help"},
  {"id":"kr-1393","type":"spot","persona":"any","source":"accurate rights","relearn":"Junior staff have rights and free legal aid is real; 'no rights' and 'justice needs money' are false.","hook":"Spot the two FALSE lines on the rights card (tap the wrong ones).","scene":[{"id":"a","text":"\"Harassment has a formal complaint route\"","trick":false},{"id":"b","text":"\"You have no rights as a junior\"","trick":true},{"id":"c","text":"\"Free legal aid exists if you can't pay\"","trick":false},{"id":"d","text":"\"You need money and connections to be heard\"","trick":true},{"id":"e","text":"\"Online scams can be reported\"","trick":false}],"why":"'No rights as a junior' and 'you need money' are the myths; the rest are real routes.","cat":"tools-and-help"},
  {"id":"kr-1394","type":"spot","persona":"Farhan","source":"overclaim","relearn":"An honest toolkit names routes without promising wins; guarantees are the red flags.","hook":"Spot the two OVERCLAIMS a rights card should never make.","scene":[{"id":"a","text":"\"Here are real routes you can use\"","trick":false},{"id":"b","text":"\"You'll definitely win your case\"","trick":true},{"id":"c","text":"\"This is education, not legal advice\"","trick":false},{"id":"d","text":"\"You're guaranteed your money back\"","trick":true},{"id":"e","text":"\"Free legal aid can help if you can't pay\"","trick":false}],"why":"'You'll definitely win' and 'guaranteed your money back' promise outcomes nobody can; drop them.","cat":"tools-and-help"},
  {"id":"kr-1395","type":"spot","persona":"any","source":"bad source","relearn":"Trust official portals, clinics and qualified help; forwards and guesses are the red flags.","hook":"Spot the two UNRELIABLE sources to never trust for your rights.","scene":[{"id":"a","text":"The official cyber portal","trick":false},{"id":"b","text":"A viral WhatsApp forward","trick":true},{"id":"c","text":"A legal-aid clinic","trick":false},{"id":"d","text":"A stranger's confident guess","trick":true},{"id":"e","text":"A qualified lawyer","trick":false}],"why":"A viral forward and a stranger's guess aren't sources; the portal, clinic and lawyer are.","cat":"tools-and-help"},
  {"id":"kr-1396","type":"spot","persona":"any","source":"wrong helpline use","relearn":"Use the line that fits: danger 112, cyber 1930, legal aid 15100; mismatches waste precious time.","hook":"Spot the two lines that MISMATCH the need (tap the wrong pairings).","scene":[{"id":"a","text":"In danger right now → 112","trick":false},{"id":"b","text":"Online scam → ignore it","trick":true},{"id":"c","text":"Can't afford a lawyer → NALSA 15100","trick":false},{"id":"d","text":"Blackmailed online → pay them off","trick":true},{"id":"e","text":"Cyber harm → report at 1930","trick":false}],"why":"Ignoring a scam and paying a blackmailer are wrong moves; report online harm at 1930 instead.","cat":"tools-and-help"},
  {"id":"kr-1397","type":"spot","persona":"Meena","source":"bad first move","relearn":"Save proof, note dates, call a helpline; staying silent or paying off the abuser are the wrong moves.","hook":"Spot the two WRONG first moves in a rights problem.","scene":[{"id":"a","text":"Save proof and note the dates","trick":false},{"id":"b","text":"Stay silent and just hope","trick":true},{"id":"c","text":"Call a helpline to be directed","trick":false},{"id":"d","text":"Pay the blackmailer to make it stop","trick":true},{"id":"e","text":"Ask a legal-aid clinic","trick":false}],"why":"Silence and paying off a blackmailer trap you; saving proof and calling for help open the route.","cat":"tools-and-help"},
  {"id":"kr-1398","type":"spot","persona":"Farhan","source":"toolkit flaws","relearn":"A useful card is plain with a number per line; jargon and false promises are the flaws to cut.","hook":"Spot the two lines that WEAKEN the rights card.","scene":[{"id":"a","text":"Short, plain wording","trick":false},{"id":"b","text":"A wall of legal jargon","trick":true},{"id":"c","text":"A helpline on every line","trick":false},{"id":"d","text":"\"We guarantee you'll win\"","trick":true},{"id":"e","text":"Written in the reader's language","trick":false}],"why":"Jargon and a false guarantee make the card useless and dishonest; the rest make it work.","cat":"tools-and-help"},
  {"id":"kr-1399","type":"spot","persona":"any","source":"myth on the card","relearn":"Routes and helplines belong on the card; 'just endure it' and 'nothing can be done' are myths to cut.","hook":"Spot the two MYTHS that don't belong on a rights card.","scene":[{"id":"a","text":"\"Harassment? Go to the IC\"","trick":false},{"id":"b","text":"\"Just endure it, that's the job\"","trick":true},{"id":"c","text":"\"Can't pay? NALSA 15100\"","trick":false},{"id":"d","text":"\"Nothing can really be done\"","trick":true},{"id":"e","text":"\"Scammed? Report at 1930\"","trick":false}],"why":"'Just endure it' and 'nothing can be done' are the myths the card exists to replace.","cat":"tools-and-help"},
  {"id":"kr-1400","type":"spot","persona":"any","source":"share or not","relearn":"Share verified routes and official links; scary forwards and unverified screenshots get checked first.","hook":"Spot the two things you should NOT forward without checking.","scene":[{"id":"a","text":"The verified helpline list","trick":false},{"id":"b","text":"A 'the law just changed' rumour","trick":true},{"id":"c","text":"The official cyber portal link","trick":false},{"id":"d","text":"A scary unverified screenshot","trick":true},{"id":"e","text":"A legal-aid clinic's address","trick":false}],"why":"The rumour and the unverified screenshot could be false; check them before sharing.","cat":"tools-and-help"},
  {"id":"kr-1401","type":"spot","persona":"any","source":"honest helper","relearn":"A good helper names the route honestly; pretending to be a lawyer or promising a win is the red flag.","hook":"Spot the two things an honest rights-helper would never say.","scene":[{"id":"a","text":"\"Here's the route to start with\"","trick":false},{"id":"b","text":"\"Trust me, you've already won\"","trick":true},{"id":"c","text":"\"I'm not a lawyer: get proper help too\"","trick":false},{"id":"d","text":"\"Skip the helpline, just pay them\"","trick":true},{"id":"e","text":"\"A helpline can point you the right way\"","trick":false}],"why":"Promising a win and saying 'just pay them' are the dishonest, harmful lines; cut them.","cat":"tools-and-help"},
  {"id":"kr-1402","type":"branch","persona":"any","source":"where to start","relearn":"Unsure of the route? A helpline or legal-aid clinic will direct you.","hook":"You're not sure which authority handles your issue.","options":[{"text":"Ring a helpline; ask them to direct you","consequence":"You get pointed to the right place.","outcome":"directed","best":true},{"text":"Give up because it's confusing","consequence":"It stalls, but a helpline would have directed you."},{"text":"Act on a random WhatsApp 'tip'","consequence":"You risk a wrong turn; a forward is often just wrong."}],"debrief":"Unsure of the route? A helpline or legal-aid clinic can point you the right way.","cat":"tools-and-help"},
  {"id":"kr-1403","type":"branch","persona":"any","source":"can't afford a lawyer","relearn":"Can't afford a lawyer? Free legal aid (NALSA 15100) exists.","hook":"You have a real case but no money for a lawyer.","options":[{"text":"Ask about free legal aid via NALSA 15100","consequence":"You find a free route open to you.","outcome":"aided","best":true},{"text":"Drop the case, assuming justice costs money","consequence":"You give up a real right: aid was there."},{"text":"Borrow heavily for a private lawyer first","consequence":"You take on debt you may not have needed."}],"debrief":"Free legal aid (NALSA 15100) means a real case isn't only for those who can pay.","cat":"tools-and-help"},
  {"id":"kr-1404","type":"branch","persona":"any","source":"scary forward","relearn":"Check a scary 'new rule' against an official source before you act or share.","hook":"A forward claims a new rule strips a right you rely on.","options":[{"text":"Check it on the official government site first","consequence":"You find the real position before reacting.","outcome":"verified","best":true},{"text":"Panic and forward it to everyone","consequence":"You may spread a falsehood and scare people."},{"text":"Act on it at once as if it's true","consequence":"You could lose out trusting an unverified claim."}],"debrief":"Forwards get the law wrong often; verify against an official source first.","cat":"tools-and-help"},
  {"id":"kr-1405","type":"branch","persona":"Meena","source":"blackmail online","relearn":"For online blackmail: don't pay, preserve proof, report at 1930.","hook":"Someone threatens to leak a private photo unless you pay.","options":[{"text":"Don't pay; save the evidence and report at 1930","consequence":"You start the real route and keep your money.","outcome":"reported","best":true},{"text":"Pay quietly and hope they stop","consequence":"Paying rarely stops it; you lose money and proof."},{"text":"Delete everything in a panic","consequence":"You destroy the evidence a report needs."}],"debrief":"Image blackmail is on the abuser: don't pay, keep proof, report at 1930.","cat":"tools-and-help"},
  {"id":"kr-1406","type":"branch","persona":"any","source":"friend in trouble","relearn":"A friend in a rights mess needs the route and a helpline, not silence.","hook":"A friend tells you they're in a rights mess and feels stuck.","options":[{"text":"Share the route and a helpline they can call","consequence":"They get a real first step and feel less alone.","outcome":"helped","best":true},{"text":"Say 'you'll figure it out' and move on","consequence":"They stay stuck: a route would have helped."},{"text":"Promise you'll 'get them justice' yourself","consequence":"You over-promise what you can't guarantee."}],"debrief":"Point a friend to the route and a helpline; false promises aren't help.","cat":"tools-and-help"},
  {"id":"kr-1407","type":"branch","persona":"Aarti","source":"harassment route","relearn":"Workplace or college harassment has a confidential complaint route; you needn't just endure it.","hook":"You're being harassed at work and unsure anything can be done.","options":[{"text":"Use the confidential internal complaint route","consequence":"You start a real, protected process.","outcome":"filed","best":true},{"text":"Stay silent, assuming it's just the job","consequence":"Nothing changes, but a route existed."},{"text":"Quit on the spot with no record","consequence":"You lose the role and the route."}],"debrief":"Harassment is never the price of a job; the route is confidential and protected.","cat":"tools-and-help"},
  {"id":"kr-1408","type":"branch","persona":"any","source":"faulty goods","relearn":"A defective product has a real consumer route to refund or replacement.","hook":"A new product is defective and the seller shrugs.","options":[{"text":"Keep the bill; use the consumer-complaint route","consequence":"You open a path to refund or replacement.","outcome":"claimed","best":true},{"text":"Accept 'that's your bad luck' and bin it","consequence":"You give up a right: consumer law was on your side."},{"text":"Just warn friends and do nothing else","consequence":"Fair, but you skip the route that could fix it."}],"debrief":"Consumer law gives a real route for faulty goods; 'bad luck' is a myth.","cat":"tools-and-help"},
  {"id":"kr-1409","type":"strike-rewrite","persona":"any","source":"junior myth","relearn":"Rights apply at any level; being junior doesn't switch them off.","hook":"\"You're too junior to have any rights.\"","myth":{"un":"\"You're too junior to have any rights.\"","re":"Basic rights apply at every level: even interns and new joiners are protected.","why":"Rights attach to the person and the work, not to seniority; juniors are covered too."},"cat":"tools-and-help"},
  {"id":"kr-1410","type":"strike-rewrite","persona":"any","source":"money myth","relearn":"Free legal aid exists, so justice isn't only for those who can pay.","hook":"\"You need money and connections to claim anything.\"","myth":{"un":"\"You need money and connections to claim anything.\"","re":"Free legal aid is available through NALSA (15100) if you can't afford a lawyer.","why":"The right to free legal aid exists so cost isn't a wall; you can start without money or contacts."},"cat":"tools-and-help"},
  {"id":"kr-1411","type":"strike-rewrite","persona":"any","source":"reporting myth","relearn":"Online scams and abuse can be reported at 1930 and the cyber portal.","hook":"\"Nothing online can really be reported.\"","myth":{"un":"\"Nothing online can really be reported.\"","re":"Online fraud, abuse and blackmail can be reported at 1930 or cybercrime.gov.in.","why":"There's a real national route for cyber harm; fast reporting genuinely helps your case."},"cat":"tools-and-help"},
  {"id":"kr-1412","type":"strike-rewrite","persona":"any","source":"forward myth","relearn":"A confident forward isn't a source; verify rights claims against official sites.","hook":"\"If it's forwarded confidently, it must be the real rule.\"","myth":{"un":"\"If it's forwarded confidently, it must be the real rule.\"","re":"Forwards get the law wrong often: check the claim on an official source first.","why":"Confidence isn't accuracy; only official portals and qualified help are reliable for your rights."},"cat":"tools-and-help"},
  {"id":"kr-1413","type":"strike-rewrite","persona":"Aarti","source":"endure myth","relearn":"Harassment is never the price of a job; there's a real complaint route.","hook":"\"Harassment is just part of working life: endure it.\"","myth":{"un":"\"Harassment is just part of working life: endure it.\"","re":"Harassment has a formal, confidential complaint route; you don't have to endure it.","why":"A safe, dignified workplace is your right, and complaining in good faith is protected."},"cat":"tools-and-help"},
  {"id":"kr-1414","type":"strike-rewrite","persona":"any","source":"advice myth","relearn":"This is education, not legal advice; a real case needs qualified or free legal help.","hook":"\"A rights tip from a friend settles your case.\"","myth":{"un":"\"A rights tip from a friend settles your case.\"","re":"Tips point you to the route, but a real case needs qualified or free legal help.","why":"Only a lawyer can advise on your facts; the toolkit gives direction, not a ruling."},"cat":"tools-and-help"},
  {"id":"kr-1415","type":"strike-rewrite","persona":"any","source":"cost myth","relearn":"Asserting a right needn't be costly: free legal aid, helplines, and consumer forums keep fees low.","hook":"\"Standing up for a right always costs a fortune in lawyers and years in court.\"","myth":{"un":"\"Asserting a right always means expensive lawyers and years of court.\"","re":"Free legal aid, helplines, and low-cost forums like consumer commissions make many routes affordable and quick.","why":"Many first steps are free or cheap; cost is rarely the real barrier."},"cat":"tools-and-help"},
  {"id":"kr-1416","type":"strike-rewrite","persona":"Farhan","source":"toolkit myth","relearn":"A rights card helps only if it's plain and honest, with a real route and number.","hook":"\"A rights card must be long and full of legal terms to be useful.\"","myth":{"un":"\"A rights card has to be long and full of legal terms to be useful.\"","re":"The best card is short and plain, with a real route and a helpline on each line.","why":"People act on what they can read fast; jargon and length make a toolkit useless."},"cat":"tools-and-help"},
];

